COLLDATA("asabahur","ur",[[9648,"§۹۶۸۵ ۔ ابو جنید(2) (تصغیر ہے)(1)\nابن جندع از بنی عمرو بن مازن، ابن مندہ نے ان کا ذکر کر کے بطریق بلوی عمارہ بن زید سے بحوالہ عبد اللہ بن علاء زہری سے ایک روایت نقل کی ہے کہ میں نے سعید بن حبان سے بحوالہ ابو عنفوانہ بارقی سنا، وہ فرماتے ہیں: میں نے ابو جنید بن جندع مازنی کو فرماتے سنا کہ میں حنین کے دن ہوازن کی صبح نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ پھر حدیث(3) ذکر کی۔ یاد رہے بلوی متروک راوی ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۶۹) تجرید (۱۵۶/۸)\n(2) جامع المسانید (۵۰۵/۱۳)\n(3) اسد الغابہ (۴۰۵/۴)"}],[9649,"§۹۶۸۶ ۔ ابو جنیدہ فہری(1)\nمطین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا، ان سے طبرانی نے ان سے ابو نعیم نے نقل کیا ہے اور اسحاق بن عبد اللہ بن ابی فروہ کے طریق سے بحوالہ ابی جنیدہ فہری وہ اپنے والد سے وہ اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جس نے کسی پیاسے کو پانی پلا کر سیراب کیا اس کے لیے جنتی دروازے کھل جاتے ہیں”۔ (حدیث)(2) ابو موسیٰ اور ابو نعیم یہی مطین کی روایت محمد بن علی ملطی سے نقل کرتے ہیں۔ جابر بن کردی فرماتے ہیں: یزید بن ہارون، اسحاق بن خلیدہ سے مروی ہے۔ داؤد بن جراح نے بحوالہ ابو غسان، اسحاق سے روایت کرنے میں ان کی موافقت کی ہے۔ البتہ انہوں نے ابن خلید کہا: جس میں ہا نہیں ہے۔ ابو موسیٰ فرماتے ہیں: اسے ابو الشیخ نے دوسرے طرق سے نقل کیا تو ابن خلیدہ بحوالہ اپنے والد حذیفہ سے روایت کرنے کے الفاظ ذکر کیے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۷۷۰) تجرید (۱۵۶/۲)\n(2) المعجم الکبیر (۹۳۹/۲۲) مجمع الزوائد (۱۳۱/۳) کنز العمال (۱۶۳۸۲) جامع المسانید والسنن (۵۰۶/۱۳) اسد الغابہ (۴۰۶/۴)"}],[9650,"§۹۶۸۷ ۔ ابو جہاد انصاری سلمی(1)\nابو نعیم کا قول ہے: اہل مصر میں شمار ہوتے ہیں، اور ابن وہب کے طریق سے سعید بن عبد الرحمن سے فرمایا: انصار کے بنی سلمہ میں سے ایک شخص نے مجھے بتایا جس کا حوالہ وہ اپنے والد سے وہ اپنے دادا ابو جہاد سے، جو صحابی رسول ہیں، روایت کرنے کا دیتے ہیں کہ ان کے بیٹے نے ان سے کہا: ابا جان! کیا آپ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا اور ان کا ساتھ نصیب ہوا ہے؟ اگر مجھے وہ دور ملتا تو اللہ کی قسم! میں کیا کیا کر گزرتا، جس پر ان کے والد فرمانے لگے: اللہ سے ڈرو اور سیدھے رہو! اللہ کی قسم! جس کے قبضہ قدرت میں میری جان ہے! خندق کی رات میں آپ کے ساتھ تھا آپ فرما رہے تھے: “کون ایسا ہے جو ان کے ہاں جا کر اطلاع لائے، اللہ تعالیٰ قیامت کے روز اسے میرا رفیق بنائے گا۔” تو لوگوں میں سے کوئی بھی بھوک اور سردی کی شدت کی وجہ سے نہ اٹھ سکا یہاں تک کہ آپ نے تیسری بار فرمایا: “حذیفہ!”(2) دولابی نے یہ روایت اسی سند سے لکھی ہے۔","",{"fn":"(1) اسد الغابہ (ت: (۵۷۷۲) تجرید اسماء الصحابۃ (۱۵۶/۲)\n(2) اخرجہ مسلم، کتاب الجہاد والسیر، باب غزوۃ الاحزاب (الحدیث: (۴۶۱۶) مسند احمد (۳۹۲/۵) سنن بیہقی (۱۴۸/۹) دلائل النبوۃ (۴۴۹/۳) جامع المسانید والسنن (۵۰۷/۱۳)"}],[9651,"§۹۶۸۸ ۔ ابو جہم بن حذیفہ(1)\nبن غانم بن عامر بن عبد اللہ بن عبید بن عویج بن عدی بن کعب قرشی عدوی، امام بخاری رحمہ اللہ اور ایک جماعت کا کہنا ہے: ان کا نام عامر ہے۔ بقول بعض: عبید ہے، یہ زبیر بن بکار اور ابن سعد کا قول ہے، دونوں حضرات فرماتے ہیں: وہ مسلمانان فتح مکہ سے ہیں۔ بغوی بحوالہ مصعب لکھتے ہیں: قریش کے عمر رسیدہ اور بزرگ شخصیات میں سے ہیں۔ ابن مندہ نقل کرتے ہیں کہ ابو عاصم نے ابو جہم بن حذیفہ اور عبید بن حذیفہ میں فرق کیا ہے، زبیر فرماتے ہیں کہ قریش کے اکابر میں سے تھے اور ان چار افراد میں سے ایک تھے جن سے قریش نسب کا علم حاصل کرتے تھے۔ زبیر فرماتے ہیں: میرے چچا نے کہا کہ قریش کے عمر رسیدہ بوڑھے شخص تھے، جنہوں نے لمبی عمر پائی تعمیر کعبہ میں دو دفعہ شرکت کی ایک دفعہ جب قریش نے اس کی تعمیر کی دوسری بار جب سیدنا عبد اللہ بن زبیر رضی اللہ عنہ نے اسے تعمیر کیا۔ اور یہ ان چار افراد میں سے ایک ہیں جنہوں نے سیدنا عثمان غنی رضی اللہ عنہ کو دفن کیا تھا۔ بغوی رحمہ اللہ نے حفص بن غیاث کے طریق سے بحوالہ ہشام بن عروہ انہوں نے اپنے والد سے نقل کیا ہے، فرماتے ہیں: جب سیدنا عثمان رضی اللہ عنہ شہید کر دیئے گئے تو لوگوں نے آپ کی نماز جنازہ پڑھنی چاہی تو بلوائیوں نے رکاوٹ ڈال دی۔ تو ابو جہم بولے: ہٹ جاؤ! کیونکہ اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم نے ان کے لیے رحمت کا فیصلہ فرما دیا ہے۔ ابن ابی عاصم “کتاب الحکماء” میں بطریق عبد اللہ بن ولید، ابو بکر بن عبید اللہ بن ابی جہم سے روایت کرتے ہیں، فرمایا: میں نے ابو جہم سے سنا: میں نے جاہلیت میں ہی شراب ترک کر دی تھی۔ میں نے صرف اس وجہ سے شراب چھوڑی تھی کہ کہیں میری عقل میں فتور نہ آ جائے، اور دیگر جو اس کے مفاسد وغیرہ ہیں۔ صحیحین میں ان کا ذکر ثابت ہے جو بطریق عروہ سیدہ عائشہ رضی اللہ عنہا سے مروی ہے، فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک ریشمی اور بیل دار چادر پہنے نماز پڑھی، نماز کے بعد فرمایا: میری یہ چادر ابو جہم کے پاس لے جاؤ، اور میرے پاس ابو جہم کا یک رنگا اونی کپڑا لے آؤ، کیونکہ اس کے بیل بوٹوں کی وجہ سے میں ابھی ابھی نماز سے ان میں کھو گیا تھا۔ زبیر نے دوسری سند سے مرسلا نقل کیا ہے کہ نبی صلی اللہ علیہ وسلم کے پاس دو سیاہ کپڑے پیش کیے گئے۔ ان میں سے ایک آپ صلی اللہ علیہ وسلم نے پہن لیا اور دوسرا ابو جہم کی جانب بھیج دیا۔ پھر اس کے متعلق ابو جہم کو پیام بھیجا اور جو کپڑا پہنا تھا وہ ان کی طرف روانہ کر دیا اور جو ابو جہم کے پاس تھا جسے انہوں نے کئی بار پہن لیا تھا آپ صلی اللہ علیہ وسلم نے وہ کپڑا پہن لیا۔ ان کا ذکر حدیث فاطمہ بنت قیس سے بھی ثابت ہے۔ فرماتی ہیں: جب مجھے معاویہ اور ابو جہم نے پیام نکاح بھیجا تو میں نے نبی صلی اللہ علیہ وسلم سے مشورہ لیا، آپ صلی اللہ علیہ وسلم نے فرمایا: “ابو جہم کاندھے سے لاٹھی نہیں اتارتا” اور لوگ کہتے ہیں وہ عورتوں کو بڑا مارتے تھے۔ ابن سعد لکھتے ہیں: وہ بہت تیز گو تھے، سیدنا عمر رضی اللہ عنہ انہیں روکتے رہتے یہاں تک کہ انہوں نے اپنی زبان پر قابو پا لیا۔ ان کا ایک اور قصہ خالد بن برصاء کے حالات میں بھی گزر چکا ہے (کہ خالد بن برصاء نے مال میں سے بالوں کی ایک رسی اٹھانا چاہی، ابو جہم حضور صلی اللہ علیہ وسلم کی طرف نگران مقرر تھے منع کیا، وہ باز نہ آئے، انہوں نے زور کی لٹھ ماری جس سے گہرا زخم آ گیا اور آپ علیہ السلام نے فیصلہ فرمایا اور ابو جہم کو ہرجانہ دینا پڑا۔ [عامر تقی ندوی]) ابن المبارک “کتاب الزہد” میں عمر بن سعید بن ابی حسین کے طریق سے بحوالہ ابن سابط وغیرہ روایت کرتے ہیں کہ ابو جہم بن حذیفہ نے فرمایا: جنگ یرموک کے روز میں اپنے چچا زاد کو تلاش کرنے لگا، میرے پاس پانی کا بھرا مشکیزہ تھا، پھر قصہ ذکر کیا۔ بقول ابن سعد: امیر معاویہ رضی اللہ عنہ کی خلافت کے آخری سالوں میں فوت ہوئے۔ میں کہتا ہوں: سابقہ بات کی وجہ سے کہ وہ ابن زبیر رضی اللہ عنہ کی تعمیر کعبہ میں شریک ہوئے تھے، اگر وہ ثابت ہو تو معلوم ہوتا ہے وہ عبد اللہ بن زبیر رضی اللہ عنہ کی خلافت کے ابتدائی دور تک زندہ رہے۔ اس کی تائید اس روایت سے بھی ہوتی ہے جو امام اصمعی کے بھتیجے نے نوادر میں لکھی ہے۔ وہ اپنے چچا (اصمعی) سے وہ عیسیٰ بن عمر سے، فرمایا: ابو جہم امیر معاویہ رضی اللہ عنہ کے پاس آئے، پھر یزید کے پاس آئے اس کے بعد ان کا ابن زبیر رضی اللہ عنہ کے ساتھ پیش آمدہ ایک قصہ ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۷۳) تجرید اسماء الصحابۃ (۱۵۶/۲)"}],[9652,"§۹۶۸۹ ۔ ابو جہیم بن حارث(1)(2)\nبن صمہ بن عمرو بن عتیک بن عمرو بن مبذول بن عامر بن مالک بن نجار انصاری۔ بقول بعض ان کا نام کچھ اور ہے۔ ایک قول ہے: ان کا نام عبد اللہ بقول حارث بن صمہ، اسی کو ابن ابی حاتم نے راجح قرار دیا ہے۔ پھر ابن ابی حاتم نے عبد اللہ بن جہیم کا عنوان قائم کیا ہے اور ابو جہیم کو دو شخصیتیں قرار دیا ہے۔ ابن مندہ لکھتے ہیں: ابو جہیم بن حارث، انہیں عبد اللہ بن جہیم بن حارث بن صمہ بھی کہا جاتا ہے۔ یوں انہوں نے حارث بن صمہ کو ان کا دادا بنا دیا جو میرے گمان میں وہم ہے۔ ابن الاثیر رحمہ اللہ نے انہی کی پیروی کی اور اسے استیعاب کی جانب منسوب کیا ہے۔ حدیث ابو جہیم بن حارث صحیحین وغیرہ میں ہے۔ مالک کی روایت سے بحوالہ ابو نضر اشیر بن سعید مروی ہے کہ زید بن خالد نے انہیں ابو جہیم سے پوچھنے کے لیے بھیجا کہ کیا آپ نے نبی صلی اللہ علیہ وسلم سے نمازی کے سامنے سے گزرنے والے کے بارے میں کوئی حدیث سنی ہے کہ اسے کتنا گناہ ملتا ہے؟ (حدیث)(3) علم اسی روایت کو ابن عیینہ نے ابو نضر سے بحوالہ بشر نقل کیا ہے۔ فرماتے ہیں: مجھے ابو جہیم عبد اللہ بن جہیم نے زید بن خالد کی طرف بھیجا۔ یہ مقلوب (آگے پیچھے) ہیں۔ ابن ماجہ نے اسے روایت کیا ہے اور مسلم نے تعلیق میں اس کا ذکر کیا ہے۔ امام بخاری، ابو داؤد اور نسائی نے اعرج کے طریق سے موصولاً روایت کی ہے جو عمیر مولیٰ ابن عباس سے مروی ہے، فرمایا: میں اور عبد اللہ بن سیار ابو جہیم کے پاس آئے، انہوں نے فرمایا کہ نبی صلی اللہ علیہ وسلم بر عمل سے آ رہے تھے آپ صلی اللہ علیہ وسلم ہی نام سے ایک شخص ملا اس نے آپ کو سلام کیا۔ (حدیث)(4) جو سلام کا جواب دینے سے پہلے تمیم کے بارے میں ہے۔ اسے ابن لہیعہ نے عبد اللہ بن سیار سے بحوالہ ابو جہیم روایت کیا اور امام احمد رحمہ اللہ نے نقل کیا ہے۔ ابو جہیم کی ایک اور حدیث بھی ہے جسے امام احمد اور بغوی رحمہ اللہ نے یزید بن خصیفہ کے طریق سے بحوالہ مسلم بن سعید مولیٰ ابن الحضرمی، بحوالہ ابو جہیم انصاری روایت کیا ہے کہ دو آدمیوں کا ایک آیت میں اختلاف ہو گیا۔ (حدیث) اسی میں ہے: “(جھگڑنے کی کوئی بات نہیں) یہ قرآن سات حروف (لہجوں) میں نازل ہوا ہے”۔(5) ہم ان سے بشر بن سعید اور ان کے بھائی مسلم بن سعید بھی روایت کرتے ہیں، بقول بعض: ابی بن کعب رضی اللہ عنہ کے بھانجے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۷۷۵) تجرید اسماء الصحابۃ (۱۵۶/۲)\n(2) اسد الغابہ (۴۰۸/۴)\n(3) مسلم کتاب الصلوۃ (۵۰۱) مسلم کتاب الصلاۃ (۲۶۱، ۵۰۷) ابو داؤد کتاب الصلاۃ (۷۰۱) ترمذی ابواب الصلاۃ (۳۳۶) نسائی کتاب القبلۃ (۷۵۶) ابن ماجہ کتاب اقامۃ الصلاۃ (۹۴۵) مسند احمد (۱۶۹/۴)\n(4) بخاری کتاب التیمم (۳۳۷) مسلم کتاب الحیض (۸۲۰) ابو داؤد کتاب الطہارۃ (۳۲۹) کتاب الطہارۃ (۳۱۰) مسند احمد (۱۶۹/۴)\n(5) مسند احمد (۱۶۹/۴) مجمع الزوائد (۱۵۱/۷) کنز العمال (۳۰۸۲)"}],[9653,"§۹۶۹۰ ۔ ابو جہیمہ(1)\nعبد اللہ بن جہیم، اس سے پہلی والی شخصیت میں اور عبد اللہ نامی لوگوں میں تذکرہ گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۸۳) استیعاب (۲۹۴۲)"}],[9654,"§۹۶۹۱ ۔ ابو جہینہ انصاری\nثعلبی نے اپنی تفسیر میں اللہ تعالیٰ کے اس ارشاد (ناپ تول میں کمی کرنے والوں کے لیے خرابی ہے)(1) میں ان کا ذکر کیا ہے، پھر بطریق سدی نقل کیا ہے کہ ان کے دو پیمانے تھے ایک سے ناپ کر دیتے اور دوسرے سے لیتے تھے۔ جس پر یہ آیت نازل ہوئی خرابی ہے کمی کرنے والوں کے لیے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) سورۃ المطففین (۱)"}],[9655,"§۹۶۹۲ ۔ ابو الجون\nوہی قتادہ بن اعور ہیں قاف میں ذکر گزر چکا ہے۔ بغوی نے ان کا تذکرہ کیا ہے۔"],[9656,"§۹۶۹۳ ۔ ابو جیش بن ذی اللحیہ عامری کلابی\nسیف نے فتوح میں ان کا ذکر کر کے لکھا ہے: عراق داخل ہوتے وقت خالد بن ولید رضی اللہ عنہ نے جن بہادر صحابہ رضی اللہ عنہم کو ہوازن پر مقرر کیا تھا ان میں یہ بھی تھے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[9657,"§۹۶۹۴ ۔ ابو جعفر انصاری(1)\nکسی قبیلہ کی طرف منسوب نہیں۔ ان سے جو روایت منقول ہے اس سے پتہ چلتا ہے کہ وہ عہد نبوی میں پیدا ہوئے۔ جس کا محاصل یہ ہوا کہ وہ اس قسم میں شامل ہیں۔ چنانچہ ابن ابی شیبہ ثابت بن عبید کے طریق سے بحوالہ ابو جعفر انصاری روایت کرتے ہیں، فرمایا: میں نے صدیق اکبر رضی اللہ عنہ کو دیکھا تھا ان کی داڑھی اور سر کے بال ایسے (سرخ) تھے جیسے جھاؤ کی چنگاری ہوتی ہے۔ اور یہ بھی منقول ہے کہ وہ سیدنا عثمان رضی اللہ عنہ کی شہادت کے وقت موجود تھے، پھر اس کا قصہ ذکر کیا۔ ابو احمد نے ان میں اور ان “ابو جعفر انصاری میں فرق کیا ہے جو سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کرتے ہیں، بظاہر یہی ہے۔","",{"fn":"(1) تجرید (۱۵۵/۲)"}],[9658,"§۹۶۹۵ ۔ ابو جامع بن مخارق\nبن عبد اللہ ابن شداد ہلالی، ان کا نسب ان کے بھائی قبیصہ کے حالات، ناموں کے دوران گزر چکا ہے۔ انہوں نے زمانہ نبوت پایا ہے جب ان کی وفات ہوئی تو ابن ہمام سلولی نے ان کا مرثیہ کہا، یہ ابن کلبی کا قول ہے۔"],[9659,"§۹۶۹۶ ۔ ابو جبر\nفتوح عراق میں جسر ابی عبید ثقفی کے شہید ہیں۔ اس دن کے شہداء کے بارے میں ابو نجیم ثقفی نے جو مرثیہ قصائد کہے ہیں ان میں ان کا ذکر کیا ہے، وہ کہتے ہیں: “ابو جبر اپنے گھر کو خالی چھوڑ گئے جبکہ بیواؤں سے وہ گھر بھرا پڑا رہتا تھا۔”"],[9660,"§۹۶۹۷ ۔ ابو الجعد غطفانی(1)\nسالم کے والد۔ امام بخاری رحمہ اللہ وغیرہ کا قول ہے: ان کا نام رافع ہے۔ بقول بغوی نبی صلی اللہ علیہ وسلم کا زمانہ پایا ہے۔ میں کہتا ہوں: صحیح مسلم، کتاب التوبہ کے آخر میں عبد اللہ بن مسعود رضی اللہ عنہ سے ان کی روایت کردہ حدیث موجود ہے، نیز انہیں سیدنا علی بن ابی طالب رضی اللہ عنہ سے بھی روایت حاصل ہے۔ ان سے ان کا بیٹا سالم بن ابی الجعد اور شعبی روایت کرتے ہیں۔ حسن بن سفیان نے اپنی مسند میں ان کے حوالہ سے ایک مرسل حدیث نقل کی ہے۔ سند یوں ہے: احمد بن حنبل، حارث بن نعمان، ابو ہریرہ حمصی علی بن ابی طلحہ، سالم بن ابی الجعد ان کے سلسلہ سند میں ان کے والد سے مروی ہے، فرمایا: “نیکی بوسیدہ نہیں ہوتی اور گناہ بھلایا نہیں جاتا اور معصیت فنا نہیں ہوتی(2)”۔ میں کہتا ہوں: حارث بن نعمان ضعیف راوی ہے اور ان کے شیخ کا مجھے تعارف نہیں۔ یہی متن ابو نعیم نے مکرم بن عبد الرحمن کے طریق سے بحوالہ محمد بن عبد الملک، نافع سے سیدنا ابن عمر رضی اللہ عنہ کے حوالہ سے اس سے مکمل نقل کیا ہے۔ محمد بن عبد الملک کی محدثین نے تکذیب کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۶۱) تجرید (۱۵۵/۲)\n(2) المصنف لعبد الرزاق (۲۲۶۲) کنز العمال (۴۳۶۷۲، ۴۳۷۲۴) جمع الجوامع (۲۰۲۹۰) الاسماء والصفات للبیہقی (۷۹) اسد الغابہ (۴۰۳/۴)"}],[9661,"§۹۶۹۸ ۔ ابو الجعید\nدور نبوی نصیب ہوا ہے۔ جنگ یرموک میں ان کا ذکر آتا ہے۔ چنانچہ محمد بن عائذ، ولید سے وہ بنی ابی الجعد کے ایک بزرگ سے وہ اپنے والد ابو الجعد سے روایت کرتے ہیں۔ انہوں نے مسلمانوں کو مشورہ دیا کہ وہ رات کے وقت رومیوں پر حملہ کریں، چنانچہ انہوں نے قبول کر لیا اور رات کے وقت ان پر ہلہ بول دیا، اسی میں ہے کہ وادی میں آٹھ ہزار میں سے ایک کو دوسرے کا پتہ نہ چلا کہ اس کے ساتھ کیا ہوا۔"],[9662,"§۹۶۹۹ ۔ ابو الجلندی ازدی\nانہیں بھی دور نبوت نصیب ہوا، سیدنا عمر رضی اللہ عنہ کے پاس آئے تو ایک اعرابی نے ان سے پوچھا: تم کس قبیلے سے ہو، انہوں نے جواب دیا میں ان لوگوں میں سے ہوں جنہیں اللہ تعالیٰ نے اسلام سے سرفرازا ہے۔ ان کے ساتھ مہلب کے والد ابو صفرہ بھی تھے۔ ابن کلبی نے ان کا ذکر کیا ہے۔"],[9663,"§۹۷۰۰ ۔ ابو الجمعہ بن خالد\nبن عبید بن مسیر بن رباح بن سالم بن غاضرہ بن خبیثہ بن کعب خزاعی۔ دور نبوی پایا ہے۔ یہ کثیر بن عبد الرحمن خزاعی مشہور شاعر کے نانا ہیں۔ ان کا بھی ابن کلبی رحمہ اللہ نے ذکر کیا ہے۔"],[9664,"§۹۷۰۱ ۔ ابو جندل بن سہیل شامی(1)\nدور نبوی پایا ہے اور بلال رضی اللہ عنہ سے سماع ہے، ابو احمد حاکم نے ان کا ذکر کیا ہے ان میں اور قسم اوّل میں سابقہ شخصیت سیدنا ابو جندل بن سہیل بن عمرو میں تفریق کی ہے۔ عبد اللہ بن عبید کلائی کے طریق سے بحوالہ مکحول، حارث بن معاویہ کندی اور ابو جندل بن سہیل روایت کی ہے دونوں حضرات فرماتے ہیں: ہم نے موذن رسول سیدنا بلال رضی اللہ عنہ سے پوچھا.... پھر ان کی حدیث ذکر کی۔ حاکم فرماتے ہیں: اس میں بعض راویوں کا قول ہے: “ابو جندل سہیل بن عمرو جو بنی عامر بن لوی سے ہیں ان سے مروی ہے”۔ تو یہ وہم ہے اس واسطے کہ ابو جندل عامر جنگ یمامہ میں شہید ہو چکے جن کا زمانہ مکحول تابعی نے نہیں پایا۔ اور نہ انہوں نے بلال سے روایت کی ہے۔ ابن عساکر نے ابو احمد حاکم جیسی بات ذکر کی ہے کہ زبیر بن بکار نے دونوں میں فرق کیا ہے۔ وہ روایت جو اس قصہ میں ہے اس میں ابو جندل بن سہیل بن عمرو، جسے تمام نے اپنے فوائد میں ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۶۸) تجرید (۱۵۶/۲)"}],[9665,"§۹۷۰۲ ۔ ابو جندلہ\nامامہ کے شوہر۔ انہیں بھی دور نبوت میسر ہے۔ حدیث عبد اللہ بن قرط شمالی سیدنا عمر رضی اللہ عنہ کی طرف سے حمص کے گورنر میں ان کا ذکر آتا ہے کتاب النکاح میں ابو الشیخ نے مسکین بن میمون مؤذن کے طریق سے بحوالہ عروہ بن رویم روایت کی ہے کہ عبد اللہ بن قرط شمالی ایک رات حمص میں گشت کر رہے تھے وہ سیدنا عمر رضی اللہ عنہ کی طرف سے گورنر تھے، ان کے پاس سے ایک برات گزری لوگ اس کے سامنے آگ جلا رہے تھے، آپ نے انہیں درہ مارا تو وہ دلہن کو چھوڑ کر منتشر ہو گئے۔ صبح ہوئی تو منبر پر تشریف لے جا کر حمد و ثنا کے بعد فرمایا: ابو جندلہ نے امامہ سے نکاح کیا اور چند مٹھی کھانا بطور ولیمہ تیار کیا، اللہ تعالیٰ ابو جندلہ پر رحم فرمائے اور امامہ پر سلام بھیجے۔ اللہ تعالیٰ تمہاری دلہن پر لعنت کرے گزشتہ رات لوگوں نے (مجوسی) کافروں کی مشابہت میں آگ جلائی اللہ ہی ان کی روشنی ختم کرنے والا ہے۔ فرماتے ہیں: عبد اللہ بن قرط صحابی ہیں۔"],[9666,"§۹۷۰۳ ۔ ابو جھراء\nمخضرمی ہیں، مہمات میں ان کا ذکر آئے گا۔ مشہور یہ ہے کہ وہ ابن جھراء ہیں۔ بقول بعض: ان کا نام عبد اللہ ہے۔"],[9667,"§۹۷۰۴ ۔ ابو جھراء (دوسرے)\nانہیں زمانہ نبوت میسر ہے، سیدنا عمر رضی اللہ عنہ کے امین تھے۔ ابو نجیم ثقفی کے حالات میں قسم اوّل میں ان کا ذکر ہوگا۔"],[9668,"§۹۷۰۵ ۔ ابو جُبیر کندی(1)(2)\nابن الاثیر نے ان میں اور جبیر بن نفیر کے والد میں فرق کیا ہے۔ ذہبی رحمہ اللہ نے بھی ان کا اتباع کیا ہے۔ فرماتے ہیں: ابو جبیر کندی کی وضو کے متعلق ایک حدیث ہے۔ نیز فرماتے ہیں: ابو جبیر حضرمی کی ایک حدیث ہے، اسی میں ان کا آنا مذکور ہے۔ دونوں ایک ہیں، اس واسطے کہ حدیث مذکورہ ابو احمد حاکم نے “کئی” میں اور ابن حبان نے اپنی صحیح میں بطریق معاویہ بن صالح، عبد الرحمن بن جبیر بن نفیر سے روایت کی ہے کہ ابو جبیر نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔ پھر ان کی حدیث ذکر کی، اسی میں آپ کے وضو کا ذکر ملتا ہے کہ آپ نے منہ (میں پانی ڈالنے) سے آغاز کیا جس پر نبی صلی اللہ علیہ وسلم نے تنبیہ کرتے ہوئے فرمایا: “منہ سے ابتدا نہ کرو”۔(3) ناموں میں حرف نون کے دوران نفیر میں یہ روایت گزر چکی ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۵۵) استیعاب (۲۹۳۱) تجرید (۱۵۴/۲)\n(2) تجرید (۱۵۴/۲)\n(3) السنن الکبریٰ (۴۶/۱)"}],[9669,"§۹۷۰۶ ۔ ابو الجدعاء(1)\nطبری اور دولابی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، اور دونوں نے خالد الحذاء، سے بحوالہ عبد اللہ بن شقیق، ابو الجدعاء سے مرفوع روایت نقل کی ہے: “میری امت کے ایک شخص کی شفاعت کرنے کی وجہ سے بنی تمیم سے زیادہ لوگ جنت میں داخل ہوں گے۔”(2) ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے جو حذف کی وجہ سے غلطی ہے۔ روایت ابن ابی الجدعاء سے ہے لفظ ابن رہ گیا۔ ان کی درست حدیث سنن ترمذی میں ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۵۳) تجرید (۱۵۴/۲)\n(2) ترمذی کتاب صفۃ القیامۃ باب (۱۲) حدیث (۲۸۳۸) ابن ماجہ کتاب الزہد (۴۳/۶) جامع المسانید (۴۹۸/۱۳)"}],[9670,"§۹۷۰۷ ۔ ابو جریر(1)\nحاء بے نقطی میں تذکرہ ہوگا۔","",{"fn":"(1) اسد الغابہ (۵۷۵۴)"}],[9671,"§۹۷۰۸ ۔ ابو جسرہ(1)\nابو بکر بن علی نے ان کا ذکر کیا اور ابو موسیٰ نے اپنے استدراک میں ذکر کیا ہے اور بطریق ابو بکر بن ابی عاصم، پھر داؤد بن مساور کی روایت سے بحوالہ معقل بن ہمام روایت کی ہے کہ میں نے ابو جسرہ کو فرماتے سنا: “ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں پہنچے تو آپ نے ہمیں کدو، ملکے اور تارکول ملے لیے برتن میں مشروبات پینے سے منع فرمایا تھا”۔(2) یہ بھی غلطی لفظی خطا سے پیدا ہوئی۔ اصل میں ابو خیر (خا نقطے والی اور یاء ہے) یہ صباحی ہیں جن کا تعلق عبد القیس سے ہے۔ درست نام آ رہا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۵۸)\n(2) الاحاد والمثانی (۳۱۲/۳)"}],[9672,"§۹۷۰۹ ۔ ابو جمعہ(1)(2)\nان سے عبد اللہ بن عوف رملی ایک حدیث کی روایت کرتے ہیں۔ دولابی نے کنی میں ان میں اور ابو جمعہ بن سبع میں فرق کیا ہے جبکہ دونوں ایک ہی شخص کے نام ہیں۔ جو حدیث انہوں نے ذکر کی وہ پہلے نام کے حوالہ سے مشہور ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۶۴) استیعاب (۲۹۳۷) تجرید (۱۵۵/۲)\n(2) اسد الغابہ (۵۷۶۴) استیعاب (۲۹۳۷) تجرید (۱۵۵/۲)"}],[9673,"§۹۷۱۰ ۔ ابو جمل(1)\nابن عبد البر نے کنیتوں میں حرف جیم کے آخر میں ان کا ذکر کیا ہے جس کا حوالہ عباس دوری نے بحوالہ یحییٰ بن معین دیا ہے، فرماتے ہیں: ابو جمل صحابی رسول ہیں۔ ان کا نام ہلال بن حارث ہے۔ حمص میں رہتے تھے مجھے ان کی اولاد کا ایک لڑکا وہاں نظر پڑا ہے۔ یہ یحییٰ کا قول ہے۔ ابن فتحون وغیرہ نے اس سلسلہ میں ان کا تعاقب کیا ہے۔ علماء فرماتے ہیں: اہل علم کے ہاں اس بارے میں کوئی اختلاف نہیں کہ ہلال بن حارث کی کنیت ابو حمراء تھی۔(2) اور ابو جمل کنیت والا کوئی شخص صحابی نہیں۔ وہم ابو عمر کی طرف سے پیدا ہوا ہے نہ عباس کی طرف سے۔ تاریخ ابن معین میں عباس کی روایت موجود ہے، ایسا ہی ابو بشر دولابی، محمد بن مخلد، احمد بن شاہین، ابو حفص کے والد اور ابو سعید بن اعرابی وغیرہ نے روایت کی ہے سب عباس دوری سے روایت کرتے ہیں۔ ابو عمر نے حاء بے نقطی میں ان کا صحیح نام لکھا ہے۔ فرماتے ہیں: ابو حمراء کا نام ہلال ہے۔ اس سلسلہ میں ان کا ایک اور وہم ہے اس لیے کہ انہوں نے ناموں میں لکھا ہے، ہلال بن حمراء یوں کنیت کو ان کے والد کا نام قرار دے دیا۔","",{"fn":"(1) اسد الغابہ (۵۷۷۷) تجرید (۱۵۶/۲)\n(2) جامع المسانید (۵۰۸/۱۳) اسد الغابہ (۴۰۸/۴) الجرح والتعدیل (۵۲۹/۳)"}],[9674,"§۹۷۱۱ ۔ ابو جہیمہ(1)\nذہبی نے تجرید میں بحوالہ ابو موسیٰ ان کا ذکر کیا ہے اور انہوں نے بطریق محمد بن حسن بن نقاش مقری، حسین بن ادریس، خالد بن ہیاج کے سلسلہ سے نقل کیا ہے وہ اپنے والد سے بحوالہ سفیان ثوری، منصور سے بحوالہ فضیل بن عمرو، ابو العالیہ سے بحوالہ ابو جہیمہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنی مجلس کے آخر میں کہا کرتے تھے: ((سُبْحَانَکَ اللَّهُمَّ وَبِحَمْدِکَ))(2) (حدیث) اللہ ابو موسیٰ فرماتے ہیں: اسے ربیع بن انس نے ابو العالیہ سے بحوالہ ابی بن کعب نقل کیا ہے۔ اور جریر نے فضیل بن عمرو سے بحوالہ زیاد بن حصین، معاویہ سے روایت کی ہے۔ میں کہتا ہوں: اس میں اسی طرح ہے، جبکہ وہ ابو العالیہ سے مروی ہے نہ کہ معاویہ سے۔ چنانچہ ابن ابی حاتم نے “علل” میں بحوالہ اپنے والد نقل کیا ہے کہ زیاد بن حصین نے اسے ابو العالیہ سے مرسلاً روایت کیا ہے۔ زیاد بن حصین کی کنیت ابو حمیمہ تھی انہی نے ابو العالیہ سے یہ حدیث روایت کی ہے، پہلی سند میں ان کا یہ کہنا کہ “ابو العالیہ بحوالہ ابی بن کعب” یہ غلط ہے۔ درست عن ابی العالیہ عمن رافع بن خدیج ہے جیسا کہ مستدرک میں حاکم نے اسے نقل کیا ہے۔ اس میں رافع بن خدیج کا ذکر غلط ہے، صحیح مرسل ہے۔ جیسا کہ ابن ابی حاتم نے بحوالہ اپنے والد لکھا ہے اس کو ابو نعیم فضل بن دکین نے بحوالہ ثوری پہلی سند سے روایت کیا ہے۔ لیکن اس میں ابو العالیہ سے آگے نہیں بڑھے۔ دوسروں کی نسبت ابو نعیم زیادہ مستند ہیں۔ وباللہ التوفیق","",{"fn":"(1) تجرید (۱۵۶/۲)\n(2) المعجم الکبیر (۱۷۲۱/۲)"}],[9675,"§۹۷۱۲ ۔ ابو حابس جہنی\nطبری نے ان کا صحابہ رضی اللہ عنہم میں ذکر کیا ہے اور ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[9676,"§۹۷۱۳ ۔ ابو حاتم مزنی حجازی(1)\nامام ترمذی، ابن حبان اور ابن السکن کا قول ہے: صحابی ہیں۔ ترمذی نے ان کی حدیث ذکر کرنے کے بعد اس کا اضافہ کیا ہے کہ کفو میں شادی کرانے کے بارے میں وہ روایت ہے، اس میں ان کا ذکر ہے جب تم سے وہ شخص رشتہ لینے آئے جس کی دینداری تمہیں پسند ہو۔۔۔۔ (حدیث)(2) مجھے اس کے علاوہ ان کی کوئی روایت معلوم نہیں۔ ابو داؤد نے ان کی حدیث مراسیل میں شامل کی ہے۔ یہ ان کے نزدیک تابعی ہیں۔ ابن ابی حاتم نے ابو زرعہ سے روایت کی ہے، فرمایا: مجھے ان کا صحابی ہونا معلوم نہیں اور صرف اسی روایت کا علم ہے۔ ابن قانع کا گمان ہے کہ ان کا نام عقیل بن مقرن ہے، اور عقیل مذکور کے حالات میں میں نے ان کے وہم کی وضاحت کر دی ہے۔ ان سے عبید کے دونوں بیٹے محمد اور سعید روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۷۷۸) تجرید (۱۵۶/۲)\n(2) ترمذی کتاب النکاح (۱۰۸۵) المصنف لعبد الرزاق (۱۰۳۲۵) ابو داؤد فی المراسیل (۱۹۸) التاریخ الکبیر (۲۶/۹) السنن الکبریٰ (۸۲/۷)"}],[9677,"§۹۷۱۴ ۔ ابو حاجب انصاری\nدولابی نے کتاب الکنی سے، صحابہ میں ان کا ذکر کیا ہے لیکن ان کی کوئی حدیث ذکر نہیں کی۔"],[9678,"§۹۷۱۵ ۔ ابو حارث بن حارث بن عبد المطلب ہاشمی\nنوفل ہیں۔"],[9679,"§۹۷۱۶ ۔ ابو حارث بن حارث کندی\nعرفہ ہیں جو مصر فروکش ہوئے تھے۔"],[9680,"§۹۷۱۷ ۔ ابو حارث بن حنظلہ سعد انصاری\nسہل کے بھائی ہیں۔"],[9681,"§۹۷۱۸ ۔ ابو حارث\nوہی عبد اللہ بن سائب مخزومی ہیں۔"],[9682,"§۹۷۱۹ ۔ ابو حارث عیاش بن ابی ربیعہ مخزومی\nان سب حضرات کا ناموں میں تذکرہ ہو چکا ہے۔"],[9683,"§۹۷۲۰ ۔ ابو حارث بن قیس(1)\nبن خالد بن مخلد انصاری زرقی، موسیٰ بن عقبہ نے بحوالہ ابن شہاب شرکاء بدر میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۸۰) استیعاب (۲۹۴۴)"}],[9684,"§۹۷۲۱ ۔ ابو حارث ازدی(1)(2)\nابن ابی عاصم رحمہ اللہ اور ان کی پیروی میں ابو بکر بن ابی علی نے ان کا ذکر کیا ہے اور بطریق سلیمان بن عبید، بحوالہ قاسم بن یحییٰ، ان سے اس آیت کی تفسیر میں نقل کیا ہے: “یقینا انہوں نے اس فرشتہ کو دوسری بار اترتے دیکھا”۔(3) عام لوگوں نے عرض کیا: یا رسول اللہ! آپ نے کیا دیکھا؟ آپ نے فرمایا: “میں نے سونے کا ایک بستر دیکھا جیسے بادل ہوتا ہے۔”","",{"fn":"(1) اسد الغابہ (۵۷۷۹) تجرید (۱۵۶/۲)\n(2) الاحاد والمثانی (۲۶۲/۵)\n(3) سورۃ النجم (۱۳)"}],[9685,"§۹۷۲۲ ۔ ابو حازم احمسی(1)(2)\nصخر بن عیلہ، ناموں میں تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۸۳) تجرید اسماء الصحابۃ (۱۵۷/۲)\n(2) استیعاب (۲۹۴۵)"}],[9686,"§۹۷۲۳ ۔ ابو حازم بجلی(1)\nقیس کے والد۔ بقول بعض: ان کا نام عروف/عبد عوف ہے۔ امام بخاری نے “الادب المفرد” میں ان کی حدیث لکھی اور ابو داؤد نے ابن خزیمہ اور ابن حبان، حاکم نے اس کی تصحیح کی ہے۔ سب اسماعیل بن ابی خالد کے طریق سے بحوالہ قیس بن ابی حازم وہ اپنے والد سے روایت کرتے ہیں کہ جب وہ آئے تو نبی صلی اللہ علیہ وسلم خطبہ دے رہے تھے وہ دھوپ میں کھڑے ہو گئے، آپ نے انہیں سائے میں چلے جانے کا حکم دیا۔ محمد بن سعد فرماتے ہیں: ابو حازم صفین میں قتل ہوئے۔","",{"fn":"(1) ابو داؤد، کتاب الادب، باب فی الجلوس بین الظل والشمس (۲۸۲۲) مسند احمد (۴۲۶/۴)"}],[9687,"§۹۷۲۴ ۔ ابو حازم بجلی (دوسرے)(1)\nابو نعیم نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور قیس بن ربیع کے طریق سے بحوالہ ابان بن عبد اللہ بجلی، کریمہ بن ابی حازم سے انہوں نے اپنے والد سے روایت نقل کی ہے کہ نبی صلی اللہ علیہ وسلم کے سامنے دو آدمیوں نے ایک بچہ کے بارے میں مقدمہ پیش کیا، آپ نے ایک کے حق میں فیصلہ فرمایا۔","",{"fn":"(1) اسد الغابہ (۵۷۸۱) تجرید (۱۵۶/۲)"}],[9688,"§۹۷۲۵ ۔ ابو حازم انصاری از بنی بیاضہ\nبغوی وغیرہ نے ان کا صحابہ رضی اللہ عنہم میں ذکر کیا ہے۔ انہوں نے اور اسحاق بن راہویہ نے اپنی مسند اور حسن بن سفیان وغیرہ ان کے حوالہ سے نبی صلی اللہ علیہ وسلم سے ایک حدیث اعتکاف کے متعلق نقل کی ہے۔ ان سے محمد بن ابراہیم تیمی روایت کرتے ہیں۔ بغوی اور ابو داؤد نے مراسیل میں شمر بن عطیہ کے طریق سے بحوالہ ابو حازم نقل کیا ہے، فرمایا: آپ صلی اللہ علیہ وسلم کا چھڑے کا ایک عمدہ تھا جس کے ذریعہ دھوپ سے بچتے وہ نمدہ مال غنیمت سے حاصل ہوا تھا، پھر حدیث ذکر کی۔ نسائی نے ان کی پہلی حدیث کئی طرق سے روایت کی ہے، کسی طریق میں فرماتے ہیں: ابو حازم مولیٰ انصار سے مروی ہے اور کسی میں مولیٰ غفار بین اور بعض میں ابو حازم تمار بحوالہ بیاضی، جو شخص بنی بیاضہ سے ہیں۔ ان کا نام عبد اللہ بن جابر ہے۔ بقول بعض: فروہ بن عمرو ہے۔(1) رہے تمار تو وہ تابعی ہیں جو مولیٰ ابو رہم غفار ہیں۔ علامہ آجری فرماتے ہیں: میں نے ابو داؤد سے پوچھا: کیا ابو حازم سے محمد بن ابراہیم روایت کرتے ہیں؟ فرمایا: وہ بنی بیاضہ کے شخص ہیں۔ بقول بعض: وہ دو ہیں۔ تمار مولیٰ ابو رہم غفاری اور بیاض مولیٰ انصاری ہیں۔ واللہ اعلم","",{"fn":"(1) ابو داؤد المراسیل (۲۶۱)"}],[9689,"§۹۷۲۶ ۔ ابو حاضر (بے نسبت)(1)(2)(3)\nبغوی، ابن جارود، باوردی اور ابن حبان نے ان کا ذکر صحابہ رضی اللہ عنہم میں کیا ہے۔ فرماتے ہیں: مجھے معلوم نہیں کہ وہ صحابی ہیں یا نہیں؟ بغوی کا قول ہے: ان کا نسب بیان نہیں ہوا۔ ابن مندہ فرماتے ہیں: صحابہ رضی اللہ عنہم میں ان کا ذکر آتا ہے۔ چنانچہ وہ اور بغوی بطریق شعبہ، خالد حذاء سے ابو ہندہ سے بحوالہ ابو حاضر روایت کرتے ہیں۔ کیا میں تمہیں نماز جنازہ نہ سکھاؤں کہ نبی صلی اللہ علیہ وسلم کیسے جنازہ پڑھتے تھے؟  اللهم نحن عبادک و انت خلقتنا و انت ربنا و الیک معادنا۔  “اے اللہ! ہم تیرے بندے ہیں تو نے ہمیں پیدا کیا تو ہمارا رب ہے تیری طرف ہمارا لوٹنا ہے۔” بغوی رحمہ اللہ کی روایت میں ہے کہ نبی صلی اللہ علیہ وسلم نے ایک جنازہ پڑھانے کے بعد فرمایا: کیا میں تمہیں نہ بتاؤں، پھر فرمایا: اسی میں ہے: انت خلقتنا و نحن عبادک، باقی اس طرح ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۸۵) تجرید (۱۵۷/۲)\n(2) جامع المسانید (۵۱۹/۱۳)\n(3) اسد الغابہ (۴۱۱/۴)"}],[9690,"§۹۷۲۷ ۔ ابو حاطب بن عمرو(1)\nبن عبد شمس بن عبد ود بن نصر بن مالک بن حسل بن عامر بن لوی قرشی عامری۔ سہیل بن عمرو کے بھائی۔ اسلام کی طرف پہل کرنے والوں میں شامل ہیں۔ ابن اسحاق نے مہاجرین حبشہ میں ان کا ذکر کیا ہے۔(2)","",{"fn":"(1) اسد الغابہ (۵۷۸۶) استیعاب (۲۹۴۶) تجرید (۱۵۷/۲)\n(2) السیرۃ النبویۃ (۲۰۸/۱)"}],[9691,"§۹۷۲۸ ۔ ابو حامد(1)\nابو حماد میں تذکرہ ہوگا۔","",{"fn":"(1) اسد الغابہ (۵۷۹۴)"}],[9692,"§۹۷۲۹ ۔ ابو حبہ بدری(1)(2)\nصحیح میں ان کا ذکر آیا ہے جو بروایت زہری سیدنا انس رضی اللہ عنہ سے مروی ہے۔ ابو بکر بن محمد بن عمرو بن حزم بحوالہ ابو حبہ بدری، زہری کی حدیث کے بعد سیدنا انس رضی اللہ عنہ سے بحوالہ ابو ذر رضی اللہ عنہ اسراء کے متعلق مروی ہے۔ نیز ان سے عمار بن ابی عمار روایت کرتے ہیں۔ ان سے مروی حدیث مسند ابی شیبہ، احمد میں ہے حاکم نے اسے صحیح کہا ہے۔ اور آپ علیہ السلام سے ان کے سماع کی صراحت کی ہے۔ اس بنا پر یہ ان کے علاوہ ہوئے جن کے متعلق ابن اسحاق نے کہا ہے کہ وہ احد میں شہید ہوئے ان کی ایک اور حدیث طبرانی میں بروایت عبد اللہ بن عمرو بن عثمان، ان سے مروی ہے جس کی سند تو قوی ہے البتہ عبد اللہ بن عمرو بن عثمان نے ان کا زمانہ نہیں پایا ہے۔ ابو حاتم رحمہ اللہ یہ فرماتے ہیں: ان کا نام عامر بن عبد عمرو بن عمیر بن ثابت ہے۔ ابو عمر فرماتے ہیں: بقول بعض باء نون اور یاء سے ہے، بہر کیف درست باء سے ہے۔ بقول: ان کا نام عامر اور بقول بعض مالک ہے۔ موسیٰ بن عقبہ اور ابن ابی خیثمہ نے نون سے ان کا ذکر کیا ہے، واقدی نے اس کا انکار کیا ہے کہ بدری صحابہ رضی اللہ عنہم میں ابو جبہ کنیت کا کوئی شخص ہو۔ جبکہ ابن اسحاق نے بدر میں ابو جبہ از بنی ثعلبہ بن عمرو بن عوف کا ذکر کیا ہے وہ سعد بن خیثمہ کے ماں شریک بھائی ہیں۔ ابو معشر نے ان کی موافقت کی ہے۔ ابن سعد کا قول ہے: ہمیں انصار کے نسب میں، عمرو بن عمیر بن ثابت بن کلفہ بن ثعلبہ کی اولاد میں، ابو جبہ نامی کوئی شخص نہیں ملا۔ واقدی فرماتے ہیں: ابو حبہ کہلانے والے انصار میں دو شخص ہیں۔ ایک ابو حبہ بن غزیہ بن عمرو مازنی جو بنی مازن بن نجار سے تعلق رکھتے ہیں، جنہوں نے بدر میں شرکت نہیں کی۔ دوسرے ابو حبہ بن عبد عمرو۔ جو صفین میں سیدنا علی رضی اللہ عنہ کے ساتھ شریک تھے وہ اہل بدر میں سے نہیں ہیں۔ عبد اللہ بن محمد بن عمارہ نے اس پر اعتماد کیا ہے کہ جو بدر میں شریک ہوئے ان کی کنیت: ابو جبہ تھی یاء کی جگہ نون ہے۔ فرماتے ہیں: ان کا نام ثابت بن نعمان بن امیہ تھا اور وہ ابو صباح کے ماں شریک بھائی تھے اور عسکری نے بحوالہ جھمی نقل کیا ہے کہ ابو جبہ انصاری دو ہیں: ایک عمرو بن غزیہ جو بڑے ہیں دوسرے یزید بن غزیہ جو چھوٹے ہیں۔ فرماتے ہیں: ابن کلبی اس لفظ کو نون سے ادا کرتے تھے۔","",{"fn":"(1) اسد الغابہ (۵۷۸۸) تجرید (۱۵۷/۲)\n(2) السیرۃ النبویۃ (۲۵۰/۲)"}],[9693,"§۹۷۳۰ ۔ ابو حبہ بن غزیہ(1)(2)\nبن عمرو بن عطیہ بن خنساء بن مبذول بن عمرو بن غنم بن مازن بن نجار انصاری مازنی، موسیٰ بن عقبہ، اور ابن اسحاق وغیرہ کا قول ہے کہ احد میں شریک اور یمامہ میں شہید ہوئے۔ طبری نے یہ دعویٰ کیا ہے کہ ان کا نام زید ہے۔ کئی لوگوں نے انہیں سابقہ شخصیت سے رلا ملا دیا ہے اور کئی ایک نے اس کا فرق بھی رکھا ہے۔ ابو عمر فرماتے ہیں: یہ خزرجی ہیں اور وہ اوسی۔ یہ بدر میں شریک نہیں ہوئے جبکہ وہ بدر میں شریک تھے۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۵۷۸۹) تجرید (۱۵۷/۲)\n(2) السیرۃ النبویۃ (۲۶۰/۲)"}],[9694,"§۹۷۳۱ ۔ ابو حبیب عنبری(1)\nہر ماس بن حبیب کے دادا۔ کئی میں دولابی نے ان کا ذکر کیا ہے۔ اسحاق بن راہویہ نے ان کا نام نعلبہ بتایا ہے، جو ناموں میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۹۰) استیعاب (۲۹۴۹)"}],[9695,"§۹۷۳۲ ۔ ابو حبیب بن زید(1)\nبن حباب ابن انس بن زید بن عبید انصاری خزرجی، عبید میں جا کر ابی بن کعب کے ساتھ نسب مل جاتا ہے۔ ابن کلبی کا قول ہے: بدر میں شریک ہوئے۔ ابو عمر کا کہنا ہے: ان کا صحابہ میں ذکر ملتا ہے، لیکن مجھے ان کے متعلق معلومات نہیں۔","",{"fn":"(1) اسد الغابہ (۵۷۹۰) استیعاب (۲۹۴۹) تجرید (۱۵۷/۲)"}],[9696,"§۹۷۳۳ ۔ ابو حبیب فہری\nناموں میں ان کے بیٹے حبیب کے حالات میں ان کا تذکرہ گزر چکا ہے۔"],[9697,"§۹۷۳۴ ۔ ابو حبیب\nان سے ابن الشاعر روایت کرتے ہیں، ان کا نام و نسب معلوم نہیں، تجرید میں یوں ہی لکھا ہے۔"],[9698,"§۹۷۳۵ ۔ ابو حبیبہ بن ازعر(1)\nبن زید ابن الخطاف بن ضبیعہ انصاری، یحییٰ بن عبد الوہاب ابن مندہ نے اپنے دادا کی کتاب پر استدراک میں ان کا ذکر کیا ہے۔ فرمایا: وہ شرکاء بدر میں سے تھے۔","",{"fn":"(1) اسد الغابہ (۵۷۹۲) تجرید (۱۵۸/۲)"}],[9699,"§۹۷۳۶ ۔ ابو حثمہ انصاری(1)(2)(3)\nسہل کے والد۔ نام عبد اللہ ہے، بقول بعض: عامر بن ساعدہ بن عامر بن عدی حارثی نہیں۔ ان کے بیٹے کے حالات میں ان کا نسب پہلے گزر چکا ہے۔ تاریخ میں امام بخاری رحمہ اللہ لکھتے ہیں: مجھ سے ابراہیم بن منذر نے، محمد بن صدقہ، محمد بن یحییٰ بن سہل بن ابی حثمہ، انہوں نے اپنے والد انہوں نے اپنے دادا سے روایت کی ہے کہ نبی صلی اللہ علیہ وسلم نے ابو حثمہ کو (پھلوں کا) اندازہ لگانے کے لیے بھیجا۔(4) اسی روایت کو دارقطنی نے دوسرے طریق سے بحوالہ محمد بن صدقہ نقل کیا تو اس میں اضافہ ہے کہ ایک شخص آ کر کہنے لگا: یا رسول اللہ! ابو حثمہ نے مجھ پر زیادتی کی جس کی وجہ سے رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: تمہارا چچیرا بھائی تمہاری شکایت کر رہا ہے۔ انہوں نے عرض کی: یا رسول اللہ! میں نے اس کے گھرانے کے لیے چنی ہوئی کھجوریں چھوڑ دی ہیں۔ واقدی نے محمد بن یحییٰ بن سہل سے بحوالہ ان کے والد انہوں نے اپنے دادا سے روایت کی ہے کہ احد کے روز نبی صلی اللہ علیہ وسلم نے فرمایا: “ایسا کوئی شخص ہے جو ہمیں دشمن سے لڑنے کے لیے قریبی راستہ دکھائے؟” ابو حثمہ بولے: میں ہوں (یا رسول اللہ!) چنانچہ وہ آپ صلی اللہ علیہ وسلم کے راہ نما بنے یہاں تک کہ ان کے مقابلہ میں جا پہنچایا۔ واقدی فرماتے ہیں: حضرات شیخین اور سیدنا عثمان رضی اللہ عنہم انہیں پھلوں کا اندازہ لگانے کے لیے بھیجا کرتے تھے۔ ان کا انتقال امیر معاویہ کی خلافت کے ابتدائی دور میں ہوا۔ ابن اسحاق نے سیرت میں یہ قصہ ذکر کیا ہے۔ لیکن جن کے ساتھ یہ واقعہ پیش آیا ان کے متعلق کہا ہے: ابو خیثمہ (خاء، یاء اور ثاء سے) یعمری کا بیان ہے ان سے وہم ہوا ہے۔ درست یہی ہے کہ وہ ابو حثمہ سہل کے والد ہیں جس پر یقینی دلیل صرف ابن عبد البر کا یہ قول پیش کیا ہے کہ صحابہ رضی اللہ عنہم میں جعلی اور سالمی کے علاوہ کوئی ابو حثمہ نہیں، اس حصر و قید میں تامل ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۹۵) تجرید (۱۹۸/۲)\n(2) التاریخ الکبیر (۹۷/۴)\n(3) کھجوروں کا اندازہ لگانے کو خرص کہتے ہیں۔\n(4) سنن دارقطنی (۱۳۵/۲)"}],[9700,"§۹۷۳۷ ۔ ابو خثمہ بن حذیفہ(1)\nبن غانم ابن عامر قرشی عدوی، ابو جہم کے بھائی۔ بقول ابن السکن: صحابی ہیں۔ فتح مکہ کے موقع پر اسلام لانے والوں میں سے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۷۹۴) تجرید (۱۵۸/۲)"}],[9701,"§۹۷۳۸ ۔ ابو الحجاج ثمالی(1)\nنام عبد اللہ بن عبد بن عامر، بقول بعض: جعد بن عبد ہے، ناموں میں ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۹۶) استیعاب (۲۹۵۲) تجرید (۱۵۸/۲)"}],[9702,"§۹۷۳۹ ۔ ابو الحجاج اسلمی\nحجاج بن حجاج کے والد، ناموں میں تذکرہ ہو چکا ہے۔ بغوی نے ان کا ذکر کیا ہے کہ مدینہ رہتے تھے۔"],[9703,"§۹۷۴۰ ۔ ابو حدرد اسلمی(1)\nعبد اللہ کے والد۔ ان کی حدیث ان کے بیٹے کے سوانح میں گزری ہے اور ناجیہ کے حالات جو نون میں ہیں وہاں بھی اس کا ذکر ہوا ہے۔ امام بخاری رحمہ اللہ کی الادب المفرد میں ان کی ایک اور حدیث بھی ہے۔ بقول بعض: ان کا نام سلامہ بن عمیر بن ابی سلامہ بن سعد بن مسنآب ہے، یہی نام ابو علی جیانی نے قلمبند کیا ہے۔ ایک قول ہے: ان کا نام بغیر تصغیر و اضافت کے “عبد” ہے یہ امام احمد رحمہ اللہ کا قول ہے۔ بقول بعض: عبید (تصغیر کے ساتھ) ہے۔(2) نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں: ان سے ان کا بیٹا جو حمل بن بشر بن حدرد کا چچا ہے وہ اور محمد بن ابراہیم تیمی روایت کرتے ہیں۔ اس کا عسکری نے ذکر کیا ہے۔ مزی کی تہذیب میں لکھا ہے کہ ابن سعد نے ان کی تاریخ وفات اے لکھی ہے۔ مغلطائی نے ان کا تعاقب کرتے ہوئے فرمایا کہ ابن سعد نے تو عبد اللہ بن ابی حدرد کا عنوان قائم کیا ہے اور ان کا نسب بیان کیا ہے اور تاریخ بھی انہی کی لکھی ہے جس میں یہ اضافہ کیا کہ وہ اکاسی(۸۱) سال کے تھے۔ یہی تاریخ خلیفہ اور یحییٰ بن بکیر وغیرہ نے بیان کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۹۷) تجرید (۱۵۸/۲)\n(2) مسند احمد (۵۴۳/۳) (۵۸۱/۳)"}],[9704,"§۹۷۴۱ ۔ ابو حدرد (دوسرے)\nحکم بن حزن کلفی، ناموں میں تذکرہ گزر چکا ہے۔"],[9705,"§۹۷۴۲ ۔ ابو حدرد (ایک اور)\nان کا نام براء تھا۔ ابن عبد البر نے ان کا ذکر کیا ہے کہ مجھے ان کے بارے میں علم نہیں۔"],[9706,"§۹۷۴۳ ۔ ابو حدرد\nابو حدیرہ میں تذکرہ آئے گا۔"],[9707,"§۹۷۴۴ ۔ ابو حذافہ سہمی\nعبد اللہ بن حذافہ بن قیس، پہلے ذکر ہوا ہے۔"],[9708,"§۹۷۴۵ ۔ ابو حذیفہ بن عتبہ(1)\nبن ربیعہ بن عبد شمس بن عبد مناف قرشی عبشمی، معاویہ فرماتے ہیں: ان کا نام مہشم ہے۔ بقول بعض ہشیم، ہاشم، قیس ہے۔ سبقت الی الاسلام کرنے والوں میں سے ہیں۔ دو ہجرتیں کیں اور دونوں قبلوں کی جانب نمازیں پڑھیں۔(2) ابن اسحاق(3) کا قول ہے: تینتالیس افراد کے بعد اسلام لائے۔ سالم مولیٰ ابو حذیفہ کے حالات میں بھی ان کا ذکر ہوا ہے۔ سالم کے قصہ میں صحیحین میں بطریق زہری، عروہ سے بحوالہ عائشہ رضی اللہ عنہا ان کا ذکر ثابت ہے کہ ابو حذیفہ شرکاء بدر میں سے تھے۔ اپنی کنیت سالم سے رکھتے تھے۔ لوگوں کا کہنا ہے کہ وہ دراز اور لانبے قد والے خوبصورت چہرے بشرے والے انسان تھے۔ جنگ یمامہ میں شہید(4) ہوئے، اس وقت عمر چھپن(۵۶) سال کی تھی۔","",{"fn":"(1) اسد الغابہ (۵۸۰۰) استیعاب (۲۹۵۵) تجرید (۱۵۸/۲)\n(2) اسد الغابہ (۴۱۶/۴)\n(3) السیرۃ النبویۃ (۷/۴) (۲۶۹/۲)\n(4) اسد الغابہ (۴۱۶/۴) مختصر تاریخ دمشق (۱۸۶/۲۷)"}],[9709,"§۹۷۴۶ ۔ ابو حذیفہ ثقفی(1)\nاز اولاد غیاث بن مالک بیعت رضوان میں بقول مدائنی شریک ہوئے، ابن فنتون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۰۱) تجرید (۱۵۸/۲)"}],[9710,"§۹۷۴۷ ۔ ابو حرب بن خویلد\nبن عامر بن عقیل بن کعب بن ربیعہ بن عامر بن صعصعہ عامری عقیلی۔ ابن کلبی فرماتے ہیں: وہ جاہلیت کے شہسوار تھے، پھر اسلام لائے۔ نبی صلی اللہ علیہ وسلم کے پاس آئے، انہوں نے آپ سے پوچھا کہ ان کی قوم نہ دسواں حصہ لے گی اور نہ جمع ہوگی تو آپ نے ان کی یہ بات مان لی۔ قطب کی شرح سیرت میں ہے آپ نے انہیں اسلام کی پیشکش کی تو انہوں نے قبول نہ کیا، بعد میں اسلام لے آئے تھے۔"],[9711,"§۹۷۴۸ ۔ ابو حریز(1)\nان سے ابو لیلیٰ روایت کرتے ہیں۔ ناموں میں حریز نامی شخصیت میں ان کا تذکرہ گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۱۰)"}],[9712,"§۹۷۴۹ ۔ ابو حریزہ(1)\nمستغفری کا قول ہے کہ انہیں شرف صحابیت حاصل ہے۔ امام بخاری رحمہ اللہ نے صرف کنیتوں میں ان کا ذکر کیا ہے اور بیشم کے طریق سے بحوالہ ابو اسحاق کوفی جو شیبانی ہیں ابو حریزہ سے ان کی حدیث نقل کی ہے، فرماتے ہیں: عبد اللہ بن سلام رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم سے کہنے لگے: یا رسول اللہ! ہمیں آپ کی یہ صفت کتابوں میں ملتی ہے کہ آپ قیامت کے روز عرش کے پاس غصہ سے بھرے، اپنے بعد اپنی اُمت کے کیے پر افسوس کرتے کھڑے ہوں گے۔”(2) ابو احمد حاکم نے یہ حدیث ان سے پہلے والے شخص ابو حریز کے سوانح میں درج کی ہے، راجح یہی ہے کہ وہ اور ہیں۔","",{"fn":"(1) اسد الغابہ (۵۸۰۲) تجرید (۱۵۸/۲)\n(2) اسد الغابہ (۴۱۷/۴)"}],[9713,"§۹۷۵۰ ۔ ابو حریش\nماعز بن مالک رضی اللہ عنہ کے رجم میں شریک ہوئے، ان کے بیٹے حریش کے حالات میں ان کا تذکرہ ہوا ہے۔"],[9714,"§۹۷۵۱ ۔ ابو حسان(1)\nصالح بن حسان کے دادا۔ بقول ابن مندہ: شرف صحابیت سے مشرف ہیں۔ ان کی حدیث مجالد نے بواسطہ صالح بن حسان، اپنے والد سے انہوں نے اپنے دادا سے روایت کی ہے کہ نبی صلی اللہ علیہ وسلم نے ان کے خلاف چڑھائی کی۔","",{"fn":"(1) اسد الغابہ (۵۸۰۵) تجرید (۱۵۹/۲)"}],[9715,"§۹۷۵۲ ۔ ابو حسان(1)(2)(3)\nبقول بعض: ابو حسن، اور ابو حسین مولا بنی نوفل، عبد بن حمید، یعقوب بن ابراہیم سے وہ اپنے والد سے وہ صالح بن کیسان سے وہ ابن المنکدر سے کہ مجھے ابو حسان مولا بنی نوفل نے بتایا ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"یہ کوئی فخر کی بات نہیں، میں قیامت کے دن پوری انسانیت کا سردار بنوں گا۔\"(4) ابن مندہ نے بطریق عباس دوری بحوالہ یعقوب اسی سند سے روایت کی، فرمایا: مجھے ابو حسین مولا بنی نوفل نے بیان کیا۔ ابو نعیم نے دوسری سند سے بحوالہ ابن عباس رضی اللہ عنہما روایت کی، فرمایا: ہمیں ابو حسن نے بیان کیا۔ زہری نے بواسطہ ابو حسن مولا بنی نوفل بحوالہ ابن عباس رضی اللہ عنہما ایک حدیث روایت کی ہے۔ نوفل اپنے عہد ولاء کی جانب منسوب ہیں وہ ابن حارث بن عبد المطلب ہیں، اس واسطے کہ وہ بنی عبد اللہ بن حارث بن نوفل کے مولا ہیں۔ اگر واقعہ یہی ہے تو وہ تابعی ہیں یہ بھی احتمال ہے کہ نوفل بن عبد مناف کی جانب منسوب ہوں، انہی میں عثمان بن سعید بن ابی حسین کے دادا بھی ہیں۔","",{"fn":"(1) اسد الغابہ (۵۸۰۷)\n(2) بخاری کتاب احادیث الانبیاء (۳۳۴۰) مسلم کتاب صفۃ القیامۃ باب ما جاء فی الشفاعۃ (۵۸۹۹)\n(3) ترمذی کتاب صفۃ القیامۃ باب ما جاء فی الشفاعۃ (۲۴۳۴) مسند احمد (۴۳۵/۲) (۴۳۶/۲)\n(4) الاسماء والصفات للبیہقی (۳۱۵) السنۃ لابن ابی عاصم (۸۱۱) جامع المسانید (۵۳۱/۱۳) اسد الغابہ (۸۹/۷)"}],[9716,"§۹۷۵۳ ۔ ابو الحسن\nعلی بن ابی طالب ابن عبد المطلب ہاشمی، ناموں میں تذکرہ ہو چکا ہے۔"],[9717,"§۹۷۵۴ ۔ ابو حسن انصاری(1)\nثم المازنی، یحییٰ بن عمارہ بن ابی حسن کے دادا، کنیت سے ہی مشہور ہیں۔ نام تمیم بن عمرو تھا، بقول بعض: ابن عبد عمرو، ابن عبد قیس بن مخرمہ بن حارثہ بن نعلبہ بن مازن تھا۔ ابن السکن لکھتے ہیں: بدری صحابی ہیں۔ اور حسین بن عبد اللہ ہاشمی کے طریق سے، بواسطہ عمرو بن یحییٰ بن عمارہ بن ابی حسن وہ اپنے والد سے وہ اپنے دادا ابو حسن سے روایت کرتے ہیں جو بیعت عقبہ اور بدر میں شریک ہوئے تھے کہ رسول اللہ صلی اللہ علیہ وسلم اپنے صحابہ رضی اللہ عنہم کی ایک جماعت کے ساتھ تشریف فرما تھے، ان میں سے ایک شخص اٹھا لیکن اپنے جوتے لینا بھول گیا، جنہیں دوسرے شخص نے اٹھا کر اپنے بیٹھنے کی جگہ رکھ لیا، وہ شخص آ کر کہنے لگا: میرے جوتے تھے، لوگوں نے کہا: ہم نے تو نہیں دیکھے (جس شخص نے جوتے اٹھا کر اپنے پاس رکھ لیے تھے) وہ کہنے لگا: میں نے بطور مزاح وہ جوتے اٹھائے تھے۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"مومن کو خوفزدہ کرنے کا کیسا انجام ہوگا۔\"(2) آپ نے تین بار یہ کلمات فرمائے۔ عبد اللہ بن احمد نے زیادات مسند میں بطریق دراوردی، عمرو بن یحییٰ سے بواسطہ یحییٰ بن عمارہ بحوالہ ان کے والد نقل کیا ہے، فرمایا: میں بازار گیا اور دو سرخ سیاہ رنگ کے فاختہ کے بچے پکڑ لیے جن پر ان کی ماں سو رہی تھی، اتنے میں ابو حسن میرے پاس آگئے، انہوں نے مجھے مار کر کہا: \"کیا تمہیں پتہ نہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ کے دونوں کناروں کے درمیانی علاقہ کو حرم قرار دیا ہے۔\"(3) اسی روایت کو طبرانی نے بطریق محمد بن فلیح، بواسطہ عمرو بن یحییٰ اس سے زیادہ مختصر انداز میں نقل کیا ہے اس میں فرماتے ہیں: اتنے میں صحابی رسول ابو حسن آگئے، پھر وہ حدیث ذکر کی۔ ذہبی(4) فرماتے ہیں: وہ سیدنا علی رضی اللہ عنہ کے دور تک زندہ رہے۔","",{"fn":"(1) اسد الغابہ (۵۸۰۶) تجرید (۱۵۹/۲)\n(2) المعجم الکبیر (۹۸۰/۲۲) مجمع الزوائد (۲۵۳/۶) جامع المسانید (۵۳۰/۱۳)\n(3) اسد الغابہ (۴۱۸/۴)\n(4) زوائد المسند (۱۶۷/۱) تجرید (۱۵۹/۲)"}],[9718,"§۹۷۵۵ ۔ ابو الحسن رافع بن عمرو طائی\nناموں میں تذکرہ ہوا ہے۔"],[9719,"§۹۷۵۶ ۔ ابو حسن مولا بنی نوفل(1)\nابو حسان میں تذکرہ گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۰۸) تجرید (۱۵۹/۲)"}],[9720,"§۹۷۵۷ ۔ ابو حسین تصغیر\nیہ بھی پہلے گزر چکا ہے۔"],[9721,"§۹۷۵۸ ۔ ابو الحشر\nصہیب کے ساتھ سیدنا ابو بکر الصدیق رضی اللہ عنہ کا پیش آمدہ ایک قصہ ذکر کیا جاتا ہے جسے ابن ابی شیبہ نے بطریق ابو الضحیٰ بحوالہ مسروق نقل کیا ہے، فرمایا کہ صہیب رضی اللہ عنہ کا سیدنا صدیق رضی اللہ عنہ کے پاس سے گزر ہوا تو ان سے اعراض کر لیا، سیدنا صدیق رضی اللہ عنہ نے پوچھا: کیا آپ کو میری طرف سے کوئی نا پسندیدہ بات پہنچی ہے؟ فرمایا: ایسی کوئی بات نہیں، میں نے آپ کے متعلق ایک خواب دیکھا ہے جو مجھے پسند نہیں، پوچھا: آپ نے کیا دیکھا؟ فرمایا: میں نے دیکھا کہ ایک انصاری کے دروازے پر آپ کا یہ ہاتھ گردن سے بندھا ہے جن کا نام ابو الحشر ہے۔ سیدنا صدیق رضی اللہ عنہ نے فرمایا: تم نے اچھی بات دیکھی ہے، قیامت تک میرے لیے دین کو جمع کر دیا ہے۔"],[9722,"§۹۷۵۹ ۔ ابو حصیرہ(1)\nابن اسحاق کا بیان ہے کہ نبی صلی اللہ علیہ وسلم نے انہیں خیبر کی کھجور میں دی تھیں، ان کا نام لکھنے میں اختلاف ہے بعض صاد کی زیر سے اور بعض ظاء سے لکھتے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۸۰۴) تجرید (۱۵۹/۲)"}],[9723,"§۹۷۶۰ ۔ ابو حصین العبسی\nان کا نام لقمان تھا، ناموں میں گزرا ہے۔"],[9724,"§۹۷۶۱ ۔ ابو حسین سدوسی(1)\nابن مندہ نے ان کا ذکر کیا ہے کہ ان کی حدیث نعیم بواسطہ اپنے چچا وہ بحوالہ اپنے والد روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۸۱۰) تجرید (۱۵۹/۲)"}],[9725,"§۹۷۶۲ ۔ ابو حصین سلمی(1)\nبغوی نے ان کا ذکر کیا ہے کہ واقدی نے بواسطہ عبد اللہ بن یحییٰ، عمر بن حکم بحوالہ جابر روایت کی ہے کہ ابو حصین سلمی کان سے سونا لے کر نبی صلی اللہ علیہ وسلم کے پاس آئے، پھر لمبی حدیث ذکر کی۔(2)","",{"fn":"(1) اسد الغابہ (۵۸۱۱) تجرید (۱۵۹/۲)\n(2) اسد الغابہ (۴۱۸/۴)"}],[9726,"§۹۷۶۳ ۔ ابو حصین انصاری سالمی(1)\nقاضی اسمعیل کی کتاب \"احکام القرآن\" میں ان کا ذکر آتا ہے، جو بطریق اسباط بن نصر بواسطہ سدی اپنی قوم کے کسی فرد سے روایت کرتے ہیں کہ ابو الحصین کے دو بیٹے تھے، وہ بغرض تجارت شام سے مدینہ آئے۔ وہ دونوں نصرانی ہو کر شام میں جا بسے تھے، ابو الحصین نے نبی صلی اللہ علیہ وسلم کے پاس آکر یہ واقعہ ذکر کیا، آپ نے فرمایا: \"دین کے معاملہ میں کوئی زور زبردستی نہیں۔\"(2) اس وقت جنگ کا حکم نازل نہیں ہوا تھا۔ ابو الحصین کو دل میں بڑی بے اطمینانی ہوئی جس پر یہ آیت نازل ہوئی: \"تیرے رب کی قسم! جب تک یہ اپنے باہمی تنازعات میں آپ کو فیصل نہیں مان لیتے، ایمان والے نہیں ہو سکتے۔\" اسی طرح یہ روایت طبری نے بطریق اسباط بواسطہ سدی نقل کی ہے۔(3) ادھر المزی نے جعفر بن محمد کے حالات میں ذکر کیا ہے کہ ابو داؤد نے \"کتاب الناسخ والمنسوخ\" میں بواسطہ جعفر بن محمد، عمرو بن حماد سے بحوالہ اسباط بن نصر اسی مفہوم کی روایت نقل کی ہے۔ لیکن نزول آیت کے بارے کہا کہ حصین نامی ایک انصاری کے بارے میں نازل ہوئی۔ نیز طبری نے بطریق محمد بن اسحاق مغازی والے، بواسطہ محمد بن ابی محمد عکرمہ یا سعید بن جبیر سے بحوالہ ابن عباس رضی اللہ عنہما روایت کی ہے کہ یہ آیت بنی سالم بن عوف کے حصین نامی ایک انصاری کے بارے میں نازل ہوئی۔ (حدیث) میں کہتا ہوں: راویوں میں حصین بن محمد سالمی ہیں جن سے زہری نے سماع کیا ہے اور ان کے بارے میں کہا ہے کہ وہ انصار کے سرداروں میں سے تھے۔ ان سے ان کی حدیث صحیح میں اور اس میں یہ ذکر نہیں کیا کہ کس نے ان سے یہ حدیث بیان کی ہے۔ ابن ابی حاتم کا بیان ہے کہ ان سے ان کی روایت تو بواسطہ عتبان بن مالک ہے، ایسا ہی ابن حبان نے ثقات التابعین میں ان کا ذکر کیا ہے۔ اس تفصیل سے وہ صحابی نہیں ہو سکتے، اگر چہ اس میں دونوں مشترک ہیں کہ وہ انصار میں سے بنی سالم سے تعلق رکھتے ہیں۔ اس سلسلہ میں حصین نامی حضرات میں اس سے زیادہ تفصیل گزر چکی ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۰۹) تجرید (۱۵۹/۲)\n(2) اسد الغابہ (۴۱۸/۴)\n(3) سورۃ النساء (۶۵)"}],[9727,"§۹۷۶۴ ۔ ابو حفص\nعمر بن خطاب امیر المومنین رضی اللہ عنہ، پہلے تذکرہ ہو چکا ہے۔"],[9728,"§۹۷۶۵ ۔ ابو حفص بن عمرو(1)\nبن مغیرہ مخزومی، فاطمہ بنت قیس کے خاوند، بقول بعض: ابو عمرو بن حفص بن مغیرہ، عین میں تذکرہ ہوتا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۱۳) تجرید (۱۵۹/۲)"}],[9729,"§۹۷۶۶ ۔ ابو الحکم\nرافع بن سنان، تذکرہ ہو چکا ہے۔"],[9730,"§۹۷۶۷ ۔ ابو الحکم بن سفیان ثقفی\nحکم بن سفیان میں تذکرہ گزر چکا ہے۔"],[9731,"§۹۷۶۸ ۔ ابو الحکم بن حبیب(1)\nبن ربیعہ بن عمرو بن عمیر ثقفی۔ مدائنی نے جسر کے روز ابو عبیدہ رضی اللہ عنہ کے ساتھ شہید ہونے والوں میں ان کا ذکر کیا ہے۔ اسی دن کو \"جسر الناطف\" کا دن کہا جاتا ہے۔ مدائنی فرماتے ہیں: اس روز ابو عبیدہ رضی اللہ عنہ امیر لشکر کے ساتھ ثقیف کے تین سو افراد شہید ہوئے، ان میں سے اسی افراد نے سفید بالوں پر خضاب لگا رکھا تھا۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۱۵) تجرید (۱۵۹/۲)"}],[9732,"§۹۷۶۹ ۔ ابو حکیم قشیری\nبہز بن حکیم کے دادا، یہ معاویہ بن حیدہ ہیں، تذکرہ ہو چکا ہے۔"],[9733,"§۹۷۷۰ ۔ ابو حکیم بن مقرن مزنی\nان کا نام عقیل تھا، بھائیوں میں سے ایک ہیں۔ پہلے تذکرہ ہو چکا ہے۔"],[9734,"§۹۷۷۱ ۔ ابو حکیم کنانی\nقعقاع بن حکیم کے دادا۔ بغوی نے صحابہ رضی اللہ عنہم میں ان کا تذکرہ کیا ہے اور بحوالہ قعقاع بن حکیم ان کے دادا کے حوالہ سے روایت کی ہے وہ سیدہ عائشہ رضی اللہ عنہا کی پرورش میں تھے، فرماتے ہیں: میں نے آپ سے عرض کی: رسول اللہ صلی اللہ علیہ وسلم سے پوچھئے کہ ان جوتوں میں نماز پڑھنا کیسا ہے جن سے وہ راستوں میں چلتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"مٹی ان دونوں کو پاک بنا دیتی ہے۔\" بغوی فرماتے ہیں: یہ روایت مجھے صرف ابن سمعان کے ہاں ملی ہے جو حدیث میں کمزور راوی ہے۔"],[9735,"§۹۷۷۲ ۔ ابو حکیم یزید\nبقول بعض: حکیم ابو یزید، خیر خواہی کے بارے میں ان کی حدیث ہے، ناموں میں تذکرہ ہو چکا ہے۔"],[9736,"§۹۷۷۳ ۔ ابو حکیم مزنی(1)(2)\nبقول باوردی، انہیں شرف صحابیت حاصل ہے۔ اہل حمص سے ان کی حدیث منقول ہے۔ چنانچہ وہ حدیث انہوں نے ابن السکن اور طبرانی بحوالہ شریح بن عبید نقل کی ہے کہ ابو حکیم کا زعم ہے کہ انہوں نے فرمایا نبی صلی اللہ علیہ وسلم کا ارشاد ہے کہ ”اگر میری امت پر صرف سورۃ الکہف ہی نازل ہوتی تو بھی ان کے لیے کافی تھی۔”(3) ایک اثر (حدیث یا قول صحابی) موقوف میں ان کا ذکر آتا ہے جسے عبد الرزاق نے بطریق عبد اللہ بن مرہ اس نقل کیا ہے کہ مجھ سے ایک شخص مسئلہ پوچھنے آیا، میں نے اس سے کہا: عبد اللہ بن مسعود یا ابو حکیم مزنی کے پاس جاؤ پھر جنبی شخص کے روزہ رکھنے کا قصہ ذکر کیا۔ اسی روایت کو طبرانی نے بھی ذکر کیا ہے، اس سے پتہ چلتا ہے کہ وہ فتویٰ دینے میں شہرت رکھتے تھے۔","",{"fn":"(1) اسد الغابہ (۵۸۱۸) تجرید (۱۶۰/۲)\n(2) کنز العمال (۲۶۱۶)\n(3) تجرید (۱۶۰/۲)"}],[9737,"§۹۷۷۴ ۔ ابو حکیم\nبقول بعض: ابو حکمیہ، عمرو بن نعلیہ، ناموں میں پہلے تذکرہ ہو چکا ہے۔"],[9738,"§۹۷۷۵ ۔ ابو حلوہ\nمولا عباس بن عبد المطلب۔ فاکہی نے کتاب مکہ میں ان کا ذکر کیا ہے کہ ابن جریج مروی ہے: مولا عباس نبی صلی اللہ علیہ وسلم کی خدمت میں آ کر عرض کرنے لگے: میں ابو مرہ مولا عباس ہوں، آپ نے فرمایا: نہیں! تم تو ابو حلوہ ہو۔"],[9739,"§۹۷۷۶ ۔ ابو حلیمہ(1)\nنام معاذ ابن حارث انصاری قاری تھا، پہلے ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۱۹) تجرید (۱۶۰/۲)"}],[9740,"§۹۷۷۷ ۔ ابو حماد انصاری(1)\nبغوی نے ان کا ذکر کیا ہے لیکن ان کی کوئی حدیث نقل نہیں کی۔ ابو موسیٰ نے ذکر کرنے کے بعد بحوالہ واہب بن عبد اللہ وہ عقبہ بن عامر اور ابو حماد یا ابو حامد انصاری اصحاب رسول صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: جس نے کسی مومن کو کسی گناہ میں مبتلا دیکھ کر اس پر پردہ ڈالا اس کے لیے زندہ در گور لڑکی کو بچانے کا ثواب ہے۔(2) میں کہتا ہوں: ابو حماد عقبہ بن عامر رضی اللہ عنہ کی کنیت ہے، اگر ان کا یہ قول نہ ہوتا کہ دونوں اصحاب رسول صلی اللہ علیہ وسلم تو امکان تھا واؤ گر گئی ہے۔","",{"fn":"(1) ابو داؤد کتاب الادب (۴۸۹۱) مسند احمد (۱۴۷/۳) المستدرک (۳۸۴/۴)\n(2) المعجم الکبیر (۷۹۵/۱۷) (۸۶۴/۲۲) اسد الغابہ (۴۲۰/۴)"}],[9741,"§۹۷۷۸ ۔ ابو حماد\nعقبہ بن عامر جہنی مشہور صحابی ہیں۔ تذکرہ ہو چکا ہے۔"],[9742,"§۹۷۷۹ ۔ ابو حمامہ\nبغوی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے کہ میں نے صحابہ رضی اللہ عنہم کے بارے میں کسی مصنف کی کتاب میں ان کا نام دیکھا ہے۔ (اس کے علاوہ) نہ میں ان کے نام سے واقف ہوں اور نہ ان کی کسی حدیث کے بارے کبھی کچھ سنا ہے۔ ابو الجارود نے بھی صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق ابن اسحاق بواسطہ یعقوب بن عتبہ بحوالہ حارث بن ابی بکر وہ اپنے والد وہ حمامہ وہ اپنے والد کی سند سے ان کی حدیث نقل کرتے ہیں۔"],[9743,"§۹۷۸۰ ۔ ابو حمراء (مولا نبی صلی اللہ علیہ وسلم)(1)\nنام بلال بن حارث، بقول بعض: ابن ظفر۔ یہ قول ابن عیسیٰ نے تاریخ حمص میں نقل کیا ہے۔ ناموں میں پہلے ان کا ذکر ہوا ہے۔ امام بخاری رحمہ اللہ فرماتے ہیں: بقول بعض: انہیں شرف صحابیت حاصل ہے۔ لیکن ان کی حدیث صحیح نہیں۔","",{"fn":"(1) اسد الغابہ (۵۸۲۰) تجرید (۱۶۰/۲)"}],[9744,"§۹۷۸۱ ۔ ابو حمراء (دوسرے)(1)\nبدر و اُحد میں شریک ہوئے۔ بقول بعض: مولا عفراء ایک قول: \"مولا حارث بن رفاعہ\" کا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۲۱) استیعاب (۲۹۶۰) تجرید (۱۶۰/۲)"}],[9745,"§۹۷۸۲ ۔ ابو حمزہ\nانس بن مالک، خادم رسول۔ مشہور صحابی ہیں، ناموں میں تذکرہ ہو چکا ہے۔"],[9746,"§۹۷۸۳ ۔ ابو حمزہ انصاری\nجن سے نبی صلی اللہ علیہ وسلم نے فرمایا: تمہارا بیٹا حمزہ ہے۔ حاء کی قسم ثانی میں حمزہ میں ان کا تذکرہ پہلے ہو چکا ہے۔"],[9747,"§۹۷۸۴ ۔ ابو حمید ساعدی(1)\nمشہور صحابی ہیں۔ نام عبد الرحمن بن سعد، ایک قول: عبد الرحمن بن عمرو سعد اور ایک قول منذر بن سعد بن منذر کا ہے۔ دادا کا نام کسی نے مالک بتایا ہے، کسی نے یوں نسب لکھا ہے۔ عمرو بن سعد بن منذر بن سعد بن خالد بن ثعلبہ بن عمرو۔ بقول بعض: سہل بن سعد کے چچا ہیں۔ نبی صلی اللہ علیہ وسلم سے کئی ایک احادیث نقل کی ہیں۔ صحیحین میں ان کا ان کے ساتھ ذکر ہے۔ ان سے ان کا پوتا سعید بن منذر بن ابی حمید، سیدنا جابر صحابی، عباس بن سہل بن سعد، عبد الملک بن سعید بن سوید، عمرو بن سلیم عروہ، اور محمد بن عمرو بن عطاء وغیرہ حضرات روایت لیتے ہیں۔ خلیفہ اور ابن سعد وغیرہ کا قول ہے: اُحد اور بعد کے غزوات میں شریک رہے۔ امام واقدی فرماتے ہیں: خلافت معاویہ کے اخیر میں یا خلافت یزید کے آغاز میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۵۸۲۲) تجرید (۱۶۰/۲)"}],[9748,"§۹۷۸۵ ۔ ابو حمید (یا ابو حمیدہ شک ہے)(1)\nبلاذری نے صحابہ رضی اللہ عنہم میں ذکر کر کے ان کا نام لکھا ہے اور امام احمد رحمہ اللہ نے اپنی مسند میں ان کی حدیث نقل کی ہے، جو ابو حمید ساعدی کی دوگنی احادیث میں شامل ہے۔ امام احمد رحمہ اللہ فرماتے ہیں: حسن بن موسیٰ اور ابو کامل دونوں زہیر سے وہ عبد اللہ بن عیسیٰ سے وہ موسیٰ بن عبد اللہ بن یزید سے وہ ابو حمید یا ابو حمیدہ سے زہیر کو شک ہے) وہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کوئی کسی عورت کو نکاح کا پیام دے تو اسے دیکھنے میں کوئی حرج نہیں۔ (حدیث) ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔ ظاہر یہی ہے کہ وہ ساعدی کے علاوہ ہیں، اس واسطے کہ اگر وہی ہوتے تو زہیر بن معاویہ کو ان کے بارے میں شک نہ گزرتا۔","",{"fn":"(1) مسند احمد (۴۲۴/۵)"}],[9749,"§۹۷۸۶ ۔ ابو حمیضہ انصاری(1)\nسالمی، نام معبد بن عباد۔ تذکرہ ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۳۱) استیعاب (۲۹۶۳)"}],[9750,"§۹۷۸۷ ۔ ابو حمیضہ حزنی(1)\nابن السکن اور عثمانی وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ابن حبان بھی لکھتے ہیں کہ انہیں شرف صحابیت حاصل ہے۔ ابن السکن اور طبرانی مسند اہل شام میں بحوالہ خفیف بن حارث روایت کرتے ہیں کہ مجھ سے ابو حمیضہ مزنی نے بیان کیا کہ ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کھانے میں شریک تھے، آپ ایک شخص سے مرد تھا یا عورت تھی بات کرنے میں مشغول تھے ہم تھوڑا تھوڑا کر کے کھانے لگے پھر آپ ہماری طرف متوجہ ہوئے اور کھانے میں شریک ہو گئے، اس کے بعد فرمایا: ایسے کھاؤ جیسے ایمان والے کھاتے ہیں۔ پھر بڑا لقمہ لے کر اشارہ کیا کہ ایسا اسی طرح کے پانچ یا چھ لقمے پھر اگر ان کے ساتھ کوئی چیز ہو تو فبہا ورنہ پانی پی کر اٹھ جائے۔(2) ابن السکن لکھتے ہیں: مجھے ان کی صرف یہی روایت ملی ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۲۳) تجرید (۱۶۰/۲)\n(2) اسد الغابہ (۴۲۱/۴)"}],[9751,"§۹۷۸۸ ۔ ابو حنش\nابن سعد نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا کہ کسی نے ان سے کہا آپ امارت (امیر بننے) کا سوال نہیں کرتے؟ ایسا ہی تجرید میں ہے۔"],[9752,"§۹۷۸۹ ۔ ابو حنہ\nپہلے بھی یہ نام گزرا ہے، واقدی نے یہی نام لیا ہے۔"],[9753,"§۹۷۹۰ ۔ ابو حلہ انصاری\nابو جبہ بن غزیہ کے بھائی ابن ابی خیثمہ نے ان کا ذکر کیا ہے اور میں نے مغلطائی کے قلم سے نقل کیا ہے۔"],[9754,"§۹۷۹۱ ۔ ابو حنہ (دوسرے)\nبقول بعض: ان کا نام مالک بن عامر یا ابن عمیر ہے، پہلے تذکرہ ہوا ہے۔"],[9755,"§۹۷۹۲ ۔ ابو حوالہ ازدی\nنام عبد اللہ ابن حوالہ، تذکرہ ہو چکا ہے۔"],[9756,"§۹۷۹۳ ۔ ابو حیان\nحیان کے حالات میں تذکرہ ہو چکا ہے۔ نسب بیان نہیں ہوا، جو ناموں میں سے حرف حاء میں گزرا ہے۔"],[9757,"§۹۷۹۴ ۔ ابو حیوہ کندی(1) یا حضرمی\nرجاء بن حیوہ کے دادا، ابو نعیم نے ان کا ذکر کیا ہے اور بسند طبرانی ان کی سند سے بحوالہ خارجہ بن مصعب بحوالہ رجاء بن حیوہ انہوں نے اپنے والد سے بحوالہ اپنے دادا روایت کی ہے۔ ایک باندی نبی صلی اللہ علیہ وسلم کے پاس سے گزری جو حج کر رہی تھی۔ آپ نے فرمایا: یہ کس کی ہے، لوگوں نے کہا: فلاں شخص کی۔ فرمایا: کیا وہ اس سے ہمبستر ہوتا ہے؟ لوگوں نے عرض کی: جی ہاں۔ فرمایا: وہ اس کے بچہ کا کیا کرے گا؟ اس کا دعویٰ کرے گا حالانکہ یہ اس کا بیٹا نہیں یا اسے غلام بنائے گا اور وہ اس کے کانوں اور آنکھوں میں غذا پہنچاتا ہے، میں نے تو اس پر ایسی لعنت بھیجنے کا ارادہ کر لیا تھا جو اس کے ساتھ قبر میں داخل ہو جائے۔(2)","",{"fn":"(1) اسد الغابہ (۵۸۲۶) تجرید (۱۶۱/۲)\n(2) مجمع الزوائد (۳۰۰/۴) المعجم الکبیر (۷۶۶/۲۲) اسد الغابہ (۴۲۲/۴)"}],[9758,"§۹۷۹۵ ۔ ابو حیہ تمیمی\nنام حابس تھا، پہلے ناموں میں تذکرہ ہو چکا ہے۔"],[9759,"§۹۷۹۶ ۔ ابو حدیرہ الاجذمی\nبقول بعض: جذامی دور نبوی پایا اور جابیہ میں سیدنا عمر رضی اللہ عنہ کے خطبہ میں موجود تھے۔ حافظ ابن عساکر رحمہ اللہ نے ان کا ذکر کیا ہے اور ان کا قصہ نقل کیا ہے کہ عبد العزیز بن نبھان نے کریب بن ابرہہ سے پوچھا: کیا آپ سیدنا عمر رضی اللہ عنہ کے خطبہ میں شریک تھے؟ انہوں نے کہا: نہیں۔ انہوں نے سفیان بن وہب کے پاس آدمی بھیجا، انہوں نے فرمایا: سیدنا عمر رضی اللہ عنہ کھڑے ہوئے، حمد و ثناء کے بعد فرمایا: جو مال اللہ تعالیٰ نے بطور غنیمت عطا کیا ہے، میں اسے لخم و جذام کے دو قبیلوں میں عدل و انصاف سے تقسیم کرتا ہوں۔ تو ابو حدیرہ کھڑے ہو کر کہنے لگے: اے عمر! میں انصاف کے بارے میں آپ کو اللہ تعالیٰ کا واسطہ دیتا ہوں۔۔۔ قصہ ہے۔ اسے مسدد نے اپنی مسند کبیر میں اور ابو عبید نے \"الاطول\" میں بروایت عبد الحمید بن جعفر بواسطہ یزید بحوالہ سفیان بن وہب اسی مفہوم میں نقل کیا ہے۔"],[9760,"§۹۷۹۷ ۔ ابو الحصین حنفی\nاسلام پر ثابت قدم رہنے والوں میں سے تھے، جن کے متعلق ابن المطرح حنفی سیدنا ابو بکر رضی اللہ عنہ کو مخاطب کر کے کہتا ہے: \"بنی حنیفہ میں سے ہم آپ کو دھوکا دینے والے نہیں، وہ اور منیٰ تک رقص کرنے والیاں کافر ہیں، ماسوائے میرے ابو حصین عامر اور ابن سفیان کے یہ نیک ہیں۔\" وثیمہ نے کتاب الردۃ میں اور ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[9761,"§۹۷۹۸ ۔ ابو حناءہ\nابن ابی ازہر دوسی۔ دور نبوی صلی اللہ علیہ وسلم پایا ہے۔ ابو ازہر کا قتل غزوہ بدر کے بعد نبی صلی اللہ علیہ وسلم کی حیات میں ہوا ہے۔ انہی ابو حناءہ کی ایک سمیہ نامی بیٹی تھی جس سے مجاشع بن مسعود نے نکاح کیا تھا، جس کا نصر بن حجاج کے ساتھ ایک واقعہ پیش آیا ہے۔"],[9762,"§۹۷۹۹ ۔ ابو حبیب عنبری(1)\nذہبی رحمہ اللہ(2) نے تجرید میں ان کا ذکر کیا ہے۔ ان میں اور ہر ماس کے دادا میں فرق ظاہر کیا ہے، جبکہ دونوں ایک ہیں۔ دونوں عنوانات میں ابو موسیٰ کی تخریج کا حوالہ دیا ہے جبکہ مجھے ذیل میں صرف ایک جگہ ملا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۹۱) تجرید (۱۵۸/۲)\n(2) تجرید (۱۵۸/۲)"}],[9763,"§۹۸۰۰ ۔ ابو حبیش غفاری(1)\nابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔ جیسا کہ اس کا بیان آ رہا ہے۔ یہ نام خاء اور نون سے \"حبیش\" ہے ابن مندہ نے درست لکھا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۹۳) تجرید (۱۵۸/۲)"}],[9764,"§۹۸۰۱ ۔ ابو حزامہ سعدی(1)\nابن مندہ نے حاء میں ذکر کیا ہے، لیکن درست خاء ہے۔ جیسا کہ تذکرہ ہونا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۰۴) تجرید (۱۵۹/۲)"}],[9765,"§۹۸۰۲ ۔ ابو الحسن الراعی\nذہبی نے تجرید میں ان کا تذکرہ کر کے لکھا ہے کہ کذاب (پرلے درجہ کا جھوٹا) ہے اس نے صحابی ہونے کا دعویٰ کیا ہے حالانکہ اس کا وجود ہی نہیں۔ اس سے روایت کرنے میں علی بن عون ایک شیخ منفرد ہے، جن سے صدر الدین بن حمویہ الجوینی اور موید محمد بن علی حلبی روایت کرتے ہیں، وہ کذاب ہے۔ میزان محمد(1) میں لکھتے ہیں: ابو الحسن بن نوفل راعنی نے کہا: شق قمر کی رات میں نے رسول اللہ صلی اللہ علیہ وسلم کو سوار کیا علی بن عون کہتے ہیں: چھ سو سال (یعنی چھٹی صدی کے بعد) ترکستان میں میری ان سے ملاقات ہوئی۔","",{"fn":"(1) میزان الاعتدال (۳۶۴/۶)"}],[9766,"§۹۸۰۳ ۔ ابو حسنہ خزاعی\nکسی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کر دیا ہے جو ایک لفظی غلطی کا نتیجہ ہے اور ابو ضمرہ انس بن عیاض سے بواسطہ ہشام بن عروہ بحوالہ اپنے والد مسند روایت کی ہے کہ ابو حسنہ خزاعی اونٹوں والوں نے انہیں بتایا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے ہدی کے جانوروں میں سے تھک کر لاچار ہو جانے والے جانوروں کے بارے میں پوچھا۔ حافظ صالح جزرہ فرماتے ہیں: اس میں ابو ضمرہ نے عجیب لفظی غلطی کی ہے۔ وہ تو ناجیہ خزاعی تھے۔ انہوں نے شروع میں الف کا اضافہ کر کے جیم کو کھینچ کر حسنہ سے ابو حسنہ بنا دیا۔ حرف نون میں ناموں کے حصہ میں صحیح طور پر حدیث پہلے بیان ہو چکی ہے۔"],[9767,"§۹۸۰۴ ۔ ابو حفصہ(1)\nمستغفری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے جو لفظی غلطی اور تبدیلی کا کرشمہ ہے۔ چنانچہ وہ بطریق شعبہ، مغیرہ بن عبد اللہ کے واسطہ سے روایت کرتے ہیں کہ میں ابو حفصہ کی مجلس میں بیٹھا پھر حدیث رقوب (جس شخص کی کوئی اولاد فوت نہ ہوئی ہو)(2) ذکر کی۔ درست نام ابو خصفہ ہے، ان شاء اللہ تعالیٰ خاء میں بیان ہوگا۔","",{"fn":"(1) اسد الغابہ (۵۸۱۴) تجرید (۱۵۹/۲)\n(2) مسند احمد (۳۶۷/۵) مجمع الزوائد (۱۱/۳)"}],[9768,"§۹۸۰۵ ۔ ابو حکیم بن ابی یزید الکرخی(1)\nبغوی نے ان کا ذکر کر کے کہا: مجھے جہاں تک علم ہے ان کی حدیث صرف عطاء بن السائب نے ذکر کی ہے، پھر بطریق حماد بن یزید انہوں نے بحوالہ اپنے والد روایت کی ہے۔ میں کہتا ہوں: اس صحابی کی کنیت ابو یزید ہے، حرف ی میں وضاحت ہوگی۔ اس لیے یہ لازم نہیں آتا کہ ان کے بیٹے کا نام حکیم ہو تو ان کی کنیت بھی ابو حکیم ہونی چاہیے۔ بغوی وغیرہ کی روایت میں ان کی کنیت ابو یزید ہی لکھی ہے، لہذا ان کا تذکرہ حرف حاء میں وہم پر مبنی ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۱۷) تجرید (۱۵۹/۲)"}],[9769,"§۹۸۰۶ ۔ ابو الحسیر\nانس بن رافع، ناموں میں تذکرہ ہوا ہے۔"],[9770,"§۹۸۰۷ ۔ ابو حیوہ الصنابحی(1)\nبقول ابو موسیٰ: ابو بکر بن ابی علی نے ان کا ذکر کیا ہے اور ان کی ایک حدیث بھی نقل کی ہے، لیکن نام اور نسبت میں لفظی غلطی کا ارتکاب کیا ہے، فرماتے ہیں: یہ نام تو ابو غیرہ ہے اور الصباحی ہے نہ کہ صنابحی۔ خاء میں درست نام ذکر ہوگا۔","",{"fn":"(1) اسد الغابہ (۵۸۲۵) تجرید (۱۵۹/۲)"}],[9771,"§۹۸۰۸ ۔ ابو حیہ النمیری\nذہبی رحمہ اللہ(1) نے تجرید میں ان کا ذکر کیا ہے کہ ان کا نام ہیثم بن الربیع ہے۔ ابن ناصر کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ سلف میں مجھے ان کی موافقت کرنے والا کوئی نہیں ملا۔ بلکہ واقعہ یہ ہے کہ ابو حیہ نہ صحابی ہیں اور نہ انہیں رویت و ادراک حاصل ہے۔ معجم الشعراء میں مرزبانی لکھتے ہیں: ابو حیہ میں بے وقوفی اور عقل کی خرابی تھی اور بصرہ فروکش ہوتے وہ رجزیہ اور قصیدہ گو شاعر تھے۔ ابو عمرو بن العلاء انہیں برتری دیتا تھا۔ انہوں نے ہشام بن عبد الملک کا دور بھی پایا ہے۔ منصور اور پھر مہدی کے دور حکومت تک زندہ رہے۔ جب منصور کا انتقال ہوا تو انہوں نے اس کا مرثیہ کہا، وہی مندرجہ ذیل شعر کے قائل ہیں:(2) \"خبردار! دوست کے گھر والوں میں سے ایک قبیلہ نے بوسیدہ چادر اوڑھ لی جب راتیں خلط ملط ہوگئیں۔ جب رات اور دن آدمی سے تقاضا کرنے لگیں تو اس سے ایسی چیز تقاضا کرنے لگ جاتی ہے جس کا تقاضا کرنا ملول اور بور نہیں کرتا۔\" محمد بن سلام الجمحی نے انہیں شعراء کے طبقہ میں سے بشار بن برد اور ان کے نیچے کے طبقہ کے شعراء میں شمار کیا ہے۔ ابو الفرج اصبہانی لکھتے ہیں: ابو حیہ الہیثم بن ربیع بن زرارہ بن کثیر بن جناب بن کعب بن مالک بن عامر بن نمیر بن عامر بن صعصعہ النمیری دور بنی امیہ اور بنی عباس کے بزرگ پیشرو مخضرمی شاعر ہیں۔ وہ بصرہ کے رہائشی اور فصیح رجزیہ اور قصیدہ گو شاعر تھے لیکن اس سب کے باوجود وہ بے وقوف، بزدل، بخیل، بے حد جھوٹے، بہر کیف ان تمام رزائل میں مشہور تھے۔ میں کہتا ہوں: شاید جن لوگوں نے انہیں صحابہ رضی اللہ عنہم میں شمار کیا ہے ان کی دلیل ان کا مخضرمی ہوتا ہے، جو ایک باطل دلیل ہے کیونکہ جن بعض مخضرمین کو کسی نے صحابہ رضی اللہ عنہم میں شمار کیا ہے ان سے مراد وہ لوگ ہیں جنہوں نے دور جاہلیت اور اسلام دیکھا ہے، نیز اموی اور عباسی حکومتوں کا دور پانے والے کو مخضرمی کہا جاتا ہے۔ اس لحاظ سے ابو حیہ قسم ثانی میں شامل ہیں نہ کہ قسم اول میں۔ ابو بکر بن ابی خیثمہ بحوالہ محمد بن سلامہ تھی نقل کرتے ہیں کہ ابو حیہ کی ایک تلوار تھی جس کا نام \"لعاب المنیۃ\" تھا۔ لیکن مزے کی بات کہ اس میں اور لکڑی میں کوئی فرق نہ تھا۔ وہ سب سے زیادہ بزدل تھے۔ مجھے ان کے ایک پڑوسی نے بتایا کہ ایک رات ان کے گھر کتا گھس آیا انہوں نے سمجھا شاید چور ہے۔ میں نے جھانک کر دیکھا انہوں نے اپنی تلوار لعاب المنیۃ سونت لی اور کہنے لگے: ارے او ہمیں دھوکا دینے والے! ہم پر جرات کرنے والے اللہ کی قسم! تو نے اپنے لیے بہت بری چیز منتخب کی ہے، مال تھوڑا ہے اور تلوار تیز اور چمکدار تم خود ہی میری طرف سے ملنے والی سزا سے پہلے ہی معافی مانگ لو۔ وہ یہ ساری باتیں صحن کے درمیان میں کھڑے ہو کر کہہ رہے تھے۔ اسی اثناء میں وہ کتا باہر نکلا تو انہوں نے بے ساختہ کہا: \"الحمد للہ اللہ تعالیٰ نے تمہیں کتے کی صورت میں بدل دیا اور ہمیں جنگ سے بچا لیا۔\" ابو محمد بن قتیبہ(3) لکھتے ہیں: ابو حیہ نمیری سب سے جھوٹا انسان تھا۔ ایک دن اس نے کہا کہ وہ صحرا میں جا کر کووں کو بلائے گا تو وہ اس کے اردگرد جمع ہو جائیں گے ان میں سے جتنے چاہے گا پکڑ لے گا۔ کسی نے اس سے کہا: ابو حیہ! اگر ہم تمہیں صحرا میں لے جائیں اور تم کووں کو بلاؤ اور وہ نہ آئیں تو پھر ہم تمہیں کیا سزا دیں؟ اس نے کہا: جب تو اللہ انہیں دور ہی رکھے۔ لکھتے ہیں: ایک دن اس نے کہا: مجھے ایک ہرن نظر آیا جس پر میں نے تیر پھینکا لیکن تیر بچ کر نکل گیا، بھاگتے ہوئے تیر پھر اس کے آڑے ہوئے پھر وہ بیچ نکلا پھر آڑے آیا اللہ کی قسم کئی بار تیر اس کے آڑے آتا اور وہ بیچ نکلتا، بالآخر اسے پچھاڑ دیا۔ مبرد نے بحوالہ ابن ابی حبیرہ روایت کی ہے کہ ابو حیہ نمیری بڑا دروغ گو شخص تھا وہ فرزدق کے حوالہ سے کئی باتیں بیان کرتا، ایک دن میں نے اس کو سنا کہنے لگا: ایک دفعہ ہرن نظر آیا تو میں نے اس پر تیر چلایا پھر اسی طرح کا واقعہ ذکر کیا۔ رقاشی بحوالہ امام اصمعی لکھتے ہیں: ابو حیہ نمیری ابو جعفر منصور کے دربار میں آیا، اس نے منصور کی مدح اور بنی حسن کی ہجو کر رکھی تھی۔ تو منصور نے اسے اس کی امید سے کم انعام دیا۔ تو وہ حیرہ چلا گیا جہاں خمارہ کے پاس شراب پینے لگا اور اس کا ایک مشکیزہ خرید لیا پھر اس کا اس کے ساتھ ایک برا قصہ ذکر کیا۔ ابن قتیبہ  لکھتے ہیں: ابن مناذر کی ابو حیہ نمیری سے ملاقات ہوئی تو کہا: مجھے اپنا کوئی شعر سناؤ! اس نے شعر سنایا۔ اس نے کہا: یہ کیا ہے؟ کہا: شعر ایسا ہوتا ہے؟ ابو حیہ نے کہا: کیوں اس میں کیا عیب ہے؟ یہی عیب ہے کہ تم نے سن لیا ہے۔ ابو عبید بکری \"شرح امالی القالی\" میں لکھتے ہیں: ابو حیہ نمیری اسلامی دور کا شاعر ہے اس نے بنی امیہ حکومت کا آخری زمانہ اور حکومت بنی عباس کا ابتدائی دور پایا ہے۔ اس کا انتقال منصور کی خلافت کے آخر میں ہوا۔ میں کہتا ہوں: پہلے جو حوالہ مرزبانی کا گزر چکا ہے کہ اس نے منصور کی وفات پر مرثیہ کہا تھا اس سے پتہ چلتا ہے اور مرزبانی ہی کا بیان ہے کہ سلمہ بن عیاش العامری شاعر نے ابو حیہ نمیری سے کہا: جانتے ہو؟ لوگ کیا کہتے ہیں؟ اس نے کہا: کیا کہتے ہیں؟ کہا کہ لوگ سمجھتے ہیں کہ میں تم سے زیادہ شاعر ہوں۔ اس نے کہا: انا للہ (افسوس!) لوگ ہلاک ہو گئے۔ اسی واقعہ کو مرزبانی نقل کرتے ہوئے لکھتے ہیں کئی لوگوں سے بحوالہ سلمہ بن عیاش العامری (جو بصرہ کے شعراء میں سے تھا) محمد بن سلیمان بن علی نے کہا کہ میں نے ابو حیہ سے کہا، پھر یہی الفاظ ذکر کیے۔ میں کہتا ہوں: محمد بن سلیمان کی گورنری مہدی کی جانب سے اور اس کے بعد بھی رہی۔ جو تقریباً ۱۶۰ھ اور اس کے بعد کا دور ہے۔ تو یہ مورخین وغیرہ کے اتنے زیادہ اقوال اس بات کی وضاحت کرتے ہیں کہ ابو حیہ نہ صحابی ہیں اور نہ اسے دور نبوت حاصل ہے اور یہی معتبر قول ہے۔ واللہ اعلم!","",{"fn":"(1) تجرید (۱۶۱/۲)\n(2) التجرید (۱۶۱/۲)\n(3) الشعر والشعراء لابن قتیبہ (۷۵۰)"}],[9772,"§۹۸۰۹ ۔ ابو خارجہ(1)\nعمرو بن قیس الخزرجی العبدی، ناموں میں ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۳۴)"}],[9773,"§۹۸۱۰ ۔ ابو خالد\nحکیم بن حزام الاسدی۔"],[9774,"§۹۸۱۱ ۔ ابو خالد\nیزید بن ابی سفیان الاموی، تذکرہ ہو چکا ہے۔"],[9775,"§۹۸۱۲ ۔ ابو خالد (بے نسبت)(1)\nان کا ابو احمد الحاکم نے بحوالہ امام بخاری، اسی طرح المستغفری نے ذکر کیا ہے کہ صحابی ہیں جن کی حدیث اعمش سے بواسطہ مالک بن حارث بحوالہ ابو خالد مروی ہے۔ انہیں شرف صحابیت حاصل ہے۔ فرمایا: ہم لوگ سیدنا عمر بن خطاب رضی اللہ عنہ کے پاس گئے، آپ نے اہل شام کو ہم سے زیادہ انعام دیا۔ ابن ابی شیبہ نے ان کا ذکر کیا ہے اور ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۳۴) استیعاب (۲۹۶۶) تجرید (۱۶۱/۲)"}],[9776,"§۹۸۱۳ ۔ ابو خالدہ(1)\nحارث بن قیس بن خلدہ بن مخلد بن عامر بن زریق بن عبد حارثہ بن مالک بن غضب بن جشم انصاری زرقی۔(2) ابن اسحاق رحمہ اللہ وغیرہ نے شرکاء بدر اور بیعت عقبہ وغیرہ کے مواقع میں ان کا ذکر کیا ہے اور امام واقدی رحمہ اللہ نے بطریق ضمرہ بن سعید نقل کیا ہے کہ ابو خالد زرقی کو جنگ یمامہ میں کئی گہرے زخم آئے جو خلافت فاروقی میں ہرے ہو کر بہہ پڑے جس سے ان کا انتقال ہو گیا۔","",{"fn":"(1) اسد الغابہ (۵۸۲۸) تجرید (۱۶۱/۲)\n(2) السیرۃ النبویۃ (۱۶۱/۲)"}],[9777,"§۹۸۱۴ ۔ ابو خالد حارثی(1)\nاز بنی حارث بن سعد ابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق ابراہیم بن بکیر بلوی بواسطہ بشیر ابن ابی قسیمہ سلامی روایت نقل کی ہے کہ مجھے ابو خالد حارثی، جو بنی حارث بن سعد سے تعلق رکھتے تھے، بتایا کہ میں ہجرت کر کے رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا میں نے دیکھا کہ آپ تبوک جانے کا ارادہ رکھتے ہیں تو ہم لوگ آپ کے ساتھ نکل پڑے، چلتے چلتے ہمارا گزر مود کی بستی حجر پر ہوا۔ آپ صلی اللہ علیہ وسلم نے ہمیں ان کے گھروں میں داخل ہونے سے منع فرمایا اور ہمیں ان کے پاس کے پانی کے چشموں اور کنوؤں سے بھی منع کر دیا۔۔۔ پھر بھی حدیث ذکر کی۔ اسی میں ہے کہ آپ جلدی ظہر کی نماز پڑھ کر ایک قبیلہ کے پاس آئے، وہاں آپ نے اپنے صحابہ رضی اللہ عنہم کو دیکھا تو فرمایا: تم لوگ ابھی تک اس کا پانی تیز کر رہے ہو۔ وہ چشمہ ایسا تھا کہ اس کا پانی کم تھا جس سے برتن بھی نہ بھرتا تھا۔ فرماتے ہیں: آپ نے اس جگہ کا نام تبوک رکھ دیا۔ اس کے بعد آپ نے اپنے ترکش سے ایک لمبا نیزہ نکال کر فرمایا: اتر کر یہ نیزہ اس میں گاڑ دو اور اللہ کا نام لینا۔ چنانچہ وہ اترے اور بسم اللہ پڑھ کر وہ نیزہ گاڑ دیا۔ تو پانی جوش سے فوارہ کی طرح نکلنے لگا۔(2) اسی قصہ میں ابراہیم فرماتے ہیں: ہمارے جذام کے ابو عقال نامی ایک صاحب آئے ان کے متعلق مشہور تھا کہ یہ ابدال ہیں۔ وہ کہنے لگے: مجھے وہ بابرکت جگہ دکھاؤ جہاں رسول اللہ صلی اللہ علیہ وسلم تشریف لائے تھے اور وہ چھوٹا سا گڑھا (معمولی سا گڑھا) تھا، جس سے پیالہ بھی نہ بھرتا تھا۔ آپ نے اللہ تعالیٰ سے دعا کی اور اسے جاری کر دیا۔ چنانچہ ہم انہیں لے کر ادھر گئے۔ وہ جب اس کے پاس کھڑے ہوئے تو کہنے لگے: ہاں یہی، یہی ہے۔ اللہ کی قسم! یہ وہ پانی ہے جسے جبرائیل علیہ السلام نے بہایا اور محمد صلی اللہ علیہ وسلم نے اس کے لیے برکت کی دُعا کی۔ یہ تو بڑی برکت والا ہے۔ فرماتے ہیں: وہ چشمہ بدستور اسی طرح رہا یہاں تک کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے ابن عریض یہودی کو بھیجا جس نے اسے پاٹ دیا۔ میں کہتا ہوں: اس حدیث کی سند میں غیر معروف راوی ہیں۔","",{"fn":"(1) اسد الغابہ (۵۸۲۹) تجرید (۱۶۱/۲)\n(2) جامع المسانید (۵۴۷/۱۳) اسد الغابہ (۴۲۴/۴)"}],[9778,"§۹۸۱۵ ۔ ابو خالد السلمی(1)\nمحمد بن خالد کے دادا بغوی نے کنی میں ان کا ذکر بطریق ابو اسحاق محمد بن خالد سلمی سے انہوں نے اپنے دادا سے جنہیں شرف صحابیت حاصل ہے روایت کی ہے، پھر ایک حدیث ذکر کی۔ محمد(2) بقول بعض: ان کا نام زید ہے جس کی تفصیل ناموں میں گزر چکی ہے۔ ابن مندہ نے ان کا نام الحلاج بتایا ہے، یہ بھی پہلے بیان ہو چکا، مجھے سوائے مذکورہ روایت کے کسی روایت میں ان کا، نام نہیں ملا۔","",{"fn":"(1) اسد الغابہ (۵۸۳۰)\n(2) مسند احمد (۲۷۲/۵) المعجم الکبیر (۸۰۱/۲۲) السنن الکبریٰ (۳۷۴/۳) مجمع الزوائد (۲۹۲/۲)"}],[9779,"§۹۸۱۶ ۔ ابو خالد الکندی(1)\nخالد بن معدان کے دادا۔ حسن سمرقندی نے اسی نام سے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ اور ابو موسیٰ کا قول ہے کہ انہوں نے ان کی کوئی روایت نقل نہیں کی۔","",{"fn":"(1) اسد الغابہ (۵۸۳۱) تجرید (۱۶۱/۲)"}],[9780,"§۹۸۱۷ ۔ ابو خالد القرشی(1)\nالمخزومی۔ خالد کے والد۔ ان سے ان کے بیٹے بحوالہ اپنے والد طاعون کے بارے نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں۔ تجرید(2) میں ان کا ذکر کر کے لکھا ہے: ان کی کوئی شان ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۳۳) استیعاب (۲۹۶۵) تجرید (۱۶۱/۲)\n(2) تجرید (۱۶۱/۲)"}],[9781,"§۹۸۱۸ ۔ ابو خداش اللحمی(1)\nشرف صحابیت حاصل ہے اور اہل شام میں شمار ہوتے ہیں ان سے عبد اللہ بن محیریز ان کا قول نقل کرتے ہیں۔(2) ابن مندہ نے ان کا اسی طرح مختصر ذکر کیا ہے اور ابن السکن نے بطریق ثور بن یزید بحوالہ عبد اللہ بن محیریز، ابو خداش صحابی رسول صلی اللہ علیہ وسلم ذکر کیا ہے، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کی معیت میں غزوہ کیا میں نے آپ صلی اللہ علیہ وسلم کو فرماتے سنا: \"تمام مسلمان تین چیزوں میں برابر کے شریک ہیں: پانی، گھاس اور آگ۔\"(3) قسم اخیر میں ان الفاظ پر اعتراض کا ذکر ہوگا اور وہ الفاظ یہ ہیں: ایک صحابی رسول۔","",{"fn":"(1) اسد الغابہ (۵۸۳۶) تجرید (۱۶۱/۲)\n(2) ابو داؤد (۳۴۷۷) مسند احمد (۳۶۴/۵) جامع المسانید (۵۴۹/۱۳) اسد الغابہ (۴۲۵/۴)\n(3) تجرید (۱۰۱/۲)"}],[9782,"§۹۸۱۹ ۔ ابو خراش\nحدرد بن ابی حدرد اسلمی۔ ناموں میں تذکرہ ہو چکا ہے۔"],[9783,"§۹۸۲۰ ۔ ابو خراش السلمی(1)\nبغوی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور ابن المقری نے حیوہ سے بواسطہ ولید بن ابی ولید روایت کی ہے کہ عمران بن ابی انس نے بحوالہ ابو خراش سلمی ان سے بیان کیا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جس نے ایک سال تک اپنے (مسلمان) بھائی سے ناراضگی رکھی تو گویا اس نے اس کا خون بہا دیا۔\" ان کے ہاں سلمی ہی لکھا ہوا ہے، حالانکہ وہ اسلمی ہیں۔(2) جیسا کہ ابن وہب نے بواسطہ حیوہ نقل کیا ہے۔ بقول بعض: یہی حدرد بن ابی حدرد ہیں جن کا تذکرہ ان سے پہلے ہوا ہے۔","",{"fn":"(1) ابو داؤد کتاب الادب باب فیمن یہجر اخاہ المسلم (۴۹۱۵)\n(2) اسد الغابہ (۵۸۴۷) تجرید (۱۶۲/۲)"}],[9784,"§۹۸۲۱ ۔ ابو الخریف بن ساعدہ(1)\nصیفی میں ذکر ہوا ہے۔","",{"fn":"(1) تجرید (۱۶۲/۲)"}],[9785,"§۹۸۲۲ ۔ ابو خزاعہ(1)\nحمص فروکش ہوئے، ان کی حدیث کثیر بن مرہ سے مروی ہے، تجرید میں ان کا ذکر ہے۔(2)","",{"fn":"(1) ایضا\n(2) اسد الغابہ (۵۸۴۲) تجرید (۱۶۲/۲)"}],[9786,"§۹۸۲۳ ۔ ابو خزامہ\nبنی حارث ابن سعد ہذیم عذری کے فرد ہیں ان کی حدیث زہری بواسطہ ابن ابی خزامہ وہ اپنے والد سے روایت کرتے ہیں۔ ابو خزامہ کا نام یعمر تھا، امام مسلم وغیرہ نے ان کا یہی نام بتایا ہے۔ فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: آپ کی کیا رائے ہے جو دم اور دوا ہم کرتے ہیں۔۔۔ (حدیث)(1) امام مسلم کی کتاب الکنی میں ابو خزامہ بن یعمر لکھا ہے، ایسا ہی یعقوب بن سفیان نے کہا اور بیہقی نے اسے قوی قول کہا ہے اور ایک اور طریق سے ان کا نام زید بن حارث بتایا ہے۔ ابو عمر لکھتے ہیں: ایک حدیث میں زہری سے راوی کی غلطی کی وجہ سے کسی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کر دیا ہے۔ جبکہ یہ تابعی ہیں، لگتا ہے ان کا میلان اس طرف ہے، جس نے یوں کہا: ابو خزامہ بحوالہ اپنے والد روایت کرتے ہیں۔ ابن فتحون لکھتے ہیں: ان کی حدیث باوردی اور طبرانی نے بطریق ابن قتیبہ نقل کی ہے جیسا کہ امام مسلم رحمہ اللہ نے کہا۔ اسی طرح یہ روایت طبرانی نے بطریق عبد الرحمن بن اسحاق بحوالہ زہری روایت کی ہے۔ بقول بعض: زہری بواسطہ ابو خزامہ وہ اپنے والد سے، اس کو ابن عبد البر نے راجح کہا ہے مہمات میں اس کی طرف اشارہ ہوگا۔ \"خزامہ\" ناموں اور حارث بن سعد اور سعد ہذیم میں اُن سب لوگوں کی غلطی کا بیان ہوا ہے، جنہوں نے ان کا ایسا ہی نام بتایا۔","",{"fn":"(1) مسند احمد (۴۲۱/۳)"}],[9787,"§۹۸۲۴ ۔ ابو خزامہ(1)\nرفاعہ بن عرابہ الجہنی۔ خلیفہ بن خیاط نے ان کی یہ کنیت بتائی ہے، ناموں میں تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۴۸) استیعاب (۲۹۷۰)"}],[9788,"§۹۸۲۵ ۔ ابو خزامہ بن اوس(1)\nبن اصرم بن زید بن ثعلبہ بن غنم انصاری۔(2) ابن اسحاق نے شرکاء بدر میں اور ابن حبان نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ لیکن میں نے ایک نسخہ میں جو حافظ ابو علی العسکری کے قلم سے لکھا ہے، اس نام کو الف کے بدلہ یاء سے \"خزیمہ\" دیکھا ہے۔ فرماتے ہیں: \"ابو خزیمہ\" میرے خیال میں یہ اسی نسخہ کا فساد ہے جس سے نقل کیا گیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۴۲) استیعاب (۲۹۷۰)\n(2) السیرۃ النبویۃ (۲۶۱/۲)"}],[9789,"§۹۸۲۶ ۔ ابو خزیمہ بن یربوع(1)\nبن عمرو انصاری عدوی کا بیان ہے کہ یہ اُحد میں شریک تھے۔ بقول بعض: ان کا نام مربوع ہے۔ ناموں میں تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۴۴) تجرید (۱۶۲/۲)"}],[9790,"§۹۸۲۷ ۔ ابو خصفہ(1)(2)\nعلی بن مدینی اور عبدہ بن عبد اللہ الصفار وغیرہ نے وہب بن جریر سے بواسطہ شعبہ بحوالہ میسرہ بن عبد اللہ بعضی روایت کی ہے، فرمایا: میں ابو خصفہ کی مجلس میں بیٹھا۔ انہوں نے فرمایا: ہمیں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم لوگ جانتے ہو فقیر کون ہے؟ ہم نے عرض کی: جس کے پاس مال نہ ہو۔ آپ نے فرمایا: (حقیقی) فقیر وہ ہے جس کا مال تو ہو لیکن اس نے آگے کچھ نہ بھیجا(3) آپ نے تین بار یہ ارشاد فرمایا: ایک روایت میں ہے کہ آپ سے رقوب کے بارے میں پوچھا گیا تھا، اس وقت آپ نے فرمایا تھا۔","",{"fn":"(1) اسد الغابہ (۴۲۹/۴)\n(2) اسد الغابہ (۵۸۴۵) تجرید (۱۶۲/۲)\n(3) مسند احمد (۳۶۷/۵) مجمع الزوائد (۱۱/۳) جامع المسانید (۵۵۴/۱۳) اسد الغابہ (۴۲۹/۴)"}],[9791,"§۹۸۲۸ ۔ ابو خصیفہ(1) (تصغیر ہے)\nطبرانی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق یزید بن عبد الملک نوفلی، زید بن خصیفہ وہ بواسطہ اپنے والد اپنے دادا کے حوالہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اچھے چہروں کے پاس بھلائی تلاش کرو۔\"(2) اسی سند سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے: \"جب تم میں سے کوئی اپنے گھر سے نکلے تو وہ (لا حول ولا قوۃ الا باللہ) پڑھ لیا کرے۔\"(3) میں کہتا ہوں: یزید ضعیف ہے ہمارے شیخ الشیوخ \"کتاب الوشی\" میں لکھتے ہیں: اگر یہ یزید بن خصیفہ ہی ہیں تو وہ یزید بن عبد اللہ بن خصیفہ مشہور ثقہ ہیں جو سائب بن یزید سے روایت کرتے ہیں۔ البتہ مجھے ان کے والد کا نام راویوں میں اور نہ ان کے دادا کا ذکر صحابہ رضی اللہ عنہم میں ملا ہے اور اگر یہ کوئی اور ہیں تو پھر مجھے نہ ان کے بارے علم ہے نہ ان کے والد اور دادا کے بارے میں۔ میں کہتا ہوں: یہی مشہور ہے ادھر العمری نے التہذیب میں یزید بن عبد الملک کو ان سے روایت کرنے والوں میں ذکر کیا ہے اور لکھا ہے کہ خصیف کے والد کا نام عبد اللہ بن یزید ہے۔ بقول بعض: وہی خصیف بن یزید ہیں۔ اس بنا پر مذکورہ حدیث کے صحابی خصیفہ ہوئے العمری نے یزید بن عبد اللہ بن خصیفہ کے سوانح میں لکھا ہے کہ خصیف کے والد کا نام یزید ہے ایک قول ہے: عبد اللہ بن یزید بن سعید بن ثمامہ الکندی ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۴۶) تجرید (۱۶۲/۲)\n(2) المعجم الکبیر (۹۸۲/۲۲) مجمع الزوائد (۱۹۵/۸) کنز العمال (۱۶۷۹۶) جامع المسانید (۵۵۵/۱۳)\n(3) المعجم الکبیر (۹۸۲/۲۲) مجمع الزوائد (۱۲۸/۱۰، ۱۲۹۹) جامع المسانید (۵۵۵/۱۳)"}],[9792,"§۹۸۲۹ ۔ ابو الخطاب(1)\nبقول ابو عمر: انہیں شرف صحابیت حاصل ہے۔ لیکن ان کا نام معلوم نہیں۔ ان سے وتر کے بارے میں ابو ثور بن ابی فاختہ ایک حدیث مروی ہے۔ ادھر ابن فتحون نے ان کا تعاقب کرتے ہوئے لکھا ہے درست یہ ہے کہ ان سے ثور نے روایت کی ہے۔ بغوی فرماتے ہیں: کوفہ کے رہائشی تھے۔ ابو احمد الحاکم لکھتے ہیں: ابراہیم بن عبد اللہ الغزامی صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے جن کی کنیت ان کے نام پر غالب ہے۔ ابن اسکن، ابن ابی خثیمہ، بغوی، عبد اللہ بن احمد نے اپنی کتاب \"الکنی\" میں اور طبرانی نے بطریق اسراکیل، بواسطہ ثور بن ابی فاختہ روایت کی ہے کہ میں نے ایک صحابی رسول اللہ صلی اللہ علیہ وسلم سے سنا جب ان سے وتر کے بارے میں پوچھا گیا کہ میرا دل تو چاہتا ہے کہ میں آدھی رات کے وقت اٹھ کر نماز پڑھوں اس وقت ہی وتر ادا کروں، بے شک اللہ تعالیٰ ساتویں کھڑی میں آسمان دنیا کی طرف (رحمت کا) نزول فرماتے ہیں۔ اور فرماتے ہیں: ہے کوئی دعا کرنے والا۔ (حدیث) اس کے آخر میں ہے: \"جب فجر کی نماز کا وقت ہوتا ہے تو بلند ہو جاتا ہے۔\"(2) ابو احمد زبیری کی روایت میں بحوالہ طبرانی ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے وتر کے بارے میں پوچھا: آپ کے علاوہ کسی نے یہ روایت مرفوع نقل نہیں کی۔","",{"fn":"(1) اسد الغابہ (۵۸۴۷) تجرید (۱۶۲/۲)\n(2) المعجم الکبیر (۹۷۶/۲۲) مجمع الزوائد (۲۴۵/۲) جامع المسانید (۱۲۹/۱۰) (۱۲۸/۱۰) جامع المسانید (۵۵۵/۱۳)"}],[9793,"§۹۸۳۰ ۔ ابو خلاد\nوہی سائب بن خلاد، ناموں میں تذکرہ ہو چکا ہے۔"],[9794,"§۹۸۳۱ ۔ ابو خلاد الرعینی(1)\nوہی عبد الرحمن بن زہیر، ان کا بھی پہلے ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۵۵)"}],[9795,"§۹۸۳۲ ۔ ابو خلاد(1) (بے نسبت)\nنبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ علیہ السلام نے فرمایا: \"جب ایسا شخص دیکھو جسے دنیا سے بے رغبتی نصیب ہوئی ہے تو اس کے قریب رہو۔\" (حدیث) ان سے ابو فروزہ الجرمی روایت کرتے ہیں۔ بقول بعض: ان میں واسطہ ابو مریم ہیں پھر امام بخاری(2) نے فرمایا: یہی بہتر ہے۔ یہ روایت بزار نے بطریق ابو فروزہ، بواسطہ ابو خلاد، جنہیں شرف صحابیت حاصل ہے نقل کی ہے اور لکھا ہے کہ ہم نے انہیں سند میں اس لیے شامل کیا کہ ان کا کہنا ہے: انہیں شرف صحابیت حاصل ہے۔ باوجودیکہ انہوں نے خود نہیں کہا کہ میں نے آپ علیہ السلام کو دیکھا یا آپ صلی اللہ علیہ وسلم کا ارشاد سنا ہے۔ ابن ابی عاصم نے یہی روایت اسی سند سے نقل کی ہے، جس کے سیاق میں وہ لکھتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا، لیکن ان کے ہاں بواسطہ ابو خالد(3) مروی ہے جبکہ درست ابو خلاد ہے۔ ادھر ابن مندہ کا خیال ہے کہ یہ سابقہ والی شخصیت ہیں۔ ابن ماجہ نے ان کا ذکر کیا تو فرمایا: بقول بعض ان کا نام عبد الرحمن بن زہیر ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۴۸) تجرید (۱۶۲/۲)\n(2) التاریخ الکبیر (۹۸/۹)\n(3) التاریخ الکبیر (۲۷/۸) اسد الغابہ (۵۸۴۹) تجرید (۱۶۲/۲)"}],[9796,"§۹۸۳۳ ۔ ابو خلف (خادم النبی صلی اللہ علیہ وسلم)\nنشری نے \"رتب الابراز\" میں ان کی ایک مرفوع حدیث نقل کی ہے کہ \"جب منافق کی تعریف کی جاتی ہے تو عرش تھر تھرانے لگتا ہے اور رب تعالیٰ ناراض ہوتا ہے۔\" انہوں نے یہ روایت بغیر اسناد کے نقل کی، میرے خیال میں اس میں سے انس رضی اللہ عنہ کا ذکر رہ گیا ہے۔"],[9797,"§۹۸۳۴ ۔ ابو خلید الفہری(1)\nبقول بعض ابو خلید یا ابو عنیفہ، جیم میں تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۵۷) استیعاب (۲۹۷۴)"}],[9798,"§۹۸۳۵ ۔ ابو خمیصہ(1)\nیہ معبد بن عبادہ ابن ثعیر انصاری، ناموں میں تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۵۷) استیعاب (۲۹۷۴)"}],[9799,"§۹۸۳۶ ۔ ابو خناس(1)\nخالد بن عبد العزیز الخزاعی، ناموں میں ذکر ہوا۔","",{"fn":"(1) تجرید (۱۸۲/۲)"}],[9800,"§۹۸۳۷ ۔ ابو خنیس الغفاری(1)\nان کا نام مشہور نہیں، ابن اسکن لکھتے ہیں: ان کی حدیث ان کے گھرانے سے مروی ہے۔ ابو بکر بن عمرو بن عبد الرحمن کی کتاب میں ان کی حدیث ہے۔ انہوں نے ایسا ہی \"عمرو\" لکھا ہے، جبکہ درست نام عمر ہے۔ وہ ابن عبد الرحمن بن عبد اللہ بن عمر امام مالک کے شیوخ واساتذہ میں شامل ہیں۔ ابو بکر اور ابو خنیس کے درمیان ایک اور راوی ہے۔ الحاکم ابو احمد کا قول ہے: انہیں شرف صحابیت حاصل ہے اور ان کی حدیث بحوالہ ابراہیم بن عبد الرحمن بن ابی ربیعہ نقل کی کہ میں نے ابو خنیس غفاری کو فرماتے سنا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ غزوہ تمہارہ میں نکلا، یہاں تک کہ جب ہم لوگ عسفان میں پہنچے تو اس کے صحابہ آپ کے پاس آ کر عرض کرنے لگے: اللہ کے رسول! بھوک نے ہمیں بے حال کر دیا، ہمیں کسی جانور کے ذبح کرنے کی اجازت دیجیے جسے ہم کھا سکیں۔۔۔۔ (حدیث) اسی میں سیدنا عمر رضی اللہ عنہ کا مشورہ ہے کہ آپ نے توشوں کو جمع کرنے کا کہا جس سے برکت ہوئی پھر یہ لوگ چل پڑے۔ راستہ میں بارش ہوئی اور یہ لوگ سواریوں سے اترے اور مدینہ لگا کر بارش کا پانی پیا، آپ صلی اللہ علیہ وسلم نے لوگوں کو خطبہ میں فرمایا: جس میں تین آدمی آئے جن میں سے دو بیٹھ گئے اور ایک اعراض کر کے چلا گیا، کیا میں تمہیں تین آدمیوں کی بات نہ سناؤں۔'(2) (حدیث) ذہلی فرماتے ہیں: یہ ابو بکر، ابن عمر بن عبد الرحمن بن عبد اللہ بن عمر ہیں۔ اور امام مالک رضی اللہ عنہ کے شیخ ہیں۔ میں کہتا ہوں: ابن ابی عاصم اور دولابی نے اپنے دوسرے شیوخ سے اپنی روایتوں میں ان کا یہی نسب بیان کیا ہے، جو عبد اللہ بن رجاء سے منقول ہے۔ حدیث کی سند حسن ہے، جو ہم بروایت اسماعیل بن امالی الحالی کے جزو ثانی میں عالی سند سے سنی ہے۔ صحیحین میں اس کا شاہد موجود ہے۔ اس کا ایک اور شاہد، بحوالہ ان کے حاکم کی کتاب میں سیدنا انس رضی اللہ عنہ سے منقول ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۵۱) استیعاب (۲۹۷۵) تجرید (۱۶۲/۲)\n(2) بخاری کتاب العلم باب من قعد ینتہی بہ المجلس (۶۶) کتاب الصلاۃ باب الحلق والجلوس فی المسجد (۴۷۴) دلائل النبوۃ (۱۲۲/۶) جامع المسانید (۵۲۲/۱۳)"}],[9801,"§۹۸۳۸ ۔ ابو خثیمہ الجعفی\nعبد الرحمن بن ابی سمرہ، تذکرہ ہو چکا ہے۔"],[9802,"§۹۸۳۹ ۔ ابو خثیمہ الانصاری السالمی(1)\nحدیث کعب بن مالک میں ان کی توبہ کے قصہ کی طویل حدیث میں ان کا ذکر آتا ہے۔ اس میں ہے غزوہ تبوک میں ایک شخص کے گھوڑے کی دھول اڑتی دکھائی دی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اللہ کرے ابو خثیمہ ہی ہو!(2) تو اللہ کی قدرت وہ ابو خثیمہ ہی تھے۔ امام واقدی رحمہ اللہ نے فرمایا: ان ابو خثیمہ کا نام عبد اللہ بن خثیمہ ہے وہ اُحد میں شریک ہوئے اور خلافت یزید بن معاویہ تک زندہ رہے۔","",{"fn":"(1) اسد الغابہ (۵۸۵۲) تجرید (۱۶۲/۲)\n(2) مسلم کتاب التوبہ (۲۷۴۷) دلائل النبوۃ (۲۲۲/۵) جامع المسانید (۵۲۳/۱۳)"}],[9803,"§۹۸۴۰ ۔ ابو خثیمہ انصاری (دوسرے ہیں)\nان کا نام مالک بن قیس، بقول بعض: یہ وہی ہیں جنہوں نے ایک صاع کھجوروں کا صدقہ پیش کیا جس پر منافقین نے انہیں ملامت کی تھی۔ ابن کلبی وغیرہ کا بیان ہے: یہ وہی پہلے والے ساتھی ہیں اور ان کا نام مالک بن قیس ہے۔ عبد اللہ بن خثیمہ نہیں۔ واللہ اعلم!"],[9804,"§۹۸۴۱ ۔ ابو خثیمہ الحارثی\nحامہ میں ان کے متعلق تنبیہ گزر چکی ہے، اور جو اس کا قائل ہے کہ یہ نام ابو خثیمہ ہے تو اس بارے میں احتمال ہے۔ واللہ اعلم"],[9805,"§۹۸۴۲ ۔ ابو الخیر الکندی\nیہ خثیمہ ہیں، ناموں میں تذکرہ ہوا ہے۔"],[9806,"§۹۸۴۳ ۔ ابو خیرہ العبدی(1)\nثم الصباحی۔ صباح ابن لکیز بن افصی کی طرف نسبت ہے جو عبد القیس کا بطن ہے۔ امام بخاری رحمہ اللہ نے تاریخ میں مختصراً، خلیفہ، دولابی، طبرانی اور ابو احمد الحاکم نے روایت نقل کی ہے کہ ابو خیرہ الصباحی نے فرمایا کہ عبد القیس کا جو وفد رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا میں اس میں تھا، تو آپ نے ہمیں پیلو(2) کی شاخ مسواک کرنے کے لیے دی۔ ہم نے عرض کی، اللہ کے رسول! اگر چہ ہمارے پاس شاخیں ہیں پھر بھی ہم آپ کا ہدیہ اور آپ کی کرامت قبول کرتے ہیں۔ جس پر آپ صلی اللہ علیہ وسلم نے فرمایا: اے اللہ! عبد القیس کی مغفرت فرما! اپنی مرضی سے بلا کسی دباؤ کے مسلمان ہوئے ہیں جبکہ ایک قوم سوائے جنگ اور گھبراہٹ کے ایمان لانے سے رکی رہی۔(3) یہ طبرانی کے الفاظ ہیں۔ دولابی کی روایت میں ہے ہم چالیس مرد تھے۔ خطیب نے \"المؤتلف\" میں ان کا ذکر کیا ہے کہ مجھے معلوم نہیں کہ کسی نے ان کا نام لیا ہو۔","",{"fn":"(1) اسد الغابہ (۵۸۵۳) تجرید (۱۶۲/۲)\n(2) مسواک کرنے کا درخت\n(3) مسند احمد (۲۰۵/۴) المعجم الکبیر (۹۲۳، ۹۲۴/۲۲) مجمع الزوائد (۶۲/۵) جامع المسانید (۵۶۰/۱۳) اسد الغابہ (۴۳۲/۴) دولابی فی الکنی (۲۷/۱)"}],[9807,"§۹۸۴۴ ۔ ابو خیرہ(1) (دوسرے ہیں)\nاثیری نے انہیں صحابی سے علیحدہ ذکر کیا ہے اور ان کی ایک حدیث نقل کی ہے اس کو طبرانی(2) نے نقل کیا ہے، لیکن وہ صحابی کے حالات میں درج کی ہے، میرے نزدیک یہ اور ہیں۔ عبد اللہ بن ہشام بن حسان بن یزید بن ابی خیرہ بحوالہ ابو خیرہ روایت کرتے ہیں: میرے اونٹ تھے جن پر میں بوجھ لادتا تھا۔ میں نبی صلی اللہ علیہ وسلم کے پاس آیا اور خیبر میں شرکت کی، فرمایا یا حنین فرمایا۔ تو ہم لوگ ان کے لیے اپنے اونٹوں پر پانی لاتے تھے۔ (حدیث) اسی میں ہے: تو رسول اللہ صلی اللہ علیہ وسلم نے میرے لیے برکت کی دعا کی اور میرے بیٹے کو بھی دعا دی۔","",{"fn":"(1) اسد الغابہ (۵۸۵۴) تجرید (۱۹۲/۲)\n(2) المعجم الکبیر (۹۲۲/۲۲)"}],[9808,"§۹۸۴۵ ۔ ابو خراش الہذلی(1)\nخویلد بن مرہ ہیں، ناموں میں تذکرہ ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۴۶) استیعاب (۲۹۶۹)"}],[9809,"§۹۸۴۶ ۔ ابو خرفاء العامری\nانہیں دور نبوت نصیب ہوا ہے۔ ابو الفرج اصبہانی(1) نے ذوالرمہ شاعر کے حالات میں ان کا تذکرہ بطریق محمد بن حجاج تمیمی ہے کہ میں حج کر کے جب \"مران\" پہنچا تو خرقاء ذوالرمہ کی اہلیہ کے ہاں آیا، انہیں سلام کر کے اپنا تعارف کرایا تو وہ فرمانے لگیں: کیا تم حجاج بن عمرو بن زید کے بیٹے ہو؟ میں نے کہا: جی ہاں۔ کہنے لگیں: اللہ تعالیٰ تمہارے والد پر رحم کرے وہ جلد ہی موت کے ہاتھ لگ گئے! تم کہاں سے آ رہے ہو؟ میں نے کہا: حج کر کے۔ کہنے لگیں: تمہارا حج ناقص ہے، کیا تم نے اپنے چچا ذوالرمہ کا یہ شعر نہیں سنا؟ \"حج کی تکمیل اس طرح ہوتی ہے کہ سواریاں خرقاء کے سامنے کھڑی ہوں درآنحالیکہ اس نے نقاب اتارا ہوا ہو۔\" راوی کا بیان ہے کہ وہ گھر کے صحن میں بیٹھے ہوئے بھی کھڑی لگ رہی تھیں، کیونکہ وہ دراز قد، سفید رنگ، ضعیف العمر، پیر خم تھیں۔ میں نے ان سے ان کی عمر پوچھی تو وہ بتانے لگیں: مجھے یہ تو معلوم نہیں کہ اب میں کتنے سالوں کی ہوں البتہ مجھے یاد ہے کہ جب سیدنا حسین رضی اللہ عنہ شہید ہوئے تو اس وقت میں کم سن بچی تھی، میں نے شمر بن ذی الجوشن کا دور پایا ہے، میرے والد نے جاہلیت کا زمانہ پایا اور اس میں کئی حملے کیے۔","",{"fn":"(1) الاغانی (۱۲۳/۱۶)"}],[9810,"§۹۸۴۷ ۔ ابو الخیبری\nجاہلیت کا دور پایا ہے۔ ان سے محرز مولا ابو ہریرہ رضی اللہ عنہ وہ واقعہ نقل کرتے ہیں جو ان کا ان کے ساتھیوں کے ساتھ حاتم طائی کی قبر پر پیش آیا۔ جو ہم نے خرائطی کی \"مکارم الاخلاق\" میں بطریق ہشام بن کلبی بحوالہ محرز بن ابی ہریرہ رضی اللہ عنہ روایت کیا ہے۔ عبد القیس کا ایک گروہ حاتم طائی کی قبر کے پاس سے گزرا اور اسی کے پاس ان لوگوں نے پڑاؤ کر لیا۔ ان میں سے ایک شخص اٹھا اور حاتم طائی کی قبر پر لات مار کر کہنے لگا: \"ہماری ضیافت کرو۔\" پھر یہ لوگ سو گئے، وہی شخص گھبرایا ہوا جاگا اور اس کی زبان پر یہ شعر جاری تھے: \"ابو الخیر کی! تم خاندان کے بڑے ظالم اور منہ پھٹ آدمی ہو۔ تم اپنے ساتھیوں کو لے کر ایک ایسے گڑھے کے پاس مہمان نوازی طلب کرنے آئے ہو جس کی (میت کی) کھوپڑی زمین میں گل مل گئی ہے۔ کیا تم میرے بستر کے پاس میرے لیے گناہ بے ضیافتی تلاش کرنا چاہتے ہو جبکہ تمہارے پاس ہی قبیلہ طی اور اس کے جانور بندھے ہیں۔ ہماری تو عادت ہے کہ ہم جانوروں کے پاس آ کر ان میں سے عمدہ کا انتخاب کر کے اپنے مہمان کو خوب سیر کر کے کھلاتے ہیں۔\" کیا دیکھتا ہے کہ اس کی اونٹنی کی کھینچیں کٹی پڑی ہیں، وہ (خود) ذبح کر چکے ہیں۔ صبح جب چلنے لگے تو اپنے اس ساتھی کو کسی نے پیچھے سوار کر لیا۔ اسی اثناء میں انہیں دور سے پکارتا ہوا ایک شخص نظر آیا جو ایک اونٹ پر سوار تھا اور دوسرا اس کے ساتھ بندھا ہوا تھا، ان کے قریب آ کر کہنے لگا: تم لوگوں میں سے ابو الخیر کی کون ہے؟ اس نے کہا: میں ہوں۔ آنے والے نے کہا: میں نے خواب میں حاتم کو دیکھا ہے، انہوں نے مجھے بتایا کہ تمہاری اونٹنی سے انہوں نے تمہارے ساتھیوں کی ضیافت و مہمان نوازی کی ہے، اور مجھے حکم دیا ہے کہ میں تمہیں سواری کا جانور دوں تو یہ اونٹ ہے اس پر سوار ہو جاؤ۔ اسی قصہ کو ابو الفرج اصبہانی(1) نے مذکورہ سند سے حاتم طائی کے حالات میں نقل کیا ہے کہ محرز بن ابی ہریرہ رضی اللہ عنہ سے ولید مولا ابو ہریرہ رضی اللہ عنہ نے سنا کہ ابو الخیر کی نامی ایک شخص تھا جس کا گزر اپنے ساتھیوں سمیت حاتم طائی کی قبر پر سے ہوا۔ اس رات ابو الخیر کی پکار کر کہنے لگا: اپنے مہمانوں کی ضیافت کرو۔ پھر وہ واقعہ ذکر کیا۔ اسی میں ہے: پھر وہ جتنی اللہ کی رضا تھی چلے اس کے بعد انہیں ایک سوار نظر آیا۔ وہ عدی بن حاتم رضی اللہ عنہ تھے، کہنے لگے: حاتم کو میں نے خواب میں دیکھا ہے، انہوں نے تمہاری اونٹنی سے ضیافت کی ہے اور اس بارے میں اشعار کہے ہیں، جنہیں اتنا دہرایا کہ مجھے یاد ہو گئے۔ پھر ان کا ذکر کیا، اسی میں ہے انہوں نے مجھے حکم دیا ہے کہ میں تمہیں اس اونٹ کو سواری کے لیے دوں چنانچہ اس پر سوار ہو کر چلے گئے۔","",{"fn":"(1) الاغانی (۱۰۱/۱۶)"}],[9811,"§۹۸۴۸ ۔ ابو خالد الکندی(1)\nابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے کہ ابو بکر بن ابی علی نے ان کا ذکر کیا اور بطریق ابو فروزہ روایت نقل کی ہے کہ میں نے ابو موسیٰ کو فرماتے سنا کہ میں نے ابو خالد کندی سے سنا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جب تم ایسا شخص دیکھو جسے دنیا سے بے رغبتی جیسی صفت عطا ہوئی ہے تو اس کے قریب رہو۔\" — (حدیث)(2) یہ حدیث ابو خالد الرعینی کی ہے، ان کی کنیت اور نسبت میں وہم ہو گیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۳۲) تجرید (۱۶۱/۲)\n(2) ابن ماجہ الزہد باب الزہد فی الدنیا (۴۱۰۱) المعجم الکبیر (۹۷۵/۲۲) اسد الغابہ (۴۲۴/۴)"}],[9812,"§۹۸۴۹ ۔ ابو خداش(1)\nانہیں شرف صحابیت حاصل ہے، ان سے ابو عثمان روایت کرتے ہیں کہ ہم لوگ ایک غزوہ میں تھے لوگوں نے ایک جگہ پڑاؤ کیا، رستہ مار لیا اور اونٹنی پرے لگا لیے، جب آپ نے یہ صورتحال دیکھی تو فرمایا: سبحان اللہ! میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کئی غزوات میں شرکت کی ہے میں نے آپ صلی اللہ علیہ وسلم کو فرماتے سنا: \"تمام مسلمان تین چیزوں میں شریک ہیں: گھاس، پانی اور آگ۔\"(2) ابن مندہ نے ایسا ہی ذکر کیا ہے۔ ابو عمر لکھتے ہیں: ابو خداش الصغریٰ کا نام حبان بن زید شامی ہے۔ ان کا صحابی ہونا صحیح ثابت نہیں۔ کسی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کر دیا ہے اور مذکورہ حدیث کی طرف اشارہ کیا اور پھر اسے بیان کیا۔ فرماتے ہیں: اسے یزید بن ہارون وغیرہ نے حریز بن عثمان سے بحوالہ ابو خداش نقل کیا ہے۔ بعض نے ان کا نام حبان بن زید شرعی بتایا ہے، اور یہ اضافہ نقل کیا ہے: ایک صحابی رسول صلی اللہ علیہ وسلم سے مروی ہے، وہ نبی صلی اللہ علیہ وسلم سے نقل کرتے ہیں۔ انہی ابو خداش نے سیدنا عمرو بن العاص رضی اللہ عنہ سے روایت کی ہے۔ میں کہتا ہوں: ادھر ابو الیمان نے حریز بن عثمان سے بحوالہ حبان روایت کی ہے جن کی کنیت ابو خداش ہے کہ شرعب کے ایک بزرگ روم کی سرزمین پر فروکش ہوئے۔ پھر وہ حدیث نقل کی۔ اس سے ابن عبد البر کی بات کی موافقت ہوتی ہے۔ ابن مندہ کے انہیں دو شخص قرار دینے پر ابن الاثیر نے ان کا عیب شمار کیا ہے۔ ایک سلمی جن کا ذکر قسم اول میں گزر چکا ہے، دوسرے شرعبی۔ فرماتے ہیں: ابو عمر نے انہیں جن سے ابو عثمان روایت لیتے ہیں اور انہیں جن سے ابن محیریز روایت کرتے ہیں، ایک شخص کہا ہے۔ یہی درست ہے۔ جبکہ ابن مندہ اور ان کے متبعین نے ان میں فرق کیا ہے۔ انہوں نے پہلے شخص کو شرعب کا بزرگ اور دوسرے کو بنی قرار دیا ہے۔ اگر انہیں اس بات کا علم ہوتا کہ شرعب لخم کا بطن ہے تو ویسا ہی کرتے جیسا ابو عمر نے لکھا ہے۔ میں کہتا ہوں: انہوں نے شرعب اور لخم کی وجہ سے فرق نہیں کیا۔ بلکہ وجہ یہ بنی کہ دوسری روایات سے یہ ظاہر ہوا کہ شرعبی ہی حبان بن زید شام کے مشہور تابعی ہیں صحابی نہیں۔ وہ تو کسی صحابی سے روایت لیتے ہیں۔ اور کبھی کوئی مرسل روایت کرتے ہیں یہ ابو خالد سلمی صحابی کے علاوہ ہیں۔ اگرچہ وہ حدیث جو ان دونوں نے روایت کی ہے ایک ہے۔ اسے عمرو بن علی فلاس نے یحییٰ قطان سے انہوں نے ثور بن یزید سے انہوں نے حریز سے انہوں نے ابو خداش سے انہوں نے کسی صحابی رسول صلی اللہ علیہ وسلم سے نقل کیا ہے۔ فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سات غزوات میں شرکت کی، یا فرمایا: تین میں شرکت کی۔ عمرو بن علی کہتے ہیں: میں نے معاذ بن معاذ سے پوچھا تو انہوں نے حریز بن عثمان سے بواسطہ حبان بن زید شرعبی انہوں نے بحوالہ ایک صحابی رسول صلی اللہ علیہ وسلم کی روایت کی ہے۔ عمرو فرماتے ہیں: پھر ہمارے پاس یزید بن ہارون آئے، انہوں نے ہم سے یہ حدیث بیان کی۔ یہی روایت ابو احمد الحاکم نے \"الکنی\" میں لکھی ہے جس کی سند یوں ہے بطریق فلاس، پھر بطریق اسمعیل بن رجاء الزبیدی، حریز بحوالہ ابو خداش وہ ایک صحابی سے نقل کرتے ہیں۔ ابو داؤد نے سنن میں عالی سند نقل کی، علی بن جعفر سے وہ حریز سے وہ حبان سے وہ قرن کے ایک شخص سے وہ مسدد، وہ عیسیٰ بن یونس وہ حریز سے وہ خداش سے وہ ایک مہاجر صحابی سے، اس سے پتہ چلا کہ ابو خداش کا نام حبان بن زید شرعی ہے اور یہ تابعی ہیں صحابی نہیں۔ اور انہوں نے کسی نام والے صحابی سے روایت کی ہے جن کی نسبت میں اختلاف ہے، کوئی شرعی اور کوئی قرنی تو کوئی کچھ اور کہتا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۳۵) تجرید (۱۶۱/۱)\n(2) مسند احمد (۳۶۴/۵) جامع المسانید (۵۴۹/۱۳) اسد الغابہ (۴۲۵/۴)"}],[9813,"§۹۸۵۰ ۔ ابو خداش الشرعبی(1)\nحبان بن زید۔ کسی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ شام کے رہنے والے ہیں ان کا صحابی ہونا ثابت نہیں۔ یہ ابن عبد البر کا قول ہے، اور بات بھی یہی ہے۔","",{"fn":"(1) استیعاب (۲۹۶۷) تجرید (۱۶۱/۲)"}],[9814,"§۹۸۵۱ ۔ ابو خراش الرعینی\nبقول ذہبی:(1) یحییٰ بن مخلد نے ان کی ایک حدیث روایت کی ہے۔ میں کہتا ہوں: ابن مندہ نے انہیں صحابہ رضی اللہ عنہم میں ذکر کیا ہے جو غلطی ہے۔ چنانچہ وہ بطریق ابو نعیم بحوالہ ابو خراش الرعینی روایت کرتے ہیں، فرمایا: میں جب مسلمان ہوا تو میری دونوں بیویاں آپس میں سگی بہنیں تھیں، میں نبی صلی اللہ علیہ وسلم کے پاس آیا، آپ صلی اللہ علیہ وسلم سے اس کا ذکر کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ان دونوں میں سے جس کو چاہو طلاق دے دو۔\"(2) میں کہتا ہوں: سند میں نقص اور تحریف واقع ہوئی ہے۔ اسی روایت کو ابن ابی شیبہ نے بحوالہ ابو خراش، وہ الدیلمی سے جو فیروز سے نقل کی ہے۔ یہ حدیث انہی سے مشہور ہے اور ان کا قصہ مشہور ہے۔ ابن ماجہ نے یہ روایت سنن میں ابو بکر بن ابی شیبہ سے اسی سند سے نقل کی ہے اور ابو احمد الحاکم نے الکنی میں بطریق حسین بن سنان حرانی، عبد السلام بن حرب سے نقل کی ہے یوں ابن مندہ کی سند سے ابو وہب کا نام رہ گیا۔ اور جیشانی کی جگہ ابو الخیر کو برقرار رکھا، نیز اس سے اصحابی بھی رہ گیا۔ ابن مندہ نے رعینی کے حالات میں عمران بن عبد اللہ کی روایت، ابو خراش سے انہوں نے فضالہ بن عبید سے نقل کی ہے جو ہم پر مبنی ہے۔ ادھر امام بخاری رحمہ اللہ اور ابو احمد الحاکم نے فضالہ سے روایت کرنے والے شخص میں (ان دونوں نے یہ نہیں کہا: وہ رعینی ہیں) اور رعینی میں فرق کیا ہے۔ جس کی تائید ابن یونس کے \"تاریخ مصر\" میں لکھے قول سے بھی ہوتی ہے کہ ابو خراش اور ان سے روایت کرنے والے عمران کی اس کے علاوہ کوئی حدیث معروف نہیں۔","",{"fn":"(1) اسد الغابہ (۵۸۳۸) تجرید (۱۶۱/۲)\n(2) ابو داؤد کتاب الطلاق باب فی من اسلم و عندہ نساء (۲۲۴۳) ترمذی کتاب النکاح (۱۱۲۹، ۱۱۳۰) ابن ماجہ کتاب النکاح (۱۹۵۰) مسند احمد (۲۳۲/۴) جامع المسانید (۵۵۲/۱۳) اسد الغابہ (۴۲۶/۴)"}],[9815,"§۹۸۵۲ ۔ ابو خلف (خادم النبی صلی اللہ علیہ وسلم)\nنشری نے \"رتب الابراز\" میں بحوالہ ابو خلف خادم النبی صلی اللہ علیہ وسلم کا یہ قول نقل کیا ہے کہ \"جب فاتح کی تعریف کی جاتی ہے تو عرش تھر تھرانے لگتا ہے اور رب تعالیٰ ناراض ہوتا ہے۔\" ان کے ہاں اسی طرح بغیر سند کے لکھا ہے جبکہ اس میں سیدنا انس رضی اللہ عنہ کا نام رہ گیا ہے، مذکورہ حدیث ابو یعلیٰ کی کتاب میں ایک کمزور ترین سند سے بواسطہ ابو خلف اعمیٰ (نابینا) بحوالہ سیدنا انس رضی اللہ عنہ خادم النبی صلی اللہ علیہ وسلم مروی ہے۔ ابن ماجہ نے ابو خلف کی بحوالہ سیدنا انس رضی اللہ عنہ ایک اور حدیث بھی روایت کی ہے۔"],[9816,"§۹۸۵۳ ۔ ابوداؤد انصاری مازنی(1)\nبقول بعض: ان کا نام عمرو یا عمیر ہے، دولابی کا قول ہے: میں نے ابن البرقی کو فرماتے سنا: ان کا نام عمیر بن عامر بن مالک بن ضباء بن مبذول بن عمرو بن غنم بن مازن بن النجار ہے۔ \"التصحیف\" میں عسکری رقمطراز ہیں کہ جنہیں فرمایا کرتے تھے کہ یہ لفظ ابوداؤد (الف سے پہلے ہمزہ کے ساتھ) ہے، ابن الدباغ نے اسے صحیح کہا ہے ایسا ہی ابوعلی الغسانی نے ابن عبدالبر کے \"اوہام\" میں لکھا ہے جبکہ ابن فنتون نے اس کی تردید کرتے لکھا ہے کہ مسلم، نسائی، ابواحمد، طبری، ابن جارود اور ابن السکن سب نے ان کی کنیت ابوداؤد (واؤ سے پہلے الف کے ساتھ) لکھی ہے۔ میں کہتا ہوں: یہی مشہور ہے۔ ابن اسحاق(2) اور خلیفہ نے اسی پر بھروسا کیا ہے۔ اور اسی کے ساتھ ان سے مروی روایت میں آیا ہے۔ ابن اسحاق وغیرہ کا بیان ہے کہ وہ بدر اور بعد کے معرکوں میں شریک ہوئے۔ امام احمد نے بطریق ابن اسحاق بحوالہ ان کے والد انہوں نے ایک مازنی سے انہوں نے ابوداؤد کے حوالہ سے بدر میں ان کی شرکت کا قصہ ذکر کیا ہے۔(3) دولابی کی بطریق جعفر بن حمزہ بن ابی داؤد مازنی بواسطہ ان کے والد بحوالہ ان کے دادا جو بدری صحابی ہیں روایت ہے، فرمایا: ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کی معیت میں نکلے یہاں تک کہ مسجد ذوالحلیفہ کے پاس پہنچے آپ نے چار رکعتیں پڑھیں اور پھر حج کا احرام باندھا۔ (حدیث) ابن سعد نے بواسطہ واقدی انہوں نے اپنی مسند سے بحوالہ ام عمارہ نقل کیا ہے کہ ابوداؤد مازنی اور سلیط بن عمرو بیعت عقبہ میں حاضر ہونا چاہتے تھے، پہنچے تو لوگ بیعت کر چکے تھے بعد میں انہوں نے اسعد بن زرارہ کے ہاتھ پر بیعت کی جو عقبہ کی رات نقباء کے سردار تھے۔","",{"fn":"(1) اسد الغابہ (۵۸۵۵) تجرید (۱۶۳/۲)\n(2) السیرۃ النبویۃ (۲۰۷/۲)\n(3) مسند احمد (۴۵۰/۵) جامع المسانید (۵۶۵/۱۳) السیرۃ النبویۃ (۲۰۷/۲)"}],[9817,"§۹۸۵۴ ۔ ابودجانہ انصاری(1)\nان کا نام سماک بن خرشہ یا ابن اوس بن خرشہ بتایا جاتا ہے۔ اس پر اتفاق ہے کہ وہ بدر میں شریک اور یمامہ میں شہید ہوئے تھے۔ ابن اسحاق(2) نے بطریق یزید بن السکن مسنداً روایت کی ہے کہ جنگ بدر میں گھمسان کا رن پڑا تو مصعب بن عمیر رضی اللہ عنہ اور ابودجانہ سماک بن خرشہ آپ علیہ السلام کا دفاع کرنے لگے، مصعب تو شہید ہو گئے اور ابودجانہ کو بہت زخم آئے۔ بقول بعض: وہ مسیلمہ کذاب کے مارنے میں شریک تھے۔ صحیح مسلم میں بطریق حماد بن سلمہ بواسطہ ثابت بحوالہ انس رضی اللہ عنہ ان کا ذکر ثابت ہے کہ نبی صلی اللہ علیہ وسلم نے اُحد کے روز ہاتھ میں تلوار لے کر فرمایا: اس تلوار کو اس کے حق سمیت کون پکڑے گا؟ تو ابودجانہ نے وہ تلوار سنبھالی اور اس سے مشرکین کی کھوپڑیاں چیرتے چلے گئے۔ \"الکنی\" میں دولابی نے بطریق عبید اللہ بن وازع بواسطہ ہشام بن عروہ وہ بحوالہ اپنے والد روایت کرتے ہیں کہ زبیر بن عوام رضی اللہ عنہ نے فرمایا: اُحد کے روز رسول اللہ صلی اللہ علیہ وسلم نے ایک تلوار پیش کر کے فرمایا: اس تلوار کو اس کے حق سمیت کون پکڑے گا؟ تو ابودجانہ سماک بن حرب کھڑے ہوئے۔ عرض کی: میں، لیکن اس کا حق کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس سے کسی مسلمان کو قتل نہ کرنا اور اسے ہاتھ میں لے کر کسی کافر سے نہ بھاگنا\"۔(3)","",{"fn":"(1) اسد الغابہ (۵۸۵۶) تجرید (۱۶۳/۲)\n(2) السیرۃ النبویۃ (۵۴/۳)\n(3) مسلم کتاب فضائل الصحابۃ باب من فضائل ابی دجانۃ (۶۳۰۳) مسند احمد (۱۲۲/۳) دلائل النبوۃ (۲۳۴/۲)"}],[9818,"§۹۸۵۵ ۔ ابوالدحداح انصاری(1)(2)(3)\n\"انصاری\" حلیف ہونے کی وجہ سے کہلاتے ہیں۔ ابوعمر لکھتے ہیں: مجھے نہ ان کا نام معلوم ہے اور نہ نسب۔ میں ان کے بارے میں اس سے زیادہ نہیں جانتا کہ انصار میں سے ہیں اور ان کے حلیف ہیں۔ بغوی لکھتے ہیں: ابودحداح انصاری، اس سے زیادہ کچھ نہیں کہا۔ امام احمد، بغوی اور حاکم نے بطریق حماد بن سلمہ بواسطہ ثابت بحوالہ سیدنا انس رضی اللہ عنہ روایت کی ہے کہ ایک شخص نے عرض کی: اللہ کے رسول! فلاں کے پاس کھجور کا درخت ہے جس سے میں اپنی چار دیواری بنانا چاہتا ہوں۔ آپ علیہ السلام نے اس شخص سے کہا: \"اسے وہ کھجور کا درخت جنت کے ایک کھجور کے درخت کے بدلہ میں دے دو\"۔ اس شخص نے انکار کر دیا۔ سیدنا ابودحداح اس کے پاس آئے اور اس سے فرمایا میرے گھر کے بدلہ میں یہ کھجور کا درخت مجھے فروخت کر دو، تو اس نے ایسا ہی کیا۔ نبی صلی اللہ علیہ وسلم کے پاس آئے۔ عرض کی: اللہ کے رسول! میں نے اپنے گھر کے بدلہ میں وہ کھجور کا درخت خرید لیا ہے، اب اس سائل کو دے دیں میں نے وہ آپ کو دے دی ہے۔ جس پر نبی صلی اللہ علیہ وسلم نے فرمایا: \"ابودحداح کے لیے جنت میں کتنے ہی کھجور کے پھیلے ہوئے درخت ہیں\"۔ آپ صلی اللہ علیہ وسلم نے یہ جملہ کئی بار فرمایا۔ پھر وہ اپنے گھر آئے، اپنی اہلیہ سے کہا: ام دحداح اس گھر سے نکلو کیونکہ میں نے اسے ایک جنتی کھجور کے درخت کے بدلہ میں بیچ دیا ہے، تو انہوں نے فرمایا: کیا ہی وارے کا سودا ہے یا اس سے ملتا جلتا کوئی لفظ کہا۔ یہی روایت ہمیں مسند عبد بن حمید میں عالی سند سے لکھی ملی ہے۔ جو حدیث جابر بن سمرہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے ابودحداح کا جنازہ پڑھایا پھر ایک شاخ لے کر فرمایا... (حدیث) اس کے آخر میں ہے: \"ابودحداح کے لیے کتنے ہی کھجور کے درخت ہیں\"۔ اسی طرح یہ روایت انہوں نے حجاج بن محمد سے بواسطہ شعبہ، سماک سے بحوالہ ان کے روایت کی ہے۔ نیز محمد بن جعفر سے بواسطہ شعبہ بحوالہ ابودحداح نقل کی ہے۔ مسلم نے بندار سے انہوں نے محمد بن جعفر سے کہ ابودحداح سے مروی ہے ابن مندہ نے بطریق عبداللہ بن حارث بحوالہ ابن مسعود روایت کی ہے کہ جب یہ آیت نازل ہوئی: \"جو اللہ تعالیٰ کو اچھا قرض دیتا ہے اللہ تعالیٰ اسے بڑھا چڑھا کر دے گا\"۔ تو ابودحداح(4) نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم اللہ تعالیٰ ہم سے قرض لینا چاہتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ہاں۔ (حدیث) اس میں ان کے صدقہ کا ذکر ہے۔ بطریق عقیل، ابن شہاب سے مرسلا اس کا مفہوم منقول ہے۔ ثابت بن دحداح کے حالات میں گزر چکا ہے کہ ان کی کنیت ابودحداح تھی، وہ نبی صلی اللہ علیہ وسلم کی حیات میں فوت ہوئے جس کی بنیاد پر ابوعمر نے کہا: وہ یہی ہیں۔ حق بات یہ ہے کہ وہ اور ہیں۔ ابن اسحاق کی روایت ہے کہ ابودحداح کا انتقال ہوا جو انصار میں باہر سے آکر آباد ہوئے۔ تو نبی صلی اللہ علیہ وسلم نے عاصم بن عدی کو بلا بھیجا اور فرمایا: کیا اس کا تم لوگوں سے کوئی نسبی رشتہ ہے؟ عرض کی نہیں۔ تو آپ صلی اللہ علیہ وسلم نے ان کی میراث ان کے بھتیجے ابولبابہ بن عبدالمنذر کو دی۔ یہ واقعہ مناسب ہے کہ ثابت کے لیے ہو کیونکہ پہلے ان کے حالات میں گزر چکا ہے کہ وہ احد میں زخمی ہوئے، بقول بعض: اس میں شہید ہوئے۔ ایک قول ہے کہ زندہ رہے بعد میں زخم مندمل ہوا تو وفات پاگئے۔ یہی راجح ہے۔ رہے یہ صحابی جن کا عنوان ہے تو یہ امیر معاویہ رضی اللہ عنہ کے زمانہ تک زندہ رہے۔ چنانچہ ابونعیم کی روایت ہے کہ ابودحداح نے امیر معاویہ رضی اللہ عنہ سے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جس کی پریشانی دنیا ہوگی اللہ تعالیٰ اس کے لیے میرا پڑوس حرام کر دے گا۔ کیونکہ میں دنیا کی بربادی کے لیے مبعوث ہوا ہوں نہ کہ دنیا کو آباد کرنے کے لیے\"۔ تشریح(5) (یعنی دنیا کی وہ چیزیں جو اللہ تعالیٰ کی یاد سے غافل اور اس میں رکاوٹ پیدا کرتی ہیں)۔ میں کہتا ہوں: فضیل تک اس کی سند صحیح نہیں۔ اسی روایت کو طبرانی نے اس سے مکمل نقل کیا ہے جو جبرون بن عیسیٰ سے بواسطہ یحییٰ بن سلیمان بحوالہ فضیل مروی ہے۔ اور جبرون کی روایت کردہ حدیثیں بے بنیاد ہوتی ہیں۔","",{"fn":"(1) اسد الغابہ (۵۸۵۷) تجرید (۱۶۳/۲)\n(2) مجمع الزوائد (۳۲۴/۹) موارد الظمان (۲۲۷۱)\n(3) البقرۃ (۲۴۵)\n(4) ذکرہ ابن ابی شیبہ فی مصنفہ (۲۶۵/۱۱)\n(5) المعجم الکبیر (۷۶۴/۲۲) کنز العمال (۶۲۷۹) مجمع الزوائد (۳۲۵/۹) اسد الغابہ (۴۳۴/۴)"}],[9819,"§۹۸۵۶ ۔ ابوالدخداح(1)\nبقول بعض: ابوالدخداح ان کا نام ثابت ہے۔ ناموں میں ذکر ہو چکا ہے، مقاتل بن سلیمان کا زعم ہے کہ ان کا نام عمر ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۶۴) استیعاب (۲۹۸۰)"}],[9820,"§۹۸۵۷ ۔ ابوالدرداء انصاری(1)\nنام عویمر، تذکرہ ہو چکا ہے۔ بقول بعض: عامر اور لقب عویمر ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۶۵)"}],[9821,"§۹۸۵۸ ۔ ابودرہ البلوی(1)\nابن یونس نے ان کا ذکر کیا ہے کہ انہیں شرف صحابیت حاصل ہے فتح مصر میں شریک تھے اور ان کی کوئی روایت مشہور نہیں۔ علی بن قدید فرماتے ہیں: میں نے ان کے گھر کے دروازہ پر لکھا دیکھا: \"یہ گھر ابودرہ بلوی صحابی رسول اللہ صلی اللہ علیہ وسلم کا ہے\"۔(2)","",{"fn":"(1) اسد الغابہ (۵۸۵۹) تجرید (۱۶۳/۲)\n(2) اسد الغابہ (۴۳۵/۴)"}],[9822,"§۹۸۵۹ ۔ ابوالدنیا(1) (بے نسبت)\nمطین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا اور محمد بن اسماعیل، ہشام بن عمار، صدقہ بن خالد، عمر بن قیس، عطاء ان کے سلسلہ سند میں ابوالدنیا سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص جمعہ کے لیے آئے وہ غسل کر لیا کرے\"۔ ہشام بن عمار فرماتے ہیں: یہ ابوالدنیا مشہور صحابی ہیں۔ اسی طرح بغوی نے بحوالہ ہشام نقل کیا ہے اور ابن مندہ بطریق ولید بن مسلم، عمر بن قیس سے نقل کرتے ہیں، لیکن متن میں یہ الفاظ ہیں: \"جمعہ کا غسل ہر بالغ پر واجب ہے\"۔ ابونعیم لکھتے ہیں: یہی درست ہے(2) پہلے الفاظ غلط ہیں: \"العلل\" میں الدارقطنی لکھتے ہیں: یہ روایت محمد بن بکر برسانی نے عمر بن عطاء سے بحوالہ ابودرداء نقل کی ہے۔ صدقہ بن خالد فرماتے ہیں: عمر کی عطاء سے بحوالہ ابوالدنیا سند لفظاً غلط ہے۔ ابوبشر دولابی \"الکنی\" میں لکھتے ہیں: اس میں غلطی ہشام بن عمار سے ہوئی۔ خطیب نے \"الکفایۃ\" میں بطریق احمد بن علی الابار روایت کی ہے کہ میں نے ہشام بن عمار سے پوچھا: کیا آپ سے صدقہ بن خالد نے بیان کیا... پھر وہ حدیث نقل کی۔ انہوں نے فرمایا: ہاں۔ الابار فرماتے ہیں: مجھے یہ حدیث اہل حمص کے ہاں عمر بن قیس سے بواسطہ عطاء بحوالہ ابودرداء لکھی نظر آتی ہے۔ مجھے لگتا ہے ان کی کتاب میں اندماج ہوکر \"عن ابی الدنیا\" ہو گیا، یعنی راء دال میں مل گئی۔ ولید بن مسلم کا مذکورہ طریق ان سب کی تردید کرتا ہے اور یہی بات باقی رہ جاتی ہے کہ اس میں لفظی غلطی ہوئی ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۶۰) تجرید (۱۶۳/۲)\n(2) بخاری کتاب الجمعۃ باب غسل الجمعۃ (۸۷۹، ۸۹۵) مسلم کتاب الجمعۃ باب وجوب غسل الجمعۃ (۱۹۵۴) ابوداؤد کتاب الطہارۃ باب الغسل یوم الجمعۃ (۳۴۱) اسد الغابہ (۴۲۵/۴)"}],[9823,"§۹۸۶۰ ۔ ابوالدھماء البنانی\nدور نبوت پایا ہے۔ اور سیدنا عمر رضی اللہ عنہ کے ہاں آئے، اور آپ سے استدعا کی بنی بنانہ کو واپس قریش میں لوٹایا جائے۔ وہ لوگ ان سے جدا ہو کر بنی شیبان کے پاس چلے گئے تھے، ابودھماء ان کے سردار تھے۔ سیدنا عمر رضی اللہ عنہ نے ان سے فرمایا: مجھے تو اس بات کا علم نہیں۔ تو سیدنا عثمان رضی اللہ عنہ نے آپ کو بتایا کہ ان کی بات صحیح ہے تو آپ نے ان سے فرمایا: آئندہ سال تم لوگ میرے پاس آ جانا۔ اسی اثناء میں ان کے سردار ابودھماء قتل ہو گئے، جب سیدنا عثمان رضی اللہ عنہ کی خلافت کا زمانہ ہوا تو یہ لوگ آگئے آپ نے انہیں قریش میں شامل کر دیا۔ اور جب سیدنا عثمان شہید کر دیئے گئے تو انہیں بھی واپس لوٹا دیا گیا۔ جس کے بارے میں عبدالرحمن بن حسان کہتے ہیں: ☆ \"سدھائے ہوئے بھیجی نے ایسی ضرب لگائی کہ اس نے بنانہ کو بنی شیبان میں واپس پہنچا دیا\"۔ یعنی جب سیدنا عثمان رضی اللہ عنہ کی شہادت ہوئی یہ سارا واقعہ بلاذری کا ذکر کردہ ہے۔ زبیر بن بکار نے اس کا کچھ حصہ نقل کیا ہے وہ اپنی روایت میں لکھتے ہیں: سیدنا عثمان رضی اللہ عنہ نے فرمایا کہ میرے والد انہیں سلام بھیجا کرتے تھے اور میرے پوچھنے پر فرمانے لگے: یہ ہماری بنی لوی بن غالب سے ہی کھچڑی قوم ہے۔"],[9824,"§۹۸۶۱ ۔ ابوالدرداء (بے نسبت)\nایک مرسل حدیث روایت کرنے کی بنا پر کسی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کر دیا ہے جو وہم پر مبنی ہے۔ چنانچہ ابن ابی الدنیا اور الشعب میں بیہقی ان کے طریق اور ابودرداء الرہاوی تک ان کی سند سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دنیا سے احتیاط کرو کیونکہ یہ ہاروت و ماروت سے بڑھ کر جادوگرنی ہے\"۔ (حدیث) بیہقی فرماتے ہیں: بعض کا قول ہے(1) ابودرداء رہاوی سے وہ ایک صحابی سے نقل کرتے ہیں۔ ذہبی(2) لکھتے ہیں: ہمیں معلوم نہیں یہ ابودرداء کون ہیں اور وہ حدیث منکر ہے، اس کی کوئی اصل نہیں۔","",{"fn":"(1) کنز العمال (۶۰۶۵) اتحاف السادۃ المتقین (۶۸/۸) کشف الخفاء (۵۸/۱)\n(2) میزان الاعتدال (۵۲۲/۴)"}],[9825,"§۹۸۶۲ ۔ ابوالدیلمی\nبغوی نے ان کا ذکر کیا ہے، میرے خیال میں درست ابن الدیلمی ہے جو فیروز ہیں، فاء میں جن کا ذکر ہو چکا ہے۔ بغوی لکھتے ہیں: یہ شام کے رہنے والے ہیں، ان کے نسب کا پتہ نہیں۔ پھر بطریق عروہ بن رویم، بواسطہ ابوادریس الخولانی بحوالہ ابودیلمی روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سب سے افضل عبادت اللہ تعالیٰ کے بارے میں اچھا گمان رکھنا ہے\"۔(1) فرمایا: اللہ تعالیٰ فرماتے ہیں: میں اپنے بندہ سے اس کے گمان کے مطابق معاملہ کرتا ہوں۔","",{"fn":"(1) کنز العمال (۵۸۴۳) جمع الجوامع (۶۲۴۶)"}],[9826,"§۹۸۶۳ ۔ ابوذباب المذحجی(1)\nاز سعد العشیرہ۔ بقول ابوعمر: ان کے اسلام لانے کی بڑی دلچسپ حدیث ہے، وہ شاعر بھی تھے۔ یہی عبداللہ بن ابی ذباب کے والد ہیں۔ ابوموسیٰ نے ذیل میں ان کا ذکر کیا ہے کہ حسن بن احمد سمرقندی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے: \"ابوذباب سعدی\" اس سے زیادہ کچھ نہیں لکھا۔ ابوموسیٰ نے بطریق عمارہ بن زید بحوالہ عبداللہ بن ابی ذباب انہوں نے اپنے والد سے نقل کیا ہے، فرمایا: میں شکار کا شوقین تھا۔ پھر ایک واقعہ ذکر کیا، پھر فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس آیا وہ جمعہ کا دن تھا میں آپ کے منبر کے روبرو بیٹھا تھا، آپ خطبہ دینے منبر پر چڑھے حمد و ثناء کے بعد فرمایا: \"میں واضح معجزات و دلائل کے ساتھ تمہاری طرف اللہ کا رسول (بن کر آیا) ہوں، اور میرے منبر کے آگے سعد العشیرہ کا ایک شخص بیٹھا ہے جو اسلام لانے آیا ہے، اس نے مجھے اور نہ میں نے اسے اس سے پہلے کبھی دیکھا ہے، نماز کے بعد یہ تم لوگوں سے ایک عجیب واقعہ ذکر کرے گا\"۔ فرماتے ہیں: آپ نے نماز پڑھائی مجھے آپ سے بڑی مسرت ہوئی، نماز کے بعد فرمانے لگے: سعد العشیرہ کے بھائی قریب ہو جاؤ، ہمیں اپنا، صافی اور قراط یعنی اپنے کتے اور اپنے بت کا واقعہ سناؤ۔ فرماتے ہیں: میں کھڑے ہو کر اپنا واقعہ سنانے لگا۔ یہاں تک کہ جب وہ قصہ ختم ہونے لگا تو میں نے دیکھا کہ آپ صلی اللہ علیہ وسلم کا چہرہ خوشی کی وجہ سے سونے کی طرح چمک رہا تھا۔ پھر آپ صلی اللہ علیہ وسلم نے مجھے اسلام کی دعوت دی اور میرے سامنے قرآن مجید پڑھا تو میں مسلمان ہو گیا۔ (حدیث) ایسا ہی \"شرف المصطفیٰ\" میں ابوسعید نیشاپوری نے طویل نقل کیا ہے، اس کے آخر میں ہے پھر میں نے آپ سے اپنی قوم کے پاس آنے کی اجازت مانگی، میں نے جا کر انہیں اسلام کی رغبت دلائی تو وہ مسلمان ہو گئے۔ میں انہیں لے کر نبی صلی اللہ علیہ وسلم کے پاس آ گیا۔ اسی کے متعلق میں کہتا ہوں: ☆ \"جب رسول اللہ صلی اللہ علیہ وسلم ہدایت لے کر آئے تو میں نے ان کا اتباع کیا اور قراط کو ذلت کے گھر میں پھینک دیا۔ سعد العشیرہ کو میری طرف سے یہ پیام کون دے گا کہ میں نے فنا ہونے والی چیز کے بدلہ باقی رہنے والی چیز (آخرت) خرید لی ہے۔\"","",{"fn":"(1) کنز العمال (۵۸۴۳) جمع الجوامع (۶۲۴۶)"}],[9827,"§۹۸۶۴ ۔ ابوذباب (دوسرے)\nفاکہی نے بطریق محمد بن یعقوب بن عتبہ انہوں نے اپنے والد سے انہوں نے حارث بن ابی ذباب سے وہ اپنے والد عباس سے نقل کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے قصی بن کلاب کے اشعار پڑھے: ☆ \"میں لوئی کی اولاد سے محتاط لوگوں کا بیٹا ہوں، مکہ میں میری ولادت ہوئی اور میں یہیں پلا بڑھا۔ میرے لیے بطحاء ہے جس کا معد کو پتہ ہے اور اس کا ظاہری علاقہ جو چاہے میں بھی وہی چاہتا ہوں۔ اگر اس میں قیدار اور غیب کی اولاد امید نہ کرے تو میں غالب نہیں\"۔"],[9828,"§۹۸۶۵ ۔ ابوذر الغفاری(1)(2)(3)\nمشہور زاہد (تارک الدنیا)۔ سچی بات کرنے والے۔ ان کے اور ان کے والد کے نام میں اختلاف ہے۔ مشہور یہ ہے کہ وہ جندب بن جنادہ بن السکن ہیں، ایک قول ہے: ابن عبداللہ۔ ایک قول ہے: ان کا نام بریر، بقول بُر بر تصغیر ہے۔ یہی اختلاف ان کے والد کے بارے میں ہے۔ صرف اسکن جو ان کے دادا ہیں ان کے بارے میں نہیں۔ بقول بعض: یزید اور عرفہ ایک قول ہے: ان کا نام یہی اسکن بن جنادہ بن قیس بن عمرو بن منکمیل (تصغیر ہے) ابن صغیر (یہ بھی تصغیر ہے) ابن حرام، ابن غفار، ایک قول ہے: ان کے دادا کا نام سفیان بن عبید بن حرام بن غفار ہے اور ان کی والدہ کا نام رملہ بنت وقیعہ غفاریہ ہے، ایک قول ہے: یہ عمرو بن عبسہ کے ماں شریک بھائی ہیں۔ ابن ماجہ کی روایت میں لکھا ہے کہ نبی صلی اللہ علیہ وسلم نے ابوذر رضی اللہ عنہ سے فرمایا: اے جنید! تصغیر کے ساتھ، یہ اختلاف جو ان کے اور ان کے والد کے نام میں ہے سارے کا سارا ابن عساکر نے بحوالہ ان کے قائلین نقل کیا ہے۔ وہ لکھتے ہیں: بریر بریق کی لفظی بگڑی ہوئی صورت ہے۔ ایسا زید اور یزید ہے۔ اسلام کی طرف سبقت کرنے والے ہیں۔ ان کے اسلام لانے کا واقعہ دو طرح سے صحیحین میں ہے، جن میں اختلاف ظاہر ہے۔ بخاری کی کتاب میں بطریق ابوحمزہ بحوالہ ابن عباس رضی اللہ عنہما منقول ہے کہ جب ابوذر رضی اللہ عنہ کو نبی صلی اللہ علیہ وسلم کی بعثت کی اطلاع ملی تو انہوں نے اپنے بھائی سے کہا: تم اس وادی میں جانا اور مجھے اس شخص کی اطلاع دو جس کا کہنا ہے کہ وہ نبی ہے اور اس کے پاس آسمان سے وحی آتی ہے اس کی بات غور سے سننا پھر مجھے آکر بتانا۔ چنانچہ وہ بھائی روانہ ہوا اور وہاں پہنچ کر آپ علیہ السلام کی گفتگو سنی پھر ابوذر کے پاس واپس آیا اور ان سے کہا: میں نے دیکھا ہے وہ شخص اچھے اخلاق کا حکم دیتا ہے اور ایسا کلام سناتا ہے جو شعر و شاعری سے بالاتر ہے۔ تو ابوذر بولے: میں جو چاہتا تھا اس کی تم نے مجھے تشفی نہ کرائی پھر خود سامانِ سفر اور ایک پانی کا مشکیزہ لیا اور چلتے چلتے مکہ پہنچ گئے مسجد میں آئے، نبی صلی اللہ علیہ وسلم کو جانتے نہ تھے تلاش کیا اور کسی سے پوچھنا مناسب نہ سمجھا یہاں تک کہ شام پڑگئی۔ وہیں ٹیک لگا کر لیٹ گئے۔ سیدنا علی رضی اللہ عنہ نے دیکھا کہ ایک مسافر شخص ہے چنانچہ یہ ان کے پیچھے ہو لیے۔ اور کسی نے ایک دوسرے سے نہیں پوچھا یہاں تک کہ صبح ہوگئی پھر اپنی مشک اور زاد سفر لے کر مسجد میں آگئے۔ یہ دن بھی گزر گیا اور نبی صلی اللہ علیہ وسلم سے ملاقات نہیں ہوئی شام ہوئی تو اسی جگہ لیٹ گئے۔ سیدنا علی رضی اللہ عنہ گزرے اور دل میں کہنے لگے: اس مسافر کا ابھی تک گھر نہیں آیا پھر انہیں اٹھا کر اپنے ساتھ لے گئے۔ اور کسی نے دوسرے سے نہیں پوچھا یہاں تک کہ تیسرا دن گزر گیا پھر سیدنا علی رضی اللہ عنہ نے ہی پوچھا: تم مجھے بتاتے نہیں کہ کیسے آنا ہوا؟ انہوں نے فرمایا کہ اگر تم مجھ سے عہد کرتے ہو کہ میری رہنمائی کرو گے تو میں بتاتا ہوں۔ چنانچہ انہوں نے وعدہ کیا تو انہوں نے بتا دیا۔ سیدنا علی رضی اللہ عنہ نے فرمایا: وہ برحق ہیں۔ اور واقعی اللہ کے رسول صلی اللہ علیہ وسلم ہیں۔ صبح تم میرے پیچھے پیچھے چلنا اگر مجھے تمہارے بھائی کی کوئی تشویشناک بات محسوس ہوئی تو میں پیشاب کے بہانے ٹھہر جاؤں گا۔ اور اگر میں چلتا رہا تو میرے پیچھے چلتے رہنا، یہاں تک کہ تم میرے ساتھ اس گھر میں داخل ہو جانا جہاں میں داخل ہوں گا۔ چنانچہ وہ ان کے پیچھے روانہ ہوئے یہاں تک کہ نبی صلی اللہ علیہ وسلم کے پاس جا پہنچے، یہ بھی وہیں چلے گئے۔ آپ صلی اللہ علیہ وسلم کی بات سنی اور اسی جگہ مسلمان ہو گئے۔ نبی صلی اللہ علیہ وسلم نے ان سے فرمایا: \"اپنی قوم کے پاس واپس چلے جاؤ اور انہیں بتاؤ یہاں تک کہ تمہارے پاس میرا حکم پہنچے\"۔ عرض کی: اس ذات کی قسم جس کے قبضہ میں میری جان ہے، میں ان لوگوں کے درمیان ضرور اس کا اعلان کروں گا چنانچہ وہاں سے باہر نکلے مسجد حرام میں آئے اور بلند آواز سے کہا: أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ۔ لوگ ان پر ٹوٹ پڑے اور مارتے مارتے بے دم کر دیا۔ سیدنا عباس رضی اللہ عنہ نے آ کر انہیں اپنے پہلو میں دبوچ لیا اور فرمانے لگے: رکو! تم جانتے نہیں یہ غفاری آدمی ہے جو شام تک تمہاری تجارتی گزرگاہ ہے، یوں انہیں وہاں سے چھڑایا، دوسرے دن پھر یہی شوق و جذبہ لے کر اعلان کیا، انہوں نے پھر زدوکوب کیا، پھر سیدنا عباس رضی اللہ عنہ نے اپنے ساتھ ملا کر چھڑالیا۔(4) مسلم میں بطریق عبداللہ بن الصامت بحوالہ ابوذر ان کے اسلام لانے کا قصہ مشہور ہے۔ ابتداء میں ہے نبی صلی اللہ علیہ وسلم کی بعثت سے پہلے میں جس رخ اللہ مجھے متوجہ کر دیتا اس طرف نماز پڑھ لیتا، ہم اپنی والدہ کے ساتھ اپنے ماموں کے ہاں آئے ہوئے تھے، ان کے پاس ایک آدمی آیا کہ انہیں آپ کے گھر رہے گا۔ میرے بھائی کو پتہ چلا وہ کہنے لگا: اللہ کی قسم! میں تمہیں نہیں ٹھہراؤں گا چنانچہ ہم لوگ روانہ ہو گئے۔ میرا بھائی بھی چل پڑا وہ مکہ آیا۔ بعد میں اس نے مجھ سے کہا: میں مکہ گیا تھا وہاں میں نے ایک صاحب دیکھے ہیں جنہیں لوگ صابی (عربوں کے دین سے بے دین) کہتے ہیں۔ وہ تمہارے زیادہ مشابہ ہے۔ فرماتے ہیں: میں مکہ آیا، میں نے ایک شخص سے پوچھا: وہ صابی کہاں ہے؟ تو اس نے شور مچانا شروع کر دیا۔ صابی! صابی! لوگوں نے مجھے پر تیر برسائے گویا میں سرخ ہدف بن گیا ہوں۔ کعبہ کے پردوں میں چھپ کر جان بچائی، وہاں میں پندرہ رات دن رہا جہاں میرا کھانا پینا صرف آب زم زم تھا۔ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم اور ابوبکر رضی اللہ عنہ ہم سے ملے وہ دونوں حضرات مسجد حرام میں آئے۔ اللہ کی قسم! میں سب سے پہلا انسان ہوں جس نے انہیں اسلام والا سلام کیا۔ میں نے کہا: السلام علیک یا رسول اللہ! آپ صلی اللہ علیہ وسلم نے فرمایا: وعلیک السلام و رحمۃ اللہ! تم کون ہو؟ میں نے کہا: میں ایک غفاری ہوں۔ تو آپ کے ساتھی نے کہا: اللہ کے رسول! مجھے آج رات اس کی مہمان نوازی کی اجازت دیجئے تو وہ مجھے اپنے اس گھر میں لے گئے جو مکہ کی نچلی جانب تھا۔ مجھے کشمش کی مٹھی دی۔ فرماتے ہیں: میں اپنے بھائی کے پاس آیا اور اسے بتایا کہ میں تو مسلمان ہو چکا ہوں۔ وہ کہنے لگا: میں بھی تمہارے دین پر ہوں ہم اپنی والدہ کے پاس آئے۔ انہیں بتایا وہ بھی کہنے لگیں: میں تمہارے دین پر ہوں۔ فرماتے ہیں: پھر میں اپنی قوم کے پاس آیا انہیں اسلام کی دعوت دی تو چند لوگوں نے میرا اتباع کر لیا۔ ہم نے ان کے اسلام لانے کے بارے میں تیسری حدیث بھی روایت کی ہے جس کی طرف اشارہ ان کے بھائی انیس کے حالات میں ہو چکا ہے کہ یہ چار آدمیوں کے بعد اسلام لائے۔ پھر اپنی قوم کے علاقوں میں چلے گئے۔ جہاں نبی صلی اللہ علیہ وسلم کی مدینہ آمد تک مقیم رہے، اسی دوران معرکہ بدر و احد گزر گیا۔ انہیں اس کے بعد ہی ہجرت کا حکم ملا۔ وہ قد کے لمبے گندمی رنگ اور دبلے پتلے جسم کے مالک انسان تھے۔ ابوقلابہ بنی عامر کے ایک شخص سے نقل کرتے ہیں: میں منیٰ کی مسجد میں آیا وہاں ایک گندم گوں دبلے جسم والا آدمی دیکھا جس نے معمولی جوڑا پہن رکھا تھا میں نے ہیئت سے اندازہ لگا لیا کہ یہ ابوذر ہی ہیں۔ مسند یعقوب بن شیبہ میں بروایت سلمہ بن اکوع مروی ہے کہ ابوذر رضی اللہ عنہ دراز قد تھے۔ طبرانی نے حدیث ابودرداء سے نقل کیا ہے کہ جب ابوذر آتے تو ان سے ابتداء کرتے اور جب نہ ہوتے تو انہیں تلاش کرتے۔ امام احمد رحمہ اللہ نے بطریق عراک بن مالک روایت کی ہے کہ ابوذر رضی اللہ عنہ نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"قیامت کے دن اس شخص کی مجلس و نشست گاہ میرے زیادہ نزدیک ہوگی جسے میں جس حال پر چھوڑے جا رہا ہوں وہ اسی طرح میرے بعد رخصت ہوا ہوگا۔ اللہ کی قسم! میرے علاوہ تم میں سے ہر ایک کے ساتھ دنیا چمٹ گئی ہے۔\"(5) اس کے رجال تو ثقہ ہیں البتہ عراک بن مالک سے ابوذر رضی اللہ عنہ تک سلسلہ منقطع ہے۔ ابویعلیٰ نے دوسری سند سے اس کا مفہوم بحوالہ ابوذر رضی اللہ عنہ متصل نقل کیا ہے، لیکن اس کی سند ضعیف ہے، کتاب الزہد میں امام احمد رحمہ اللہ لکھتے ہیں: میں نے یزید بن ہارون کو محمد بن عمرو سے بحوالہ عراک بن مالک روایت کرتے سنا کہ ابوذر رضی اللہ عنہ نے فرمایا: \"قیامت کے روز میری نشست گاہ تم لوگوں سے زیادہ رسول اللہ صلی اللہ علیہ وسلم کے قریب ہوگی۔ کیونکہ میں نے آپ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: قیامت کے روز میرے نزدیک اس کی مجلس زیادہ قریب ہوگی جو دنیا سے اسی حالت سے رخصت ہوا جس پر میں اسے چھوڑ جا رہا ہوں۔ اللہ کی قسم! میرے علاوہ تم میں سے ہر ایک کے ساتھ کچھ دن لگ گئی ہے۔\" انہوں نے مسند میں ایسا ہی لکھا ہے۔ لیکن میرے خیال میں یہ سند منقطع ہے کیونکہ عراک کا سماع ابوذر سے نہیں ہے۔ ابوذر رضی اللہ عنہ سے اور ان سے انس، ابن عباس، ابوادریس خولانی، زید بن وہب، احنف بن قیس، جبیر بن نفیر، عبدالرحمن بن تمیم، سعید بن المسیب، خالد بن وہبان جو ابوذر کے خالہ زاد ہیں بقول بعض: ابن ابان ایک قول ہے وہ ان کے بھتیجے ہیں۔ ابوذر رضی اللہ عنہ کی اہلیہ، عبداللہ بن الصامت، ابواسماء الرحبی، خرشہ بن حر، زید بن ظبیان معرور بن سوید، یزید بن شریک، ابوعثمان نہدی، ابوالاسود دولی۔ ابومراوح غفاری، عبدالرحمن بن ابی لیلیٰ، عبدالرحمن بن حجیرہ، عبدالرحمن بن شماسہ اور عطاء بن یسار وغیرہ سیدنا روایت کرتے ہیں۔ ابواسحاق سبیعی بواسطہ ہانی بن ہانی بحوالہ سیدنا علی روایت کرتے ہیں۔ ابوذر علم کا بھرا تھیلا ہے جس پر گرہ لگا دی گئی ابوداؤد نے یہ روایت جید سند سے نقل کی ہے۔ ابوداؤد ہی اور امام احمد عبداللہ بن عمرو سے روایت کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"اس دھرتی پر اور اس آسمان کے نیچے ابوذر رضی اللہ عنہ سے زیادہ سچے لہجہ والا کوئی نہیں\"۔ اس باب میں سیدنا(6) علی، ابودرداء، ابوہریرہ، جابر، اور ابوذر رضی اللہ عنہم سے مروی روایات ہیں جن کے طرق ابن عساکر نے ان کے حالات میں ذکر کیے ہیں۔ آجری بحوالہ ابوداؤد نقل کرتے ہیں کہ ابوذر بدر میں شریک نہیں ہوئے۔ لیکن ابوعمر نے انہیں بدری صحابہ رضی اللہ عنہم میں شامل کیا ہے، وہ علم میں ابن مسعود رضی اللہ عنہ کے ہم پلہ تھے۔ سیرۃ نبویہ میں ابن اسحاق نے ضعیف سند سے نقل کیا ہے کہ ابن مسعود رضی اللہ عنہ فرماتے ہیں: (قحط کا زمانہ تھا) لوگ غزوہ تبوک میں بچھڑنے لگے، لوگ کہنے لگے: اللہ کے رسول! فلاں شخص پیچھے رہ گیا ہے، آپ نے فرمایا: اگر اس کے برعکس ہے تو اللہ تعالیٰ نے تم کو اس سے راحت بخشی ہے۔ ادھر ابوذر نے اپنے اونٹ پر کافی دیر لگا دی۔ جب وہ نہ اٹھا تو اپنا سامان اپنی پیٹھ پر رکھے چل نکلے، کسی مسلمان کی نظر پڑ گئی، کہنے لگا: یہ شخص تو راستہ پر آ رہا ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ کرے ابوذر ہی ہوں۔ جب لوگوں نے غور سے دیکھا تو کہنے لگے: اللہ کے رسول! یہ تو واقعی ابوذر ہیں۔ آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا: \"اللہ تعالیٰ ابوذر پر رحم فرمائے، اکیلا رہے گا، اکیلا فوت ہوگا اور اکیلا ہی اٹھایا جائے گا\"۔ پھر ان کی وفات کا ذکر کیا(7)۔۔۔۔ ربذہ میں ان کی وفات ہوئی، تاریخ وفات میں اختلاف ہے۔ ۳۱ھ بقول بعض اس کے بعد ہوئی اسی پر اکثریت کی رائے ہے۔ یہ بھی کہا جاتا ہے کہ ان کی نماز جنازہ عبداللہ بن مسعود رضی اللہ عنہ نے پڑھائی۔ جو ایک سند سے مروی ہے جس پر قدح کی بات نہیں۔ مدائنی فرماتے ہیں کہ عبداللہ بن مسعود رضی اللہ عنہ نے ربذہ میں ان کی نماز جنازہ پڑھائی پھر مدینہ آئے اور کچھ مدت بعد وفات پاگئے۔","",{"fn":"(1) اسد الغابہ (۵۸۶۲) استیعاب (۲۹۸۵) تجرید (۱۶۴/۲)\n(2) بخاری کتاب مناقب الانصار باب اسلام ابی ذر الغفاری (۳۸۶۱) مسلم کتاب فضائل الصحابہ باب فضائل ابی ذر الغفاری (۲۴۷۴)\n(3) مسند احمد (۱۶۵/۵)\n(4) ترمذی کتاب المناقب باب مناقب ابی ذر (۳۸۰۱، ۳۸۰۲)\n(5) ابن ماجہ المقدمۃ باب فی فضائل اصحاب رسول اللہ صلی اللہ علیہ وسلم (۱۵۶) مسند احمد (۲۲۳/۲)\n(6) المستدرک (۵۰/۳) دلائل النبوۃ (۲۲۲/۵) کنز العمال (۳۳۲۳۲) البدایۃ والنہایۃ (۸/۵)\n(7) تین لفظوں کی مقدار جگہ خالی ہے۔ تجرید (۱۶۰/۲)"}],[9829,"§۹۸۶۶ ۔ ابوذر (دوسرے)\nتجرید میں ذہبی نے ذکر کیا ہے کہ بقی بن مخلد کی مسند میں ان کی ایک حدیث ہے، ہوسکتا ہے یہ بعد والے ہوں۔"],[9830,"§۹۸۶۷ ۔ ابوذرہ بن معاذ(1)\nبن زرارہ انصاری ظفری۔ بقول بعض: ان کا نام حارث ہے۔ طبری فرماتے ہیں: یہ ان کے والد اور بھائی ابونملہ اُحد میں شریک ہوئے۔ میں کہتا ہوں: یہ ابونملہ کے سگے بھائی ہیں، ابواحمد الحاکم نے ان کا ذکر کیا ہے۔ ابونملہ کے حالات میں ان کا نسب بیان ہوگا۔","",{"fn":"(1) اسد الغابہ (۵۸۶۳) استیعاب (۲۹۸۶) تجرید (۱۶۴/۲)"}],[9831,"§۹۸۶۸ ۔ ابوذرہ الحرمازی\nدولابی نے ان کا ذکر کیا ہے ان کا نام نصلہ بن طریف بن نہصل ہے، ناموں میں ذکر ہو چکا ہے۔"],[9832,"§۹۸۶۹ ۔ ابوذؤیب الہذلی(1)\nمشہور شاعر۔ نام: خویلد بن خالد بن محرث ابن زبید ابن مخزوم بن صابلہ۔ بقول بعض: ان کا نام خالد بن خویلد ہے، باقی نسب اسی طرح ابن مسعود رضی اللہ عنہ کے ساتھ مخزوم میں یکجا ہو جاتا ہے۔ ابن مسعود رضی اللہ عنہ کے حالات میں ان کا بقیہ سلسلہ نسب ہے۔ محمد بن سلام جمحی نے \"طبقات الشعراء\" میں عمرو بن العلاء کی روایت نقل کی ہے کہ میں نے عمر بن معاذ سے پوچھا: سب سے بڑا شاعر کون ہے؟ تو انہوں نے ایک قصہ ذکر کیا۔ ابوذؤیب خویلد بن خالد مغرب کی جانب اپنے ایک گھر میں فوت ہوئے۔ عبداللہ بن زبیر رضی اللہ عنہ نے انہیں قبر میں اتارا۔ ابوعمر کی روایت ہے کہ کسی نے سیدنا حسان بن ثابت رضی اللہ عنہ سے پوچھا: سب سے بڑا شاعر کون ہے؟ آپ نے فرمایا: آدمی یا قبیلہ؟ لوگوں نے کہا: قبیلہ؟ فرمایا: ہذیل۔ ابن سلام فرماتے ہیں: میں کہتا ہوں: ہذیل میں سب سے بڑا شاعر ابوذؤیب ہے۔ عمر بن شبہ کا قول ہے: وہ اپنے اس قصیدہ کی وجہ سے ہذیل کے تمام شعراء پر فوقیت رکھتے ہیں: ☆ \"نفس کو اگر تم رغبت دلاؤ گے تو یہ رغبت کرنے والا ہے، اور جب اسے تھوڑے کا عادی بنا دو گے تو یہ قناعت و صبر کرنے لگے گا۔\" مرزبان لکھتے ہیں: وہ فصیح، زیادہ غریب (عام استعمال سے ہٹ کر کرنے والے) شعر گوئی پر قدرت رکھتے تھے، جاہلیت میں ایک عرصہ گزرا۔ اسلام کا دور پایا تو مسلمان ہو گئے۔ ان کے عمومی اشعار اسلام کے کہے ہوئے ہیں۔ ان کی اولاد میں سے پانچ افراد طاعون میں مبتلا ہوئے اور ایک ہی سال فوت ہو گئے۔ وہ سب کے سب مرد تھے جو جنگجو اور بہادر تھے۔ وہ اپنے ایک قصیدہ میں فرماتے ہیں، جس کا مطلع یہ ہے: ☆ \"کیا تو موت اور اس کی آفت سے غمزدہ ہے، سود دیکھا زمانہ کسی جزع فزع کرنے والے کا درد دور نہیں کرتا\"۔ اسی میں وہ کہتے ہیں: ☆ \"برا بھلا کہنے والوں کے لیے میرا صبر و استقلال نہیں یہ دکھانے کے لیے ہے کہ میں زمانہ کے حادثات سے نہیں ڈگمگاتا ہوں، اور جب موت اپنے پنجے گاڑ لیتی ہے تو دیکھے گا کہ کوئی تعویذ سود مند نہیں ہوتا، دل کو اگر تم رغبت دلاؤ گے تو وہ رغبت ہی کرنے والا ہے اور اگر اسے تھوڑی چیز کا عادی بنا دو گے تو یہ اس پر صبر کرنے لگے گا۔\" ابن مندہ نے بطریق المبلوی ابوذؤیب شاعر کی روایت نقل کی ہے کہ میں مدینہ آیا تو یہاں کے لوگ پھوٹ پھوٹ کر ایسے رو رہے تھے جیسے کوئی زخمی روتا ہے۔ جب سب نے احرام باندھا تو میں نے پوچھا: کیا ہوا ہے؟ انہوں نے بتایا: اللہ کے رسول صلی اللہ علیہ وسلم فوت ہو گئے ہیں۔ ابن عبدالبر کا بیان ہے کہ ابن اسحاق یہ روایت ابوالاکام سے نقل کی ہے۔ جس کی ابتداء میں یہ الفاظ ہیں: ہمیں معلوم ہوا کہ رسول اللہ صلی اللہ علیہ وسلم کی یہ بیمار ہیں۔ مجھے لگا جیسے کوئی جنگ چھڑی ہے میں نے یہ رات سب سے زیادہ لمبی پائی جس کی تاریکی چھٹتی ہی نہ تھی کہ روشنی نمودار ہو یہاں تک کہ جب سحری کا وقت ہوا تو میری آنکھ لگی میں نے سنا کوئی کہہ رہا ہے: ☆ \"نخلستان اور معقل کے ٹیلوں کے درمیان اسلام پر ایک بہت بڑی مصیبت ٹوٹ پڑی۔ نبی محمد (صلی اللہ علیہ وسلم)(2) وفات پاچکے ہیں۔ اور ہماری آنکھیں ان پر مسلسل آنسو بہارہی ہیں\"۔ فرماتے ہیں: میں گھبرا کر جاگا، آسمان کی طرف دیکھا تو مجھے سعد ذابح ستارہ نظر آیا، جس کی تاویل میں نے یہ سمجھی کہ عرب میں ایک مصیبت آتی ہے، پھر مجھے معلوم ہوا کہ نبی صلی اللہ علیہ وسلم انتقال کر گئے ہیں۔ میں اپنی اونٹنی پر سوار ہو کر چل پڑا۔ پھر اپنا قصہ ذکر کیا۔ اسی میں ہے: انہوں نے نبی صلی اللہ علیہ وسلم کی تدفین دیکھی ابھی تک آپ صلی اللہ علیہ وسلم کو غسل نہیں دیا گیا، اس وقت آپ صلی اللہ علیہ وسلم کے پاس صرف آپ کے اہل خانہ تھے، پھر سقیفہ بنی ساعدہ میں اپنی موجودگی اور ابوبکر رضی اللہ عنہ کا خطبہ سننے کا ذکر کیا اور اپنا وہ قصیدہ بیان کیا جس میں نبی صلی اللہ علیہ وسلم کا مرثیہ کہا تھا: ☆ \"ان کی وفات کی وجہ سے ستارے بے نور اور چودھویں کا چاند ماند پڑ گیا اور بطحاء کی وادی کے ٹیلے ریزہ ریزہ ہو گئے۔\" فرماتے ہیں: پھر ابوذؤیب اپنے دیہات واپس ہو گئے، جہاں اپنی وفات تک مقیم رہے۔ خلافت عثمانی میں مکہ کے راستہ میں فوت ہوئے۔ ان کے علاوہ کا قول ہے: زمانہ عثمانی میں افریقا کے راستہ میں ایک مقام پر فوت ہوئے۔ وہ غزوہ افریقا میں شریک تھے اور ابن زبیر رضی اللہ عنہ کے ساتھ تھے۔ بقول بعض: وہ رومی زمین میں جنگ کے دوران فوت ہوئے۔ مرزبانی کا قول ہے: خلافت عثمانی میں افریقا میں فوت ہوئے۔ ایک قول ہے: وہ مصر کی راہ میں فوت ہوئے۔ ابن زبیر رضی اللہ عنہ نے ان کی تجہیز و تکفین کی۔ ابن البرقی کا قول ہے: معروف بن خربوذ بحوالہ ابوالطفیل روایت کرتے ہیں کہ صحابی رسول عمرو بن احمق کا گمان ہے کہ کسی کتاب میں ہے کہ سب سے بڑی زمین ام صہبار بنی سلیم کا حرہ ہے اور سب سے کمینہ قبیلہ محارب خصفہ ہے اور سب سے بڑا شاعر ابوذؤیب ہے، فرماتے ہیں: ابوالحارث عبداللہ بن عبدالرحمن بن سفیان الہدلی بحوالہ اپنے والد روایت کرتے ہیں کہ ابوذؤیب سیدنا عمر رضی اللہ عنہ کی خلافت میں ان کے پاس آئے۔ کہنے لگے: امیر المومنین! سب سے افضل کونسا عمل ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: اللہ پر ایمان رکھنا۔ کہا: میں نے تو یہ کام کر لیا ہے، اس کے بعد کونسا عمل ہے؟ فرمایا: اللہ کی راہ میں جہاد۔ کہا: اچھا یہ تو مجھے پر لازم ہے۔ مجھے نہ جنت کی اُمید ہے اور نہ جہنم کا خدشہ ہے۔ پھر وہیں سے وہ، ان کا بیٹا اور بھتیجا ابوعبید چل نکلے یہاں تک کہ وہ روم کی زمین میں فوت ہو گئے۔ لشکر عافہ کی زمین میں کشاں کشاں جا رہا تھا اس وقت انہوں نے اپنے بیٹے اور بھتیجے سے کہا: ایسا تو نہیں ہوسکتا کہ تم دونوں میرے پاس رہو اس لیے قرعہ اندازی کر لو، قرعہ ابوعبید کے حق میں نکلا تو وہ تدفین تک ان کے پاس رہے۔","",{"fn":"(1) اسد الغابہ (۵۸۶۵) تجرید (۱۶۴/۲)\n(2) پہلا اور دوسرا مصرعہ اسد الغابہ (۴۳۸/۴) میں ہے۔"}],[9833,"§۹۸۷۰ ۔ ابوراشد الازدی(1)\nعبدالرحمن بن عبید ہیں، ناموں میں ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۶۶) استیعاب (۲۹۸۷) تجرید (۱۶۴/۲)"}],[9834,"§۹۸۷۱ ۔ ابوراشد (دوسرے)\nابوملیکہ میں تذکرہ ہونا ہے۔"],[9835,"§۹۸۷۲ ۔ ابورافع القبطی(1) (مولیٰ رسول اللہ صلی اللہ علیہ وسلم)\nان کا نام: ابراہیم، اسلم، سنان، یسار، صالح، عبدالرحمن، قزمان، یزید، ثابت اور ہرمز بتایا جاتا ہے۔ ابن عبدالبر فرماتے ہیں: ان کا نام اسلم زیادہ مشہور ہے۔ یحییٰ بن معین کا قول ہے: ان کا نام ابراہیم ہے۔ یہی قول مصعب الزبیری کا ہے۔ ان کا لقب بُرَیہ ہے جو ابراہیم کی تصغیر ہے۔ ابن شاہین نے بحوالہ ابوداؤد نقل کیا ہے کہ ان کا نام قزمان تھا، بعد میں ابراہیم رکھا گیا۔ ایک قول ہے: اسلم ہے۔ ابن حبان نے یہ اضافہ نقل کیا ہے کہ یسار اور ہرمز بھی بتایا جاتا ہے۔ ایک قول ہے: یہ عباس بن عبدالمطلب کے غلام تھے، انہوں نے نبی صلی اللہ علیہ وسلم کو ہبہ کر دیا، آپ نے انہیں اس وقت آزاد کر دیا تھا جب انہوں نے آپ کو عباس بن عبدالمطلب کے اسلام لانے کی خوشخبری سنائی۔ محفوظ تو یہ ہے کہ وہ اسلم ہیں جب انہوں نے عباس رضی اللہ عنہ کو یہ خوشخبری دی کہ نبی صلی اللہ علیہ وسلم کو خیبر والوں پر فتح ہوئی ہے۔ جس کا ایک واقعہ ہے وہ بدر سے پہلے اسلام لے آئے تھے، لیکن اس میں شرکت نہ کر سکے۔ البتہ احد اور بعد کے معرکوں میں شریک رہے۔ نبی صلی اللہ علیہ وسلم اور عبداللہ بن مسعود رضی اللہ عنہ سے روایت کرتے ہیں ان سے ان کی اولاد میں سے رافع، حسن، عبیداللہ اور مغیرہ روایت کرتے ہیں اور پوتوں میں سے حسن، صالح، عبیداللہ جو علی بن ابی رافع کی اولاد ہے۔ فضل بن عبیداللہ بن ابی رافع، ابوسعید المقبری، سلیمان بن یسار، عطاء بن یسار، عمرو بن شرید، ابوغطفان بن ظریف، سعید بن ابی سعید مولیٰ حزم، حصین، داؤد کے والد اور شرحبیل بن سعد وغیرہ۔ امام واقدی رحمہ اللہ کا قول ہے کہ ابورافع مدینہ میں سیدنا عثمان رضی اللہ عنہ سے کچھ مدت پہلے یا بعد میں فوت ہوئے۔ ابن حبان کا قول ہے: خلافت علی بن ابی طالب میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۵۸۶۷) تجرید (۱۶۴/۲)"}],[9836,"§۹۸۷۳ ۔ ابورافع انصاری\nابوداؤد میں مخابرہ کی حدیث میں ان کا ذکر آتا ہے، جو بطریق مجاہد بواسطہ ابن رافع بن خدیج بحوالہ ان کے والد مروی ہے۔ فرمایا: ہمارے پاس ابورافع آئے... پھر وہ حدیث ذکر کی۔ احتمال ہے کہ یہ بعد والے ہوں۔"],[9837,"§۹۸۷۴ ۔ ابورافع ظہیر بن رافع بن خدیج\nناموں میں ذکر ہو چکا ہے۔"],[9838,"§۹۸۷۵ ۔ ابورافع الحکم بن عمرو الغفاری\nناموں میں ذکر ہو چکا ہے۔"],[9839,"§۹۸۷۶ ۔ ابورافع الغفاری\nبقی بن مخلد نے ان کی ایک حدیث نقل کی ہے، احتمال ہے کہ پہلے والے ہوں۔"],[9840,"§۹۸۷۷ ۔ ابورافع\nمولا نبی صلی اللہ علیہ وسلم دوسرے ہیں۔ قبطی نہیں۔ مصعب الزبیری نے ان کا ذکر کیا ہے کہ ابورافع، ابواحیحہ سعید بن عاص بن امیہ کے غلام تھے، تو ان کی اولاد میں سے سوائے خالد بن سعید کے سب نے اپنا حصہ آزاد کر دیا۔ انہوں نے اپنا حصہ نبی صلی اللہ علیہ وسلم کو سونپ دیا، آپ نے انہیں آزاد کر دیا۔ وہ کہا کرتے تھے: میں رسول اللہ صلی اللہ علیہ وسلم کا مولا (آزاد کردہ غلام) ہوں۔ امیر معاویہ رضی اللہ عنہ کے دور حکومت میں جب عمرو بن سعید بن عاص بن امیہ مدینہ کا حاکم بنا، اس نے ابورافع رضی اللہ عنہ کے بیٹے کو بلایا پوچھا تم کس کے مولا ہو؟ کہا: رسول اللہ صلی اللہ علیہ وسلم کا، تو عمرو بن سعید نے اسے سو کوڑے مارے اور پھر پوچھا: تم کس کے مولا ہو؟ اس نے کہا: رسول اللہ صلی اللہ علیہ وسلم کا۔ پھر سو کوڑے لگائے۔ یہاں تک کہ پانچ سو کوڑے لگائے۔ مبرد نے \"الکامل\" میں ذکر کیا ہے، اس کا تقاضا ہے کہ یہ وہ ابورافع ہیں جن کا ذکر ہو چکا ہے۔ ابن عبدالبر نے اسی کو اختیار کیا ہے اور مذکورہ قصہ ابورافع قبطی کے حالات میں لکھا ہے۔ جو عبداللہ کاتب علی رضی اللہ عنہ کے والد ہیں۔ جبکہ یہ بالکل غلط ہے، اس واسطے کہ وہ ابورافع جو عبیداللہ کے والد ہیں وہ تو عباس بن عبدالمطلب رضی اللہ عنہ کے غلام تھے، جنہیں آپ صلی اللہ علیہ وسلم نے آزاد کر دیا تھا۔ ابوعمر فرماتے ہیں: نقلا یہ قصہ ثابت نہیں کیونکہ اس میں اضطراب بہت زیادہ ہے۔ عمرو بن دینار، جریر بن ابی حازم اور ایوب کی روایت ہے کہ جس نے ابورافع میں سے اپنا حصہ روک لیا تھا وہ صرف خالد ہی ہیں۔ ایک اور روایت میں ہے کہ ماسوائے ایک حصہ کے وہ ابواحیجہ کے تھے، تو ان کی اولاد نے اپنا حصہ آزاد کر دیا۔ آپ صلی اللہ علیہ وسلم نے وہ ایک حصہ خرید کر انہیں آزاد کر دیا۔ میں کہتا ہوں: ابوسعید بن الاعرابی نے یہ قصہ اپنی معجم میں بطریق جریر بن حازم بواسطہ حماد بن موسیٰ جن کا تعلق مدینہ سے ہے نقل کیا ہے کہ عثمان بن الیسع بن ابی رافع نے ان سے بیان کیا کہ میرے دادا ابواحیجہ نے میراث چھوڑی بدر کے روز اپنی اولاد کے ساتھ روانہ ہوئے۔ ان میں سے تین سعید، عبیداللہ اور عاص نے تو اپنا حصہ آزاد کر دیا یہ تینوں بدر کے روز کفر پر مرے۔ تو سعید کی اولاد میں سے سوائے خالد بن سعید کے سب نے انہیں آزاد کر دیا۔ کیونکہ خالد کو ابواحیجہ کی لونڈی کی وجہ سے ابورافع پر غصہ تھا وہ اس سے شادی کرنا چاہتے تھے۔ خالد نے انہیں روکا لیکن انہوں نے بات نہ مانی، اور ان پر حملہ کر دیا۔ جب ابورافع مسلمان ہو گئے، ہجرت کرلی تو رسول اللہ صلی اللہ علیہ وسلم سے خالد کے بارے میں بات کی، انہوں نے آزاد کرنے، ہبہ کرنے یا فروخت کرنے سے انکار کیا۔ بعد میں انہیں ندامت ہوئی۔ اور نبی صلی اللہ علیہ وسلم کو ہبہ کر دیا۔ آپ صلی اللہ علیہ وسلم نے اپنا حصہ آزاد کر دیا، ابورافع کہا کرتے تھے، میں رسول اللہ صلی اللہ علیہ وسلم کا مولا ہوں۔ جب عمرو بن سعید بن عاص مدینہ کا والی بنا تو بہی بن ابی رافع کو بلا بھیجا، پوچھا تم کس کے مولا ہو؟ اس نے کہا: رسول اللہ صلی اللہ علیہ وسلم کا تو اس نے سو کوڑے لگائے، پھر پوچھا: تم کس کے مولا ہو؟ تو یہی جواب دیا۔ یہاں تک کہ پانچ سو وڑے لگائے جب جان کا خوف ہوا تو کہہ دیا، میں تمہارا مولا ہوں۔ جب عبدالملک بن مروان نے عمرو بن سعید کو قتل کر دیا تو بہی نے اس کی مدح کی اور عمرو بن سعید کی ہجو کی۔ اس سے معلوم ہوا اس واقعہ والے ابورافع عبداللہ کے والد کے علاوہ کوئی شخص ہیں اس لیے کہ ان کی اولاد میں بھی نامی کوئی نہیں۔"],[9841,"§۹۸۷۸ ۔ ابورائطہ(1)\nابوریطہ میں تذکرہ ہوتا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۶۸) تجرید (۱۶۵/۲)"}],[9842,"§۹۸۷۹ ۔ ابوالرباب\nکتاب النساء الرباب میں ذکر ہوگا۔"],[9843,"§۹۸۸۰ ۔ ابوالربذاء\nبقول بعض میم اور دال سے تذکرہ ہوتا ہے۔"],[9844,"§۹۸۸۱ ۔ ابوربعی\nعمرو بن الامتم تمیمی، تذکرہ ہو چکا ہے۔"],[9845,"§۹۸۸۲ ۔ ابوالربیع عبداللہ بن ثابت انصاری\nحدیث جابر بن عتیک میں ان کا ذکر ہو چکا ہے۔"],[9846,"§۹۸۸۳ ۔ ابوربیعہ(1) (بے نسبت)\nابوموسیٰ کا قول ہے: ابوزکریا بن مندہ نے اپنے دادا کی کتاب کے استدراک میں ان کا ذکر کیا ہے اور ان کی کوئی حدیث نقل نہیں کی۔","",{"fn":"(1) اسد الغابہ (۵۸۷۱) تجرید (۱۶۵/۲)"}],[9847,"§۹۸۸۴ ۔ ابورحیمہ(1) (بے نسبت)\nحاء سے یا خاء سے۔ ابونعیم نے ان کا ذکر کیا اور بطریق روح بن جناح، عطاء بن نافع بواسطہ حسن بحوالہ ابورحیمہ روایت نقل کی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سینگی لگائی تو آپ نے مجھے ایک درہم دیا۔(2) اس کی سند میں ضعف ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۷۳) تجرید (۱۶۵/۲)\n(2) جامع المسانید والسنن (۴۰/۱۱۴) اسد الغابہ (۴۴۲/۴)"}],[9848,"§۹۸۸۵ ۔ ابورداد اللیثی(1)\nبقول ابواحمد الحاکم اور ابن حبان، انہیں شرف صحابیت حاصل ہے ان کی حدیث زہری نے بواسطہ ابوسلمہ بن عبدالرحمن بحوالہ ان کے نبی صلی اللہ علیہ وسلم سے نقل کی ہے۔ اسی سند کی حدیث ابوداؤد(2) نے نقل کی ہے جس کے الفاظ یہ ہیں کہ رداد نے بحوالہ عبدالرحمن بن عوف انہیں بتایا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: اللہ تعالیٰ نے فرمایا: \"میں رحمن ہوں میں نے رحم (رشتہ داری) کو پیدا کیا۔\" ایسا ہی ابن حبان نے ثقات التابعین میں \"رداد اللیثی\" لکھا ہے۔ پھر بطریق معمر بواسطہ زہری، ابوسلمہ سے، رداد سے بحوالہ عبدالرحمن بن عوف بیان کی، فرماتے ہیں: میرا گمان نہیں کہ معمر نے اسے یاد رکھا ہو۔ میں کہتا ہوں: ابن عیینہ نے زہری سے ترمذی میں ان کی متابعت کی ہے۔ امام بخاری رحمہ اللہ فرماتے ہیں: حدیث معمر میں غلطی ہے۔ امام بخاری رحمہ اللہ نے \"الادب المفرد\" میں بطریق ابن ابی عتیق، زہری، ابوسلمہ محمد بن عبدالرحمن، بواسطہ ابورداد اللیثی بحوالہ نبی صلی اللہ علیہ وسلم روایت کی ہے۔ شعیب نے بحوالہ زہری اس کی متابعت کی ہے۔ ابوحاتم رازی لکھتے ہیں: اس سلسلہ میں ابوسلمہ بن عبدالرحمن بن عبدالرحمن کی روایت مشہور ہے۔ اس میں ابورداد کا قصہ ہے وہ یہ کہ ابورداد بیمار ہوئے تو عبدالرحمن بن عوف ان کی عیادت کرنے گئے، آپ صلی اللہ علیہ وسلم نے فرمایا: لوگوں میں سے بہترین اور صلہ رحمی کرنے والا ابومحمد ہے۔ تو انہوں نے کہا: عبدالرحمن... پھر حدیث ذکر کی۔","",{"fn":"(1) اسد الغابہ (۵۸۷۴) تجرید (۱۶۵/۲)\n(2) ابوداؤد کتاب الزکوٰۃ باب صلۃ الرحم (۱۶۹۵، ۱۶۹۶)"}],[9849,"§۹۸۸۶ ۔ ابوالردین(1) (بے نسبت)\nبغوی نے ان کا ذکر کیا ہے لیکن ان کی کوئی حدیث ذکر نہیں کی۔ ابن مندہ کا قول ہے۔ صحابہ رضی اللہ عنہم میں ان کا ذکر آتا ہے۔ لیکن ان کا صحابی ہونا ثابت نہیں۔ ان کی حدیث حارث بن ابی اسامہ اور طبرانی نے مسند شامیین میں بطریق عبدالحمید بن عبدالرحمن بحوالہ ابوالردین نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو قوم بھی اکٹھے ہو کر اللہ تعالیٰ کی کتاب پڑھتی اور ایک دوسرے کو سکھاتی ہے تو وہ اللہ کے مہمان ہیں اور فراغت تک فرشتے انہیں گھیر لیتے ہیں۔\"(2)","",{"fn":"(1) اسد الغابہ (۵۸۷۵) تجرید (۱۶۵/۲)\n(2) المعجم الکبیر (۸۴۴/۲۲) مجمع الزوائد (۱۲۲/۱) جامع المسانید (۴۲/۱۴) اسد الغابہ (۴۴۳/۴)"}],[9850,"§۹۸۸۷ ۔ ابورزین(1) (بے نسبت)\nبقول ابوعمر: ان سے صرف ان کا بیٹا عبداللہ روایت کرتا ہے یہ دونوں نامعلوم شخص ہیں۔ شکار کے چھپ جانے کے بارے میں ان کی حدیث آتی ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۷۷) تجرید (۱۶۵/۲)"}],[9851,"§۹۸۸۸ ۔ ابورزین(2) (دوسرے ہیں)(1)\nبقول بعض: اہل صفہ میں شامل ہیں، خلعیات میں ہم نے بطریق عمرو بن بکر سکسکی، محمد بن زید، ابوسلمہ بن عبدالرحمن، وہ بحوالہ اپنے والد روایت کی ہے کہ نبی صلی اللہ علیہ وسلم نے اہل صفہ میں سے ایک شخص سے کہا: جن کی کنیت ابورزین تھی۔ ابورزین! جب تم خلوت میں ہوا کرو تو اللہ تعالیٰ کے ذکر میں اپنی زبان کو حرکت دینا کیونکہ جب تک تم اپنے رب کا ذکر کرتے رہے تو نماز میں شامل لکھے جاؤ گے۔ ابورزین! جب لوگ جہاد کے لیے جانے لگیں اور تم چاہو کہ تمہیں بھی انہی جیسا اجر ملے تو مسجد سے جدا نہ ہونا۔ وہاں بغیر اجرت اذان دیتے رہنا۔ اس کی سند ضعیف ہے۔ ان کا ذکر ایک اور حدیث میں بھی آتا ہے جو عقیلی نے \"الضعفاء\" میں محمد بن اشعث(3) جو ایک مجہول راوی ہے کے حالات میں نقل کی ہے جو اس کے طریق سے بواسطہ ابوسلمہ بحوالہ ابوہریرہ رضی اللہ عنہ مروی ہے کہ ابورزین نے عرض کی: اللہ کے رسول! میرے راستہ میں قبرستان آتا ہے تو کیا کوئی ایسی بات ہے جو میں وہاں سے گزرتے ہوئے ان سے کہوں؟ آپ نے فرمایا: یوں کہو! السلام علیکم یا اہل القبور من المسلمین انتم لنا سلف و نحن لکم تبع و انا ان شاء اللہ بکم لاحقون۔ تو ابورزین نے کہا: اللہ کے رسول! کیا وہ سنتے ہیں؟ آپ نے فرمایا: \"سنتے تو ہیں لیکن جواب نہیں دے سکتے۔ ابورزین! کیا تم خوش نہیں کہ ان کی تعداد میں فرشتے تمہیں جواب دیں؟\" عقیلی فرماتے ہیں: یہ روایت اسی سند سے مشہور ہے جو کتابوں میں (اور حفاظ کے سینوں میں) محفوظ نہیں۔ مردوں کو سلام کی اصل روایت اس کے علاوہ صحیح سند سے نقل کی جاتی ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۷۹) تجرید (۱۶۵/۲)\n(2) حلیۃ الاولیاء (۳۶۶/۱) اسد الغابہ (۴۴۴/۴)\n(3) الضعفاء (۱۹/۴)"}],[9852,"§۹۸۸۹ ۔ ابورزین العقیلی(1)\nلقیط بن عامر ناموں میں ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۷۸) استیعاب (۲۹۹۳) تجرید (۱۶۵/۲)"}],[9853,"§۹۸۹۰ ۔ ابورعلہ القشیری\nخواتین کے حصہ میں ام رعلہ میں تذکرہ ہوگا۔"],[9854,"§۹۸۹۱ ۔ ابورفاعہ العدوی(1)\nتمیم بن اسد۔ امام بخاری رحمہ اللہ نے یہی نام لیا ہے کسی نے ابن اسید کسی نے اسید (تصغیر) کسی نے کہا: ان کا نام عبداللہ بن حارث ہے، یہی خلیفہ وغیرہ کا قول ہے۔ یہ نبی صلی اللہ علیہ وسلم سے اور ان سے حمید بن ہلال، وصلہ بن اشیم جو دونوں عدوی اور بصری ہیں روایت کرتے ہیں۔ صحیح مسلم میں حدیث حمید سے ان کی حدیث آتی ہے، فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا پھر قصہ ذکر کیا کہ آپ ان کی خاطر منبر سے اترے اور گفتگو کی، آپ کی عادت تھی جب کوئی مسافر شخص دین کی کوئی بات پوچھتا تو آپ منبر سے اتر آتے، چنانچہ آپ لوہے کے پایوں والی ایک کرسی پر تشریف فرما ہوئے۔ اور مجھے وہ چیزیں سکھانے لگے جو اللہ تعالیٰ نے آپ کو سکھائی تھیں۔ (حدیث)(2) الحاکم کی مصعب زبیری کے طریق سے روایت ہے کہ ابورفاعہ عدوی صحابی ہیں ان کا نام عبداللہ بن حارث بن اسید بن عدی بن مالک بن تمیم بن الدول بن حسل بن عدی بن عبد مناۃ ہے عبدالرحمن بن سمرہ کی معیت میں بجستان کی جنگ میں شرکت کی رات کی آخری گھڑی کھڑے ہوئے گرنے کی وجہ سے فوت ہو گئے۔ ابن عبدالبر نے لکھا ہے کہ بصرہ کے فضلاء (فضیلت والے) صحابہ رضی اللہ عنہم میں سے تھے۔ کابل میں ۴۴ھ میں شہید ہوئے۔ خلیفہ کا قول ہے کہ ابن عامر نے ۴۴ھ میں کابل فتح کیا جس میں ابوقتادہ عدوی بقول بعض: اس میں شہید ہونے والے ابورفاعہ عدوی تھے۔ عدی بن غنام کا قول ہے: ابورفاعہ صحابی رسول صلی اللہ علیہ وسلم اور اسود بن کلثوم کی قبر بیہق میں ہے۔ یہی قول مسلم کا ہے کہ ابورفاعہ کی قبر بیہق میں ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۸۰) تجرید (۱۶۵/۲)\n(2) مسلم کتاب الجمعہ باب حدیث التعلیم فی الخطبۃ (۲۰۲۲) نسائی کتاب الزینۃ باب الجلوس علی الکراسی (۵۳۹۲) مسند احمد (۴۴/۱۴)"}],[9855,"§۹۸۹۲ ۔ ابورقاد\nنبی صلی اللہ علیہ وسلم نے اس سے زید بن ثابت رضی اللہ عنہ کو مخاطب کیا تھا۔ زید بن اشتہ کے حالات میں بطریق واقدی یہ بات بیان ہو چکی ہے۔"],[9856,"§۹۸۹۳ ۔ ابورقیہ (تصغیر ہے)\nتمیم بن اوس داری، ناموں میں ذکر ہوا ہے۔"],[9857,"§۹۸۹۴ ۔ ابورمثہ البلوی(1)\nبقول ترمذی: انہیں شرف صحابیت حاصل ہے۔ مصر کے رہائشی تھے اور افریقا میں فوت ہوئے۔ انہوں نے وصیت کی تھی کہ میری قبر زمین سے برابر کر دی جائے۔ اہل مصر سے ان کی حدیث منقول ہے۔ اسی طرح ابوعمر نے ان کا تذکرہ کیا ہے، ان میں اور بعد والے ابورمثہ تمیمی میں فرق کیا ہے، جبکہ المری نے ان سے اختلاف کرتے ہوئے لکھا ہے کہ بعد والے تیمی، بقول بعض بلوی ہیں۔","",{"fn":"(1) اسد الغابہ (۵۸۸۱) تجرید (۱۶۶/۲)"}],[9858,"§۹۸۹۵ ۔ ابورمثہ التیمی(1)\nاز تیم الرباب بقول بعض: التیمی، کا نام رفاعہ بن یثربی ہے۔ ایک قول ہے: یثربی بن عوف کسی نے یثربی بن رفاعہ کہا ہے اسی پر طبرانی کا اعتماد ہے ایک قول ہے: ان کا نام حیان ہے جس پر کئی لوگوں کا اعتماد ہے۔ بقول بعض: حبیب بن حیان، بقول بعض: حسحاس۔ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں ان سے ایاد بن لقیط، ثابت بن منقذ روایت لیتے ہیں۔ تین اصحاب السنن نے ان کی روایت لی ہے۔ ابن خزیمہ، ابن حبان اور الحاکم نے ان کی حدیث کو صحیح لکھا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۸۲) استیعاب (۲۹۹۶) تجرید (۱۶۶/۲)"}],[9859,"§۹۸۹۶ ۔ ابورمداء البلوی(1)\nناموں میں تذکرہ ہو چکا ہے کہ ان کا نام یاسر ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۸۳) استیعاب (۲۹۹۷) تجرید (۱۶۶/۲)"}],[9860,"§۹۸۹۷ ۔ ابورہم الغفاری(1)\nنام: کلثوم بن حصین بن خالد بن المعیر بن زید بن عمیس بن احمس بن غفار ہے، بقول بعض: ابن حصین بن عبید بن خلف بن حماس بن غفار غفاری۔ کنیت اور ناموں دونوں میں شہرت رکھتے ہیں۔ بیعت رضوان(2) میں شریک تھے۔ فتح مکہ کے موقعہ پر نبی علیہ السلام نے انہیں مدینہ میں اپنا نائب مقرر کیا تھا۔ یہی بات ابن اسحاق سے مغازی میں مروی ہے۔ انہوں نے غزوہ تبوک کی طویل حدیث نبی صلی اللہ علیہ وسلم سے روایت کی ہے۔ اسے بعض نے مختصراً نقل کیا ہے۔ ان سے ان کا بھتیجا اور مولا، ابوجازم تمار روایت کرتے ہیں۔ امام احمد اور بغوی وغیرہ نے بطریق معمر بحوالہ زہری روایت کی ہے کہ مجھے ابورہم کے بھتیجے نے بتایا کہ انہوں نے ابورہم کو فرماتے سنا: میں نے غزوہ تبوک میں نبی صلی اللہ علیہ وسلم کے ساتھ شرکت کی۔ پھر وہ(3) حدیث نقل کی۔ ابن سعد(4) لکھتے ہیں: نبی صلی اللہ علیہ وسلم نے انہیں اپنی قوم کو غزوہ تبوک کی تیاری کے لیے بھیجا۔(5) امام بخاری رحمہ اللہ کی الادب المفرد، صحیح ابن حبان، معجم طبرانی میں ان کی حدیث ہے۔ ابوعروبہ کا بیان ہے کہ اُحد میں ان کے سینہ کی ہڈی اور گردن میں تیر پیوست ہوا تھا۔ نبی صلی اللہ علیہ وسلم نے اس میں اپنا لعاب لگایا تو تندرست ہو گئے۔","",{"fn":"(1) اسد الغابہ (۵۸۹۳) استیعاب (۳۰۰۱) تجرید (۱۶۶/۲)\n(2) جامع المسانید (۴۴۸/۴)\n(3) مسند احمد (۳۴۹/۴)\n(4) الطبقات (۱۷۹/۴)\n(5) الطبقات (۳۴۹/۴) مجمع الزوائد (۳۴۲/۵)"}],[9861,"§۹۸۹۸ ۔ ابورہم بن قیس اشعری(1)\nبرادر ابوموسیٰ اشعری رضی اللہ عنہ ان کے بھائی ابوبردہ بن قیس کے سوانح میں ان کی حدیث گزر چکی ہے جو طاعون کے متعلق ہے اس کی سند صحیح ہے۔ میں نے تاریخ مظفری میں ابن قتیبہ کے حوالہ سے دیکھا ہے کہ ابورہم فتنوں میں جلدی کرتے تھے اور ان کے بھائی ابوموسیٰ ان سے روکتے تھے پھر ایک واقعہ ذکر کیا۔ ابن قتیبہ فرماتے ہیں: بقول بعض: یہ ابورہم مشہور نہیں۔ میں کہتا ہوں: شاید یہ وہی ہیں پھر مجھے مسند احمد میں بطریق قتادہ ابوموسیٰ کی سند کے دوران حسن کی روایت مل گئی کہ ابوموسیٰ رضی اللہ عنہ کا ابورہم نامی ایک بھائی تھے جو فتنوں میں جلدی کرتے تھے۔ ابوموسیٰ نے ان سے ایک حدیث بیان کی۔ جب دو مسلمان اپنی تلواریں لیے روبرو ہو جاتے ہیں اور ان سے ایک دوسرے کو قتل کر دے تو دونوں جہنم میں جائیں گے۔(2)","",{"fn":"(1) اسد الغابہ (۵۸۹۳) استیعاب (۲۹۹۸) تجرید (۱۶۷/۲)\n(2) نسائی کتاب التحریم باب تحریم القتل (۴۲۲۹) (۴۱۳۰) ابن ماجہ کتاب الفتن باب اذا التقی المسلمان بسیفیھما (۳۹۶۴) مسند احمد (۴۱۲/۴)"}],[9862,"§۹۸۹۹ ۔ ابورہم (دوسرے)(1)\nنام: مجدی بن قیس، تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۹۴) تجرید (۱۶۷/۲)"}],[9863,"§۹۹۰۰ ۔ ابورہم الارحبی(1)\nناموں میں مطعم میں ان کا تذکرہ ہو چکا ہے، بغوی نے ان کا ذکر کیا ہے اور ابوعبید کے حوالہ سے نقل کیا ہے: ابورہم شاعر نے نبی صلی اللہ علیہ وسلم کی طرف ایک سو پانچ سال کی عمر میں ہجرت کی ان کا تعلق بنی اُڑکب سے تھا، جو ہمدان کے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۸۹۰) تجرید (۱۶۷/۲)"}],[9864,"§۹۹۰۱ ۔ ابورہم(1)(2)\nبقول بعض: اسمعی۔ میرے نزدیک یہ احزاب کے علاوہ ہیں۔ ابن سعد(3) کا قول ہے: کوفہ کے رہنے والے تھے۔ شام جا بسے، صحابی ہیں۔ نہ ان کا نسب لکھا ہے اور نہ نام۔ ابن ابی خیثمہ کی روایت ہے کہ ابورہم صحابی رسول صلی اللہ علیہ وسلم سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اپنے امام (خلیفہ) کی بات نہ مانی اس کا اجر ضائع ہو گیا۔\" اسحاق بن راہویہ نے یہ روایت اپنی مسند میں بحوالہ بقیہ اور حسن بن سفیان نے بحوالہ اسحاق جبکہ دولابی نے بطریق ثور بن یزید یزید بن مرشد سے بحوالہ ابورہم نقل کی ہے، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جب تم میں سے کوئی سفر سے واپس آئے تو اپنے گھر والوں کے لیے ہدیہ لے کر جائے۔ اگر اور کچھ نہ ملے تو اپنے تھیلے میں پتھر ہی ڈال لے۔ یا ایندھن کا گٹھا لے جائے اس سے انہیں خوشی ہوگی۔\" ان تینوں احادیث سے ابورہم کے صحابی ہونے کا پتہ چلتا ہے، ان میں سے پہلی حدیث ابن ماجہ نے دوسری سند سے بواسطہ یزید بن ابی حبیب انہوں نے ابوالخیر سے بحوالہ ابورہم نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: سب سے افضل سفارش یہ ہے کہ تم نکاح کرانے میں سفارش کرو تا کہ دو افراد مل جائیں۔ اسی طرح طبرانی نے نقل کیا ہے البتہ متن میں یہ الفاظ زائد روایت کیے ہیں \"اور سب سے بڑا گناہ یہ ہے کہ کوئی کسی مسلمان کا مال ناجائز طور پر ہتھیا لے\"۔ (حدیث) اگر کسی راوی سے \"اسمعی\" کہنے میں غلطی نہ ہوئی ہو تو یہ صحابی ہیں انہیں سمعی کہا جاتا ہے یہ احزاب بن اسید نہیں ہیں کیونکہ انہیں صحابی ہونے کا شرف حاصل نہیں ہے۔ اور یہ ناممکن نہیں کہ ایک ہی کنیت اور نسبت دو آدمیوں کی واقع ہو جائے۔","",{"fn":"(1) الطبقات (۱۷۹/۵)\n(2) السنن الکبریٰ (۸۷/۹)\n(3) جامع المسانید (۵۸/۱۴) اسد الغابہ (۴۴۸/۴)"}],[9865,"§۹۹۰۲ ۔ ابورہیمہ(1) (تصغیر ہے) السمعی\nمستغفری اور بردگی نے ان کا ذکر کیا ہے اور ابوموسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔ ابن مندہ نے ابوخیلہ الہمی کے حالات میں ان کا ذکر کیا ہے جس کی تفصیل حرف نون میں آ رہی ہے۔ کیونکہ ابوموسیٰ نے بطریق ابن مندہ ان کا تذکرہ کیا ہے اور اس کا جواز پیش کیا ہے کہ وہ اس سے پہلے والی شخصیت ہے۔ اس کا احتمال ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۹۶) تجرید (۱۶۷/۲)"}],[9866,"§۹۹۰۳ ۔ ابوالروم(1)\nبن عمیر بن ہاشم بن عبدالدار بن عبد مناف بن قصی العبدری، مصعب کے بھائی ہیں۔ بقول البلاذری: ان کا نام عبد مناف ہے، جب مسلمان ہوئے تو یہ نام چھوڑ دیا۔ سابقین اولین میں سے ہیں۔ حبشہ ہجرت کی، پھر وہاں سے واپس آ کر اُحد میں شریک ہوئے۔ ابن کلبی کا قول ہے: خیبر سے پہلے آکر اس میں شریک ہوئے۔ امام واقدی رحمہ اللہ فرماتے ہیں: ان کی ہجرت الی الحبشہ پر اتفاق نہیں۔ ہیم بن عدی وغیرہ نے اس کی نفی کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۸۵) تجرید (۱۶۶/۲)"}],[9867,"§۹۹۰۴ ۔ ابورومی\nیعقوب بن سفیان نے ان کا ذکر کیا ہے اور بحوالہ ابن عباس رضی اللہ عنہما روایت کی ہے کہ ابورومی سب سے برے (شریر) شخص تھے، آپ صلی اللہ علیہ وسلم نے فرما دیا: اگر مجھے ابورومی نظر آ گیا تو میں اس کی گردن اتار دوں گا۔ صبح وہ خود ہی نبی صلی اللہ علیہ وسلم کی طرف آنے لگے، وہ آپ علیہ السلام کے صحابہ کے ساتھ تھے، ان سے باتیں کر رہے تھے۔ آپ نے جب دور سے انہیں دیکھا تو فرمایا: ابورومی خوش آمدید! اور انہیں جگہ دینے لگے۔ آپ نے ان سے فرمایا: \"ابورومی! گزشتہ رات تم نے کیا عمل کیا ہے؟\" وہ عرض کرنے لگے: \"اللہ کے رسول! میں ایسا کیا عمل کر سکتا ہوں حالانکہ میں تو سب سے شریر آدمی ہوں؟\"(1) آپ صلی اللہ علیہ وسلم نے فرمایا: \"خوش ہو! کیونکہ اللہ تعالیٰ نے تمہارے عمل کو جنت تک کا ذریعہ بنا دیا ہے، اس واسطے کہ اللہ تعالیٰ جو چاہتا ہے مٹاتا ہے اور جو چاہتا ہے برقرار رکھتا ہے۔\"(2)","",{"fn":"(1) اسد الغابہ (۵۸۸۶) تجرید (۱۶۶/۲)\n(2) الدر المنثور (۶۷/۴)"}],[9868,"§۹۹۰۵ ۔ ابورویحہ الثمالی(1)\nان کا نام ربیعہ بن السکن ہے، ناموں میں تذکرہ ہو چکا ہے۔ ابوموسیٰ کا قول ہے: ابورویحہ فرعی ثم سے تعلق رکھتے ہیں۔ فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس آیا آپ لوگوں میں بھائی چارہ قائم فرما رہے تھے یہی قول مستغفری کا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۸۸) تجرید (۱۶۶/۲)"}],[9869,"§۹۹۰۶ ۔ ابورویحہ الخثعمی(1)\nنبی صلی اللہ علیہ وسلم نے ان میں اور بلال مؤذن کے درمیان بھائی چارہ قائم فرمایا تھا۔ بقول بعض: ان کا نام عبداللہ بن عبدالرحمن خثعمی ہے۔ ابورویحہ نے نبی صلی اللہ علیہ وسلم سے کوئی بھی مسند حدیث نہیں نقل کی ہے۔ پھر انہوں نے بطریق محمد بن اسحاق یہ روایت نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے صحابہ رضی اللہ عنہم میں بھائی چارہ قائم کیا۔ تو بلال مولا ابوبکر مؤذن رسول اللہ صلی اللہ علیہ وسلم اور ابورویحہ عبداللہ بن عبدالرحمن خثعمی دونوں بھائی بنے۔ جب سیدنا عمر رضی اللہ عنہ نے شام میں رجسٹریشن کی تو سیدنا بلال رضی اللہ عنہ سے فرمایا: آپ کی رجسٹریشن کس کے ساتھ کروں؟ انہوں نے کہا: ابورویحہ کے ساتھ میں ان سے مذکورہ بھائی چارہ نہیں توڑ سکتا۔ چنانچہ آپ نے بلال رضی اللہ عنہ کی وجہ سے انہیں ان کے ساتھ ملا دیا اور حبشہ کا دیوان (رجسٹر) خثعم کے ساتھ شامل کر دیا۔ آج تک وہ شام میں خثعم کے ساتھ ہیں۔ ابواحمد الحاکم کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ مجھے ان کے نام کا پتہ نہیں۔ ابوموسیٰ فرماتے ہیں: ابوعبداللہ بن مندہ نے \"الکنیٰ\" میں ان کا ذکر کیا ہے لیکن ہمارے پاس ان کی کتاب میں صحابہ رضی اللہ عنہم میں ان کا ذکر نہیں۔ پھر بطریق ابواحمد الحاکم بحوالہ ابوالدرداء روایت کی ہے کہ جب عمر بیت المقدس کی فتح سے واپس آئے اور جابیہ جانے لگے تو سیدنا بلال رضی اللہ عنہ نے ان سے درخواست کی مجھے شام ٹھہرا دیں، چنانچہ آپ نے ایسا ہی کیا۔ اور سیدنا بلال بولے: ابورویحہ میرا بھائی ہے۔ نبی صلی اللہ علیہ وسلم نے ہم میں بھائی چارہ قائم فرمایا تھا۔ پھر وہ دونوں بنی خولان کے ایک گھر والے کے پاس فروکش ہوئے۔ پھر وہ اور ان کا بھائی بنی خولان کے قبیلہ کے ہاں گئے ان سے کہا: ہم تم سے رشتہ لینے آئے ہیں۔ ہم دونوں کافر تھے، اللہ تعالیٰ نے ہمیں راہ ہدایت نصیب فرمائی۔ غلام تھے، اللہ تعالیٰ نے آزادی عطا فرمائی۔ نادار و فقیر تھے، اللہ تعالیٰ نے بے نیاز کر دیا۔ اب اگر تم لوگ ہماری شادیاں کر دو تو اللہ کا شکر ہے اور اگر ہمیں واپس بھیج دو تو اللہ کے سوا نہ کوئی طاقت ہے اور نہ کوئی قوت۔ چنانچہ ان لوگوں نے ان دونوں کو رشتے دے دیئے۔ ابوعمر لکھتے ہیں: ابورویحہ سے مروی ہے کہ میں نبی صلی اللہ علیہ وسلم کے پاس آیا تو آپ صلی اللہ علیہ وسلم نے مجھے پرچم بنا کر دیا اور فرمایا: \"جاؤ لوگوں میں اعلان کرو! جو ابورویحہ کے جھنڈے تلے آ جائے گا اسے امن ہے\"۔(2) میں کہتا ہوں: یہ بات ربیعہ بن السکن کے حالات میں ہو چکی ہے۔ ابوموسیٰ نے فزعی اور خثعمی میں فرق کیا ہے۔ ادھر ابن الاثیر(3) ان کا تعاقب کرتے ہوئے لکھتے ہیں: فزع خثعم کا بطن ہے۔ جو فزع بن شہران بن عفرس بن حلف بن افل۔ یہی خثعم ہیں ان سے یہ بات رہ گئی کہ پہلے شخص کا نام ربیعہ بن السکن ہے اور سیدنا بلال رضی اللہ عنہ کے بھائی کا نام عبداللہ بن عبدالرحمن ہے۔ میں ان کے حالات میں ذکر کر چکا ہوں کہ یہ ان کے علاوہ ہیں جن کے ساتھ نبی صلی اللہ علیہ وسلم نے سیدنا بلال رضی اللہ عنہ کا بھائی چارہ قائم فرمایا تھا۔ ابن عساکر نے فزعی کی حدیث خثعمی کے سوانح میں نقل کی ہے، شاید وہ دونوں ان کے نزدیک ایک شخصیت ہیں۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۵۸۸۷) تجرید (۱۶۶/۲)\n(2) الاسماء والکنیٰ للدولابی (۱۹۲/۱) اسد الغابہ (۴۴۷/۴)\n(3) اسد الغابہ (۴۴۷/۴)"}],[9870,"§۹۹۰۷ ۔ ابورناب\nذال میں ذکر ہوا ہے، بقول بعض ابوذئاب ہی ابورناب ہیں۔"],[9871,"§۹۹۰۸ ۔ ابوریحانہ الازدی(1)\nبقول بعض: انصاری ان کا نام شمعون تھا، ناموں میں حرف شین میں تذکرہ ہو چکا ہے۔","",{"fn":"(1) استیعاب (۳۰۰۴) تجرید (۱۶۷/۲)"}],[9872,"§۹۹۰۹ ۔ ابوریحانہ القرشی(1)\nناموں میں عقبہ بن مالک الجہنی کے حالات میں ان کی حدیث گزر چکی ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۹۸) تجرید (۱۶۷/۲)"}],[9873,"§۹۹۱۰ ۔ ابوریطہ المذحجی(1)\nدولابی، طبرانی اور ابن مندہ نے ان کا ذکر کیا ہے اور بطریق عبداللہ بن احد الحصی بواسطہ علی بن ابی علی عمی سے بحوالہ ابوریطہ بن کرامہ مذحجی روایت نقل کی ہے، فرمایا: ہم نبی صلی اللہ علیہ وسلم کے پاس تھے۔ آپ نے ایک سفر کرنے والی جماعت سے فرمایا: ہرگز تمہارے ساتھ شوئی بیمار جانور نہ ہو اور کسی سائل کو ہرگز نہ ہٹانا اور ہرگز کوئی گمشدہ جانور اپنے ساتھ شامل نہ کرنا، اگر تمہارا (اس سفر سے) نفع (کمانے) اور سلامتی (سے واپسی) کا ارادہ ہے۔۔۔ (حدیث)(2) طبرانی کی روایت میں لکھا ہے، ابوریطہ عبداللہ بن کرامہ سے مروی ہے، مستغفری نے بطریق عمر بن صبیح، ابوحریز قاضی سجستان، بواسطہ شعبی بحوالہ ابوریطہ مذحجی نبی صلی اللہ علیہ وسلم سے روایت کی ہے کہ ایک دفعہ آپ مغرب اور عشاء کے درمیانی وقت میں بیٹھے تھے کہ ایک جماعت گزری جو آہستہ آہستہ جارہی تھی۔۔۔ پھر وہ حدیث ذکر کی۔ بغوی نے ان کا ذکر کیا تو لکھا، ابوریطہ(3)، ان کی کوئی روایت نہیں نقل کی۔","",{"fn":"(1) اسد الغابہ (۵۹۰۰) تجرید (۱۶۷/۲)\n(2) مجمع الزوائد (۲۱۲/۳) المعجم الکبیر (۳۷۶/۲۲) کنز العمال (۱۷۶/۷) (۴۴۰۲۲)\n(3) المعجم الکبیر (۹۴۱/۲۲) مجمع الزوائد (۲۱۲/۳) الکنیٰ للدولابی (۳۱/۱)"}],[9874,"§۹۹۱۱ ۔ ابوریطہ(1) (دوسرے، بے نسبت)\nابونعیم نے ان کا تذکرہ کیا اور بطریق حسن بن سفیان بحوالہ ریطہ روایت کی ہے ان کے والد صحابی رسول صلی اللہ علیہ وسلم تھے۔ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں رکابی چاٹ لوں یہ مجھے اسے کھانے سے بھر کر صدقہ کرنے سے زیادہ بہتر ہے۔(2) ابوموسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۹۹) تجرید (۱۶۷/۲)\n(2) جامع المسانید (۶۴/۱۴) اسد الغابہ (۴۵۰/۴)"}],[9875,"§۹۹۱۲ ۔ ابوریمہ(1)\nابن حبان نے بغیر نام کے ان کا صحابہ رضی اللہ عنہم میں ذکر کیا ہے اور ان کے حالات کا کچھ بیان نہیں کیا۔ ابن مندہ اور ابونعیم بطریق منہال بن خلیفہ بحوالہ ازرق بن قیس روایت کرتے ہیں کہ ہمیں ابوریمہ نامی ایک شخص نماز پڑھاتے تھے وہ دائیں بائیں ایسے سلام پھیرتے تھے کہ ان کے رخساروں کی سپیدی نظر آتی تھی۔ پھر انہوں نے فرمایا: میں نے تمہیں ایسے ہی نماز پڑھائی ہے جیسے میں نے رسول اللہ صلی اللہ علیہ وسلم کو نماز پڑھتے دیکھا ہے۔ ابن مندہ کا بیان ہے(2) شعبہ نے یہ روایت بواسطہ ازرق بن قیس بن عبداللہ بن ریاح بحوالہ ایک صحابی جن کا نام نہیں ذکر کیا نقل کی ہے۔ اطراف میں المزی نے لکھا ہے: ابوداؤد نے اسی سند سے نقل کی ہے۔ لیکن مجھے سنن کے کسی نسخہ میں یہ حدیث نہیں ملی جن میں سے ایک نسخہ ابوالفضل بن طاہر کا ایک نسخہ جو خطیب کے قلم سے منقول ہے۔ حفاظ (حدیث) کی ایک جماعت نے دونوں کا مقابلہ کیا وہ انتہائی محفوظ ہے۔ اس پر اتفاق ہے کہ صحابی ابورمثہ یعنی طاء سے پہلے میم ہے ایسا ہی طبرانی یہ حدیث ابورمثہ کی مسند کے حوالہ سے اپنی معجم میں روایت کی ہے اور اسی طرح میں نے مستدرک حاکم میں دیکھی ہے۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۵۹۰۱) تجرید (۱۶۷/۲)\n(2) ابوداؤد کتاب الصلاۃ باب فی الرجل یتطوع فی مکانہ الذی صلی بہ المکتوبۃ (۱۰۰۷) مسند احمد (۳۱۸۲)"}],[9876,"§۹۹۱۳ ۔ ابورافع الصائغ(1)\nان کا نام شفیع ہے مدنی ہیں بصرہ فروکش ہوئے۔ یہ بنت نجار کے مولا ہیں۔ بقول بعض: ان کے چچا زاد ہیں۔ ابن سعد نے اہل بصرہ کے پہلے طبقہ میں ان کا ذکر کیا۔ لکھتے ہیں: یہ بہت پہلے مدینہ سے چلے گئے تھے۔ ثقہ ہیں۔ الحاکم ابواحمد نے الکنیٰ میں بطریق مرحوم العطار بواسطہ ثابت البنانی بحوالہ ابورافع روایت کی ہے کہ جاہلیت میں انہوں نے درندے کا گوشت کھا لیا تھا۔(2) میں کہتا ہوں: سیدنا ابوہریرہ رضی اللہ عنہ سے بکثرت اسی طرح خلفاء اربعہ ابن مسعود، زید بن ثابت، ابی بن کعب اور ابوموسیٰ وغیرہ سے روایت کرتے ہیں۔ ان سے ان کا بیٹا عبدالرحمن، ثابت البنانی، بکر مازنی، قتادہ اور سلیمان تیمی وغیرہ روایت کرتے ہیں۔ عجلی کا قول ہے: اکابر تابعین میں سے معتبر ہیں۔ طبرانی نے اس بات کو وزنی قرار دیا ہے کہ ان کی کنیت ہی ان کا نام ہے اور ان کی توثیق کی ہے۔ ابوعمر کا قول ہے: تابعین علماء میں سے مشہور ہیں۔ دور جاہلیت پایا ہے۔ ابراہیم حربی نے \"غریب الحدیث\" میں عمدہ سند سے بحوالہ ابورافع روایت کی ہے۔ فرمایا: سیدنا عمر رضی اللہ عنہ مجھ سے مزاح کر کے کہتے: سب سے جھوٹا صائغ ہے۔ جو آج کو کل کہتا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۶۸) استیعاب (۲۹۸۸) تجرید (۱۶۴/۲)\n(2) اسد الغابہ (۴۴۱/۴)"}],[9877,"§۹۹۱۴ ۔ ابورجاء العطاردی(1)\nبقول بعض: نام عمران بن ملحان، یا ابن تیم، ابن عبداللہ۔ ایک قول ہے: ان کا نام عطارد ہے۔ ابن قتیبہ لکھتے ہیں: ہجرت سے گیارہ(۱۱) سال پہلے پیدا ہوئے۔ اور ہشام بن عبدالملک کی خلافت تک زندہ رہے۔ تاریخ مظفری میں میں نے ایسا ہی لکھا دیکھا ہے۔ اشعث بن سوار کا قول ہے: ان کی عمر ایک سو ستائیس(۱۲۷) سال تھی۔ صحیح بخاری میں ایک طریق سے مروی ہے جب رسول اللہ صلی اللہ علیہ وسلم مبعوث ہوئے تو ہم لوگ آگ کی طرف یعنی مسیلمہ کذاب کی طرف بھاگے۔ بقول ابوحاتم: دور جاہلیت کے ہیں۔ فتح کے بعد اسلام لائے اور ایک سو بیس(۱۲۰) سال زندہ رہے۔ امام بخاری رحمہ اللہ فرماتے ہیں: سیدنا حسن سے پہلے فوت ہوئے۔ ان کی وفات دس(۱۰) میں ہوئی۔ نبی صلی اللہ علیہ وسلم سے مرسل روایت کرتے ہیں۔ سیدنا عمر، علی، عمران بن حصین، سمرہ بن جندب، ابن عباس اور سیدہ عائشہ رضی اللہ عنہم سے روایت کرتے ہیں۔ جبکہ ان سے روایت کرنے والے مندرجہ ذیل افراد ہیں: ایوب، جریر بن حازم، عوف الاعرابی، مہدی بن میمون، عمران القصیر، ابوالاشہب اور الجعد ابوعثمان۔ ابن سعد کا قول ہے: انہیں علم، قرآن اور روایت حاصل تھی وہ معتبر ہیں۔ اپنی قوم کی چالیس سال امامت کی اور عمر بن عبدالعزیز کی خلافت میں فوت ہوئے۔ واقدی کا قول ہے: ۷اھ میں فوت ہوئے۔ جو وہم ہے۔ ذہلی فرماتے ہیں: حسن سے پہلے فوت ہوئے، میرے خیال میں ۷اھ کا سال ہے۔ یحییٰ بن معین، ابوزرعہ اور ابن عبدالبر نے انہیں ثقہ لکھا ہے اور یہ اضافہ نقل کیا ہے، البتہ ان سے کبھی غفلت ہو جاتی تھی۔","",{"fn":"(1) اسد الغابہ (۵۸۷۲) تجرید (۱۶۵/۲)"}],[9878,"§۹۹۱۵ ۔ ابورزین الاسدی\nمسعود بن مالک، تابعی ہیں۔ اس میں اختلاف ہے کہ آیا انہوں نے دور نبوت پایا ہے یا نہیں۔ قسم چہارم میں ان کا تذکرہ ہوگا۔"],[9879,"§۹۹۱۶ ۔ ابوالرقاد\nان کا نام شولیس ہے۔"],[9880,"§۹۹۱۷ ۔ ابورمح الخزاعی\nدعبل بن علی نے طبقات الشعراء میں ان کا تذکرہ کیا ہے کہ اہل حجاز کے مخضرمی ہیں۔ انہوں نے ہی سیدنا حسین بن علی رضی اللہ عنہما کا مندرجہ ذیل اشعار میں مرثیہ کہا۔ میں آل محمد کے گھرانوں سے گزرا تو وہ مجھے ایسے نظر نہ آئے جیسے آباد تھے۔ اللہ تعالیٰ ان گھروں اور مکینوں کو دور نہ کرے اگرچہ وہ اپنے مکینوں سے خالی ہو گئے۔"],[9881,"§۹۹۱۸ ۔ ابورہم السمعی\nبقول بعض الظہر کی۔ نام احزاب بن اسید تھا۔ ناموں میں تذکرہ ہوا ہے۔"],[9882,"§۹۹۱۹ ۔ ابورزین(1)\nمسعود بن مالک اسدی، ان کے مولا ہیں۔ بقول بعض: سیدنا علی رضی اللہ عنہ کے مولا ہیں۔ نام عبید ہے، کوفہ فروکش ہوئے، ابن ام مکتوم، علی بن ابی طالب، ابوموسیٰ اشعری، ابوہریرہ رضی اللہ عنہ وغیرہ سے روایت کرتے ہیں۔ جبکہ ان سے ان کا بیٹا عبداللہ، اسماعیل بن ابی خالد، عطاء بن السائب، اعمش، منصور، موسیٰ بن ابی عائشہ اور مغیرہ بن مقسم روایت کرتے ہیں۔ ابوحاتم فرماتے ہیں: بقول بعض: صفین میں سیدنا علی رضی اللہ عنہ کا ساتھ دیا۔ امام بخاری رحمہ اللہ نے اپنی صحیح کے باب الطہارۃ میں ان کا فعل تعلیقاً ذکر کیا ہے اور \"الادب المفرد\" میں ان کی سند سے روایت کی ہے۔ اور امام مسلم اور چاروں نے ان کی روایت سے بحوالہ صحابہ رضی اللہ عنہم حدیث نقل کی ہے۔ ابن شاہین کا بیان ہے صحابی ہیں۔ ابوموسیٰ نے ان کا تعاقب کرتے ہوئے لکھا ہے: یہ صحابی نہیں اور نہ انہوں نے دور نبوی پایا ہے۔ پھر بطریق عاصم بن ابی وائل روایت کی ہے، انہیں ابورزین پر تعجب نہیں ہوتا جو بوڑھے ہو گئے۔ وہ عہد فاروقی میں لڑکے تھے اور میں مرد تھا۔ بقول بعض: وہ ابووائل سے بڑے تھے۔ عالم سمجھدار تھے۔ ایسا ہی تہذیب میں المزی کے قلم سے لکھا ہے مغلطائی ان کا تعاقب کرتے ہوئے لکھتے ہیں: \"فهما\" فاء سے غلط ہے \"بھما\" ہے۔ ایسا ہی امام بخاری رحمہ اللہ نے یحییٰ قطان سے بحوالہ ابوبکر نقل کیا ہے: ابورزین مجھ سے بڑے ہیں۔ یحییٰ فرماتے ہیں: وہ دونوں کا علم رکھتے تھے، ابوزرعہ اور عجلی وغیرہ نے انہیں ثقہ لکھا ہے۔ میں کہتا ہوں: ان کی سیدنا معاذ بن جبل رضی اللہ عنہ سے روایت ہے جو مرسل ہے، ابوالحسن بن قطان نے انکار کیا ہے کہ انہوں نے ابن ام مکتوم کا دور پایا ہو شعبہ کا قول ہے جو ابن ابی حاتم نے بحوالہ ان کے مراسیل میں نقل کیا ہے، انہوں نے ابن مسعود سے سماع حدیث نہیں کیا ہے۔ بقول بعض: عبیداللہ بن زیاد نے ۶۰ھ کے بعد انہیں قتل کر دیا تھا۔ ایک قول ہے جماجم تک ۸۰ھ کے بعد زندہ رہے جس کی تاریخ ابن قانع نے پچانوے(۹۵) لکھی ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۷۶) استیعاب (۳۰۰۰) تجرید (۱۶۵/۲)"}],[9883,"§۹۹۲۰ ۔ ابورہم الانماری(1)\nابوبکر بن علی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور یہ روایت(2) نقل کی ہے کہ ابورہم انماری نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم جب لیٹنے لگتے تو فرماتے: بسم اللہ اللھم اغفر لی ذنبی واخس شیطانی وفک رھانی۔ (حدیث)(3) ابوموسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے جو غلط ہے اور تحریف و تصحیف کا نتیجہ ہے، یہ نام تو زہیر انماری تھا ایسا ہی ابن ابی عاصم نے لکھا ہے جو ان کی کتاب الدعاء میں ہے اور طبرانی نے یہ دعا نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۸۹) تجرید (۱۶۶/۲)\n(2) الاحاد والمثانی (۲۸۷۸)\n(3) ابوداؤد کتاب الادب باب ما یقال عند النوم (۵۰۵۴) کنز العمال (۱۸۲۳۶) مرقاۃ (۲۴۰۹)"}],[9884,"§۹۹۲۱ ۔ ابورہم الظہری(1)\nابو بکر بن علی نے ان کا تذکرہ کیا ہے اور ابوموسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے جو غلط ہے یہ اسمعی ہیں اور ان کا نام احزاب ہے۔ صحابی نہیں ہیں۔ ابن ابی عاصم(2) نے بحوالہ یحییٰ بن سعید العطار ان کا ذکر کیا ہے کہ حمص میں دوسو میں انہیں وظیفہ ملتا تھا، بہت بوڑھے تھے، پیلا خضاب لگاتے تھے، ان کا عمارہ نامی بیٹا یزید بن المہلب کے ساتھ شہید ہوا۔","",{"fn":"(1) اسد الغابہ (۵۸۹۱) تجرید (۱۶۶/۲)\n(2) الاحاد والمثانی (۳۳۳/۵)"}],[9885,"§۹۹۲۲ ۔ ابورہیمہ الشجاعی(1)\nابوموسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے اور حوالہ جعفر مستغفری کا دیا ہے جو غلط ہے شجاعی سماعی کی بگڑی ہوئی صورت ہے اور جو حدیث مستغفری نے ذکر کی ہے وہ وہی حدیث ہے جو قسم اوّل میں بطریق سلیمان بن داؤد کی ان کے اتباع میں گزری ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۹۵) تجرید (۱۶۷/۲)"}],[9886,"§۹۹۲۳ ۔ ابوریحانہ(1)\nعبداللہ بن مطر۔ ابو نعیم نے ان کا ذکر کیا ہے جو غلط ہے۔ کیونکہ ابوریحان صحابی کا نام شمعون ہے، رہے عبداللہ بن مطر تو یہ تابعی ہیں، خادم نبی صلی اللہ علیہ وسلم سیدنا سفینہ سے روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۸۹۷) تجرید (۱۶۷/۲)"}],[9887,"§۹۹۲۴ ۔ ابوریطہ مذحجی(1)\nابوموسیٰ نے ان میں اور ابورائطہ میں فرق کیا ہے جبکہ دونوں ایک ہیں اور حدیث بھی ایک ہے۔ بقول بعض: ابورائطہ سے اور بقول بعض: ابوریطہ سے مروی ہے جس کی وضاحت قسم اوّل میں کر چکا ہوں۔","",{"fn":"(1) اسد الغابہ (۵۹۰۲) تجرید (۱۶۷/۲)"}],[9888,"§۹۹۲۵ ۔ ابوریمہ\nقسم اول میں ان کے متعلق کلام ہو چکا ہے۔"],[9889,"§۹۹۲۶ ۔ ابوزرارہ انصاری\nابن ابی خیثمہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ابو عمر لکھتے ہیں: اس میں تامل ہے۔ بغوی کا قول ہے: ان کا نام معلوم نہیں، اور نہ میں یہ جانتا ہوں آیا صحابی ہیں یا نہیں؟ پھر انہوں نے اور ابن ابی خیثمہ نے یہ روایت نقل کی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جس نے تین بار منادی (مؤذن) کی آواز سنی اور جواب نہیں دیا اسے منافقوں میں شمار کیا جائے گا“۔(1) یہی روایت دوسرے شیخ سے بحوالہ ابان مرسل نقل کی ہے۔ بعض نے یہ امکان ظاہر کیا ہے کہ ابوزرارہ، عبدالرحمن بن سعد بن زرارہ ہی ہیں۔ قسم ثانی حرف عین میں ان کا تذکرہ ہو چکا ہے۔","",{"fn":"(1) جامع المسانید (۶۹/۱۴)"}],[9890,"§۹۹۲۷ ۔ ابوزرارہ نخعی(1)\nانہیں آنے کی سعادت حاصل ہے۔ ابن کلبی کا قول ہے: یہ بات ابن الاثیر نے بحوالہ ابن دباغ نقل کی ہے، جبکہ جمہرہ میں زرارہ نام ہے نہ کہ کنیت۔ میں کہتا ہوں: بات یہی ہے، ناموں میں تذکرہ ہو چکا ہے، میں نے صرف احتمال کی وجہ سے ذکر کر دیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۰۳) تجرید (۱۶۷/۲) ایضا"}],[9891,"§۹۹۲۸ ۔ ابوزعراء(1)\nابن مندہ نے ان کا ذکر کیا ہے کہ اہل مصر میں شمار ہوتے ہیں، پھر ان کی روایت نقل کی ہے، فرماتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں نکلا رسول اللہ صلی اللہ علیہ وسلم ہم سواریوں پہ تھے۔ میں نے سنا، آپ صلی اللہ علیہ وسلم نے فرمایا: مجھے دجال سے زیادہ بڑے فتنے کا اپنی امت کے بارے میں خوف ہے۔۔۔۔ (حدیث)(2) اس میں ہے گمراہ حکمرانوں کا خوف ہے۔ محمد بن ربیع جیزی نے اُن صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے جو مصر میں داخل ہوئے کہ اہل مصر کی ان سے ایک حدیث مروی ہے پھر مذکورہ سند سے اسے بیان کیا۔","",{"fn":"(1) اسد الغابہ (۵۹۰۳) تجرید (۱۶۷/۲) السلسلۃ الصحیحۃ (۱۵۸۲) (۱۹۸۹) جامع المسانید (۷۱/۱۴) کنز العمال (۲۹۰۴۳)\n(2) اسد الغابہ (۵۹۰۷) استیعاب (۳۰۰۸) تجرید (۱۶۷/۲)"}],[9892,"§۹۹۲۹ ۔ ابوزعنہ(1)\nشاعر۔ نام میں اختلاف ہے۔ عامر بن کعب بن عمرو بن خدیج/ عبداللہ بن عمرو/ کعب بن عمرو، طبری فرماتے ہیں: بدر میں شریک ہوئے، یہی ابو عمر کا بیان ہے۔ میں کہتا ہوں: ابن اسحاق(2) کا بیان ہے: اُحد میں شریک ہوئے، پھر فرماتے ہیں بنی جشم بن خزرج کے ایک شخص ابوزعنہ بن عبداللہ بن عمرو بن عتبہ نے اُحد کے روز کہا، میں ابوزعنہ ہوں، بڑھاپا مجھے باز رکھتا ہے۔ باعث رسوائی و شرمندگی کے کام سے صرف درد کی وجہ سے بچا جا سکتا ہے۔ خزرجی جو جشم سے ہے اپنے علاقوں کی حفاظت کرتا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۰۸) استیعاب (۳۰۰۹) تجرید (۱۶۸/۲)\n(2) السیرۃ النبویۃ (۱۳۱/۳)"}],[9893,"§۹۹۳۰ ۔ ابوزمعہ بلوی\nعسکری نے ان کا نام عبید ابن ارقم بتایا ہے، ابو موسیٰ کی کتاب میں یہ نام بغیر تصغیر عبید اور والد کے نام کے بغیر لکھا ہے۔ بغوی اور ابن السکن وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق ابن لہیعہ بحوالہ ابو قیس مولا بنی صیح روایت کی ہے کہ میں نے ابوزمعہ بلوی کو فرماتے سنا (اور وہ بیعت رضوان کے شرکاء میں سے تھے) ایک دن فسطاط تشریف لائے میدان میں کھڑے ہوئے انہیں عبداللہ بن عمرو کی بعض سختیوں کا علم ہوا تھا، فرمانے لگے: لوگوں پر سختی نہ کرو کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: بنی اسرائیل کے ایک شخص نے ننانوے(۹۹) قتل کیے تھے۔(1) حدیث طویل ہے۔ یہ حدیث میں نے معجم بغوی میں حرف قاف کے آخر میں دیکھی ہے، مجھے اس کا سبب معلوم نہ ہو سکا پھر میں نے دوسرا نسخہ دیکھا۔ بقول بعض: ان کا نام عبید بن آدم ہے۔","",{"fn":"(1) المعجم الکبیر (۷۸۸/۲۲) مجمع الزوائد (۲۱۳/۱۰) جامع المسانید (۷۳/۱۴)"}],[9894,"§۹۹۳۱ ۔ ابوزہراء بلوی(1)\nصحابی ہیں۔ فتح مصر میں شریک تھے۔ ابن مندہ نے بحوالہ ابن یونس ان کا ذکر کیا ہے، مجھے یہ لفظی غلطی لگتی ہے۔ یہ نام تو ابوزعراء ہے، کیونکہ تاریخ ابن یونس میں ابوزعراء کے علاوہ اور کوئی نہیں۔ ایسا ہی ابن ربیع جیزی کی کتاب ”مصر میں داخل ہونے والے صحابہ رضی اللہ عنہم“ میں ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۱۰) تجرید (۱۶۸/۲)"}],[9895,"§۹۹۳۲ ۔ ابوزہراء قشیری\nقسم ثالث میں ان کا ذکر ہوگا، ممکن ہے اس قسم میں سے ہوں، کیونکہ ان کے حالات میں آتا ہے کہ ان لوگوں میں سے تھے جنہیں سیدنا یزید بن ابی سفیان رضی اللہ عنہ نے شام کی بعض فتوحات میں امیر مقرر کیا تھا، اور بارہا گزر چکا ہے کہ فتوحات میں صرف صحابہ کرام رضی اللہ عنہم ہی امیر بنائے جاتے تھے۔ اور اس واقعہ میں دحیہ بن خلیفہ کے ساتھ ملا دیا ہے۔"],[9896,"§۹۹۳۳ ۔ ابوزہیر بن اسید\nبن جعونہ۔ قرہ بن دعموص کے حالات میں ان کا ذکر ہو چکا ہے۔"],[9897,"§۹۹۳۴ ۔ ابوزہیر الانماری\nابوالزہیر نامی حضرات میں ذکر ہوا ہے۔"],[9898,"§۹۹۳۵ ۔ ابوزہیر ثقفی(1)\nابن حبان ”الصحابہ“ میں لکھتے ہیں: وفد میں شامل تھے۔ بقول بغوی: طائف کے رہائشی تھے۔ بقول ابن ماکولا: نبی صلی اللہ علیہ وسلم کے پاس آئے۔ ابو احمد نے ”الکنیٰ“ میں ابوزہیر بن معاذ اور ابوزہیر ثقفی میں فرق کیا ہے۔ ثقفی کے متعلق لکھتے ہیں: ان کا نام عمارہ بن حمید تھا اور یہ ابوبکر بن ابی زہیر کے والد ہیں اور حدیث ابوزہیر مسند احمد ابن ماجہ اور الدارقطنی نے الافراد میں حسن غریب سند سے بطریق نافع بن عمر حجی بحوالہ ابوزہیر ثقفی سے نقل کی ہے کہ نبی صلی اللہ علیہ وسلم نے طائف کے علاقے نجادہ میں ہم سے خطاب کیا، فرمایا: ”عنقریب تمہیں جہنمیوں سے جنتی علیحدہ نظر آئیں گے“۔ لوگوں نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم؟ کس طرح؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اچھی اور بری تعریف سے، تم ہی ایک دوسرے کے گواہ ہو“۔(2) الدارقطنی کا قول ہے: امیہ بن صفوان اس میں منفرد ہے اور حاکم نے یہ روایت بطریق سفیان بن عیینہ نقل کی ہے جو سنداً صحیح ہے۔ حدیث معاذ ناموں میں گزر چکی ہے۔ المزی نے یہ بھی نقل کیا ہے کہ انہیں عمارہ بن رویبہ بھی کہا جاتا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۱۳) تجرید (۱۶۸/۲)\n(2) ابن ماجہ کتاب الزہد باب الثناء الحسن (۴۲۲۱) مسند احمد (۴۱۶/۲)"}],[9899,"§۹۹۳۶ ۔ ابوزہیر(1)\nبن معاذ بن ریاح ثقفی۔ بقول حسین بن محمد قبانی: صحابی ہیں۔ ایک قول ہے: معاذ ان کا نام ہے، حاکم ابواحمد کا قول ہے: ابراہیم حربی کا بیان ہے: ابوزہیر بن معاذ ان صحابہ رضی اللہ عنہم سے ہیں جن کے ناموں سے زیادہ ان کی کنیت مشہور ہے۔ اور پھر ان کی یہ حدیث نقل کی: ”جب تم نام رکھو تو عبداللہ اور عبد الرحمن جیسے نام رکھو“۔(2) یہی حدیث طبرانی نے معاذ ثقفی کے حالات میں نقل کی ہے میں نے وہیں اس کی علت بیان کی ہے اور المزی نے ابوزہیر ثقفی کے حالات میں درج کی ہے، فرماتے ہیں: بقول بعض: ابوزہیر بن معاذ۔","",{"fn":"(1) اسد الغابہ (۵۹۱۴) تجرید (۱۶۸/۲)\n(2) مجمع الزوائد (۵۰/۸) المعجم الکبیر (۳۸۳/۲۰) کنز العمال (۴۰/۹۶) اتحاف السادۃ المتقین (۳۸۷/۵)"}],[9900,"§۹۹۳۷ ۔ ابوزہیر النمیری(1)\nبقول بعض: ابوزہیر الانماری جنہیں ابوزہر بھی کہا جاتا ہے، راجح یہی ہے کہ وہ اور ہیں۔ ابن مندہ صبیح بن مخرمہ کے طریق سے بحوالہ ابو صبح مقبری روایت کرتے ہیں، فرمایا: ہم ابوزہیر نمیری کے پاس بیٹھا کرتے تھے جو صحابی تھے۔ وہ بہت اچھی گفتگو کرتے اور جب ہم میں سے کوئی شخص دعا کرتا تو فرماتے: آمین کہہ کر ختم کرنا، کیونکہ دعا میں آمین ایسے ہی ہے جیسے خط پر مہر۔ پھر ابوزہیر کہنے لگے: میں تمہیں اس کے متعلق بتاتا ہوں ایک رات ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چلتے ہوئے باہر نکلے، ایک خیمہ میں ایک شخص کے پاس ٹھہر گئے جس نے دعا کرنے میں اصرار کیا اور رسول اللہ صلی اللہ علیہ وسلم اس کی بات سنتے جا رہے تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اگر اس نے مہر لگا دی تو اس کی دعا قبول ہے“۔ لوگوں میں سے ایک شخص عرض کرنے لگا: کس چیز سے مہر لگائے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”آمین سے، اگر اس نے آمین سے دعا ختم کی تو قبول ہوئی۔ چنانچہ جس شخص نے آپ صلی اللہ علیہ وسلم سے یہ بات سنی وہ اس دعا کرنے والے) کے پاس پہنچا اور کہنے لگا: ”مبارک ہو،(2) بھائی ہر دعا آمین پر ختم کیا کرو“۔ پھر فرماتے ہیں: یہ غریب حدیث ہے، جس میں فریابی صبح سے نقل کرنے میں منفرد ہے۔ بغوی اور طبرانی نے مسند شامیین میں بطریق ضمضم بن زرعہ بواسطہ شریح بن عبید حضرمی بحوالہ ابوزہیر نمیری (جو صحابی ہیں) روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ٹڈیوں (جو سبزہ کھاتی ہیں، گھریلو نجاست کھانے والی ٹڈیاں مراد نہیں) کو قتل نہ کرو، کیونکہ یہ اللہ کے لشکروں میں سے ایک بڑی فوج ہے۔(3) بقول بغوی: شام کے رہائشی تھے۔ یحییٰ بن نفیر کے حالات میں اس کا کچھ تذکرہ ہوا ہے۔ احتمال ہے یہ ابوزہیر بن جعونہ ہوں جن کا ذکر ہو چکا ہے کیونکہ وہ بھی نمیری ہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۱۵) تجرید (۱۶۸/۲)\n(2) ابوداؤد کتاب الصلاۃ باب التامین وراء الامام (۹۳۸) کنز العمال (۳۲۳۳) مرقاۃ المصابیح (۸۴۶۵)\n(3) المعجم الکبیر (۷۵۷/۲۲) مجمع الزوائد (۳۹/۴) جامع المسانید (۷۵/۱۴)"}],[9901,"§۹۹۳۸ ۔ ابوزوائد یمانی(1)\nمطین اور الکنی میں دولابی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ فاکہی اور جعفر فریابی نے کتاب النکاح میں ابراہیم بن میسرہ سے صحیح سند کے ساتھ نقل کیا ہے کہ ہم طواف کر رہے تھے تو طاؤس مجھ سے کہنے لگے: یا تمہیں نکاح کرنا ہی پڑے گا یا میں تمہیں وہ بات کہوں جو سیدنا عمر رضی اللہ عنہ نے ابوزوائد سے کہی تھی: ”کیا تم عاجزی یا زنا کی وجہ سے نکاح نہیں کر رہے؟“ اور طبرانی بطریق زیاد بن نصر بواسطہ سلیم بن مطین بحوالہ اپنے والد وہ ابوزوائد سے روایت کرتے ہیں، فرمایا: حجتہ الوداع(2) کے موقعہ پر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھا، پھر لمبی حدیث ذکر کی جس کا کچھ حصہ ابوداؤد نے اسی سند سے نقل کیا ہے جس کی طرف حرف ذال میں اشارہ ہو چکا ہے۔ ان میں سے کسی کا کہنا ہے: ابوزوائد وہی ذوالزوائد ہیں جن کا امام بخاری رحمہ اللہ نے گمنتیوں میں ذکر کیا ہے اور اسی سند سے اس حدیث کا ایک گوشہ نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۰۹) تجرید (۱۶۹/۱)\n(2) ابوداؤد کتاب الخراج والامارۃ باب فی کراہیۃ الافتراض فی آخر الزمان (۲۹۵۹) التاریخ الکبیر (۲۶۵/۳) الاحاد والمثانی (۱۱۸/۵) المعجم الکبیر (۸۹۴/۲۲) جامع المسانید (۷۸/۱۴)"}],[9902,"§۹۹۳۹ ۔ ابوزیاد(1)\nمولا بنی تج۔ یہ صدیق اکبر رضی اللہ عنہ سے اور ان سے خالد بن معدان روایت کرتے ہیں۔ ایسا ہی تجرید میں ہے(2) شاید ان کے نزدیک یہ محضرمی ہیں مجھے ان کی ایک اور مرفوع حدیث مل گئی ہے جو طبرانی نے مسند شامیین میں بطریق سفیان بن حبیب، ثور بن زید سے بواسطہ خالد بن معدان بحوالہ ابوزیاد نقل کی ہے۔ فرمایا: ”میں اس بات کو نہیں بھولا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا جب آپ صلی اللہ علیہ وسلم نماز پڑھتے تو دایاں ہاتھ بائیں ہاتھ کے اوپر رکھتے تھے“۔","",{"fn":"(1) تجرید (۱۶۹/۲)\n(2) تجرید (۱۶۱)"}],[9903,"§۹۹۴۰ ۔ ابوزید انصاری\nناموں میں زرارہ میں تذکرہ ہوا ہے۔"],[9904,"§۹۹۴۱ ۔ ابوزید(1)\nجنہوں نے قرآن جمع کیا تھا۔(2) (صحیح بخاری میں حدیث انس میں بغیر نام کے ان کا ذکر آتا ہے سیدنا انس رضی اللہ عنہ فرماتے ہیں: میرے چچاؤں میں سے ایک ہیں۔ ان کے نام کے بارے اختلاف ہے۔ اوس/ ثابت بن زید/ معاذ/ سعد بن عبید/ قیس بن السکن یہی راجح ہے، جیسا کہ میں نے حرف قاف میں بیان کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۱۷) تجرید (۱۶۹/۲)\n(2) اسد الغابہ (۴۵۶/۴)"}],[9905,"§۹۹۴۲ ۔ ابوزید(1)\nبن اخطب۔ نام عمرو بن اخطب بن رفاعہ بن محمود بن بشر بن عبداللہ بن الضیف بن احمد بن عدی بن ثعلبہ بن حارثہ بن عمرو بن عامر انصاری خزرجی۔ ابوزید کنیت سے مشہور ہیں۔ عزرہ بن ثابت کے نانا ہوتے ہیں۔(2) ترمذی نے ان کی روایت نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے میرے چہرے پر ہاتھ پھیرا اور میرے لیے دعا فرمائی۔(3) امام احمد رحمہ اللہ کی صرف اس حدیث میں ہے اس سے میرا حسن و جمال بڑھ گیا۔ فرماتے ہیں: مجھے کئی لوگوں نے بتایا کہ ان کی عمر سو(۱۰۰) سے زائد کی ہوگئی پھر بھی ان کے سر اور داڑھی کے بال سیاہ تھے۔ امام احمد رحمہ اللہ کی روایت میں دوسری سند سے ہے جو ابو نہیک سے مروی ہے کہ مجھ سے ابو زید نے بیان کیا۔ رسول اللہ صلی اللہ علیہ وسلم نے پانی طلب کیا تو میں ایک برتن میں پانی لے کر حاضر ہوا، اس میں کہیں سے ایک بال پڑ گیا، میں نے وہ بال نکال پھینکا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اے اللہ! اسے حسن و جمال عطا فرما“۔(4) فرماتے ہیں: میں نے انہیں چورانوے(۹۴) برس کی عمر میں دیکھا، ان کی داڑھی میں ایک بھی سفید بال نہ تھا۔ ابن حبان اور حاکم نے اسے صحیح قرار دیا ہے۔ مسلم میں اسی سند سے ہے: ہمیں رسول اللہ صلی اللہ علیہ وسلم نے فجر کی نماز پڑھائی اور خطاب کرنے منبر پر تشریف لے گئے، اور ظہر تک خطاب کیا۔۔۔۔ (حدیث) شمائل ترمذی میں مذکورہ طریق سے بحوالہ ابوزید مروی ہے مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ابوزید میرے قریب آکر میری پشت پر ہاتھ پھیرنا۔ میں نے آپ کی پشت مبارک پر ہاتھ پھیرا اور مہر نبوت پر انگلی رکھی۔۔۔۔ (حدیث)(5) ابن حبان اور حاکم نے اسے بھی صحیح لکھا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۲۲) استیعاب (۳۰۱۶) تجرید (۱۶۹/۲)\n(2) جامع المسانید (۸۱/۴)\n(3) مسند احمد (۳۴۰/۵) جامع المسانید (۸۳/۱۴)\n(4) مسند احمد (۳۴۱/۵) المستدرک (۱۳۹/۴) المصنف لعبد الرزاق (۱۹۴۶۲) مجمع الزوائد (۳۷۸/۹) المعجم الکبیر (۲۸/۱۷)\n(5) مسند احمد (۳۴۱/۵) جامع المسانید (۸۳/۱۴)"}],[9906,"§۹۹۴۳ ۔ ابوزید بن الضحاک\nنام ثابت ہے۔"],[9907,"§۹۹۴۴ ۔ ابوزید بن عُبید\nنام سعد ہے۔"],[9908,"§۹۹۴۵ ۔ ابوزید بن عمرو بن حدیدہ\nنام قطبہ ہے۔"],[9909,"§۹۹۴۶ ۔ ابوزید بن غرزہ\nنام عمرو ہے۔ ناموں میں ان حضرات کا تذکرہ ہو چکا ہے سب کا تعلق انصار سے ہے۔"],[9910,"§۹۹۴۷ ۔ ابوزید انصاری خزرجی(1)\nابوزید نحوی بصری کے دادا، بقول حاکم ابو احمد صحابی ہیں اور نحوی کا نام سعید بن اوس بن ثابت بن بشیر بن ابی زید ہے۔ واقدی کا قول ہے: یہ قرآن جمع کرنے والے کے علاوہ ہیں، پہلے بیان ہو چکا ہے کہ ان کی اولاد نہ تھی۔","",{"fn":"(1) اسد الغابہ (۵۹۱۷) استیعاب (۳۰۱۹)"}],[9911,"§۹۹۴۸ ۔ ابوزید بن عمرو الجذامی(1)\nابن اسحاق نے جذامی میں وفد میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۱۶۹/۲)"}],[9912,"§۹۹۴۹ ۔ ابوزید الارحبی\nنام عمرو بن مالک ہے۔ ناموں میں تذکرہ ہوا ہے۔"],[9913,"§۹۹۵۰ ۔ ابوزید انصاری (دوسرے)\nبغوی نے ان کا ذکر کیا ہے اور یہ روایت نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: یعنی خوارج، اللہ تعالیٰ کی طرف بلاتے ہیں، لیکن اللہ تعالیٰ کے کسی حکم کے تابع نہیں، جو ان سے جنگ کرے گا وہ ان سے زیادہ اللہ تعالیٰ کے عہد کو پورا کرنے والا ہوگا۔(1)","",{"fn":"(1) المستدرک (۱۴۷/۲) المعجم الکبیر (۲۹/۱۷) کنز العمال (۳۱۲۵۱) (۳۱۶۰۰)"}],[9914,"§۹۹۵۱ ۔ ابو زید انصاری (دوسرے)\nابن کلبی کا بیان ہے اُحد میں شہید ہوئے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[9915,"§۹۹۵۲ ۔ ابوزید (بے نسبت)\nبغوی نے ان کا ذکر کیا ہے اور بحوالہ غنم بن حویص روایت کی ہے فرمایا: میں نے ابوزید کو فرماتے سنا: میں نے نبی صلی اللہ علیہ وسلم کی معیت میں تیرہ غزوے کیے(1) لیکن امام احمد نے یہ روایت مسند ابوزید بن اخطب انصاری میں نقل کی ہے لیکن ان کی روایت میں لکھا ہے شعبہ بواسطہ تمیم نقل کرتے ہیں میں نے ابوزید کو فرماتے سنا، پھر ان کا ذکر کیا اور نسب نہیں بیان کیا۔","",{"fn":"(1) مسند احمد (۳۴۰/۵)"}],[9916,"§۹۹۵۳ ۔ ابوزید\nفاطمہ بنت قیس اپنی طویل حدیث میں فرماتی ہیں جو مطلقہ (طلاق یافتہ) کے خرچ اور رہائش کے متعلق ہے پھر اللہ تعالیٰ نے مجھے ابوزید یعنی اسامہ بن زید (جو ان کی کنیت ہے) کی بیوی ہونے کا شرف بخشا، اسے مسلم نے بطریق ابوبکر بن ابی جہم بحوالہ فاطمہ نقل کیا ہے۔"],[9917,"§۹۹۵۴ ۔ ابوزید الجرمی(1)\nبقول ابواحمد: صحابی ہیں۔ اس کی سند میں کلام ہے۔ بغوی فرماتے ہیں: مجھے ان کا صحابی ہونا، نہ ہونا معلوم نہیں۔ میں کہتا ہوں: ان کی حدیث بغوی اور طبرانی نے نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: والدین کا نافرمان، احسان جتلانے والا اور شراب کا عادی جنت میں نہیں جائے گا۔(2) عبید بن اسحاق عطار بے حد ضعیف راوی ہے۔ دارقطنی کا قول ہے، العلل میں لکھتے ہیں: اسے یزید بن ابی زیاد نے مجاہد سے نقل کیا ہے کہ ابوسعید خدری سے مروی ہے اور عبدالکریم کا قول ہے: مجاہد سے بحوالہ عبداللہ بن عمرو منقول ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۲۰) تجرید (۱۶۹/۲)\n(2) المعجم الکبیر (۹۳۱/۲۲)"}],[9918,"§۹۹۵۵ ۔ ابوزید الغافقی\nابن مندہ(1) نے ان کا ذکر کیا ہے کہ اہل مصر میں شمار ہوتے ہیں۔ پھر بطریق عمرو بن شراحیل معافری بحوالہ ابوزید غافقی یہ روایت نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مسواکیں تین قسم کی ہیں۔ پیلو، اگر پیلو نہ ہو تو زیتون یہ بھی نہ ہو تو بہن۔ ابووہب کا قول ہے جو اس روایت کے راوی ہیں تم(2) سے مراد زیتون ہے۔ ابن مندہ فرماتے ہیں: غریب ہے ہم اسی سند سے جانتے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۲۳) تجرید\n(2) جامع المسانید (۸۹/۱۴) اسد الغابہ (۴۵۸/۴)"}],[9919,"§۹۹۵۶ ۔ ابوزید\nنبی صلی اللہ علیہ وسلم سے سماع کیا ہے ان سے حسن بصری نے سنا ہے۔ ابن مندہ نے اس بات کا جواز پیش کیا ہے یہ عمرو بن اخطب ہیں۔"],[9920,"§۹۹۵۷ ۔ ابو زید (بے نسبت)\nطبرانی نے الاوسط میں بطریق حسن بن دینار بواسطہ یزید الرشک روایت کی کہ میں نے ابوزید جو صحابی ہیں۔ کو فرماتے سنا: میں نبی صلی اللہ علیہ وسلم کے ساتھ تھا آپ نے ایک شخص کو تہجد میں سورۃ فاتحہ پڑھتے سنا تو کھڑے ہو کر غور سے سننے لگے یہاں تک کہ اس نے سورۃ ختم کر لی پھر فرمایا: پورے قرآن میں اس جیسی سورت نہیں۔ بقول بعض ممکن ہے یہ عمرو بن اخطب ہوں۔"],[9921,"§۹۹۵۸ ۔ ابو زید (بے نسبت)\nابومسلم کجی نے اپنی کتاب السنن میں ان کی حدیث نقل کی ہے ابوزید صحابی رسول صلی اللہ علیہ وسلم نے فرمایا: نبی صلی اللہ علیہ وسلم کا ارشاد ہے ”مسافر اپنے موزوں پر تین دن تین راتیں مسح کرے اور مقیم رات دن مسح کرے“۔"],[9922,"§۹۹۵۹ ۔ ابوزینب بن عوف انصاری(1)\nبقول ابو موسیٰ: ابوالعباس بن عقدہ نے کتاب الموالاۃ میں بطریق علی بن حسن العبدی، سعد سے جو اسکاف ہیں بحوالہ اصبغ بن نباتہ روایت کی ہے کہ سیدنا علی نے کھلے میدان میں لوگوں سے پوچھا: رسول اللہ صلی اللہ علیہ وسلم سے غدیر کے روز جس نے سنا وہ اٹھ کھڑا ہو چنانچہ دس بارہ آدمی کھڑے ہوئے ان میں ابوایوب اور ابوزینب بن عوف بھی تھے، ان سب نے کہا: ہم گواہی دیتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: انہوں نے آپ کا ہاتھ پکڑ کر بلند کر کے فرمایا: کیا تم لوگ گواہی نہیں دیتے کہ میں نے حق پہنچا دیا ہے؟ ہم نے عرض کی: ہم ضرور گواہی دیتے ہیں۔ تو آپ نے فرمایا: جس کا میں دوست اس کا علی دوست(2) اس کی سند میں کئی ایک ایسے راوی ہیں جو رفض کی جانب منسوب ہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۲۶) تجرید (۱۷۰/۲)\n(2) مسند احمد (۴۱۹/۵) المعجم الکبیر (۴۰۵۲) مجمع الزوائد (۱۰۴/۹) جامع المسانید (۹۰/۱۴)"}],[9923,"§۹۹۶۰ ۔ ابوزرعہ بن زنباع\nوہی روح الجذامی ہیں ناموں میں تذکرہ ہوا ہے۔"],[9924,"§۹۹۶۱ ۔ ابو زبید الطائی\nمشہور شاعر ہیں دور نبوی پایا ہے۔ ان کے اسلام لانے میں اختلاف ہے نام حرملہ بن منذر ہے بقول بعض: منذر بن حرملہ بن معدیکرب۔۔۔۔ طائی بقول طبری ابوزبید جاہلیت میں بنی تغلب میں اپنے ماموؤں کے پاس جزیرہ میں مقیم تھا اور دور اسلام میں ولید بن عقبہ بن ابی معیط کی جزیرہ اور کوفہ پر ولایت کے دور میں اس کے پاس چلا گیا تھا۔ ولید اس کے ساتھ دوستی یاری رکھتا رہا یہاں تک کہ وہ مسلمان ہو گیا۔ اسلام میں اس کی حالت اچھی ہو گئی۔ ابو مورع اور اس کے ساتھی ولید پر جاسوس مقرر کرتے، کسی نے ان سے کہہ دیا کہ ولید ابھی ابوزبید کے ساتھ شراب پی رہا ہے یہ لوگ جھٹ سے پہنچے، ولید نے اپنے سامنے رکھی کوئی چیز چار پائی تلے چھپا دی، انہوں نے چار پائی پر جھپٹا مارا اور اس کے نیچے سے ایک صراحی نکال لی جس میں انگور کا رس تھا جسے دیکھ کر یہ لوگ شرمندہ ہو گئے۔ ابن قتیبہ لکھتے ہیں: ابوزبید مسلمان نہیں ہوا تھا بلکہ اپنے مذہب نصرانیت پر ہی مرا تھا۔ مرزبانی کا قول ہے: نصرانی تھا، لمبی عمر پائی تھی بقول بعض ڈیڑھ سو(۱۵۰) سال زندہ رہا، اسلام کا زمانہ پایا لیکن مسلمان نہیں ہوا۔ سیدنا عمر نے اسے اس کی قوم کے صدقات زکوۃ وصول کرنے پر مقرر کیا تھا آپ نے اس کے علاوہ کسی غیر مسلم کو یہ ڈیوٹی نہیں سونپی تھی۔ امیر معاویہ کے دور تک زندہ رہا۔ کوفہ میں ولید بن عقبہ بن ابی معیط کا ہم نشین تھا۔ جب ولید پر یہ تہمت لگائی گئی کہ اس نے شراب پی ہے اور کوفہ کی گورنری سے ہٹا دیا گیا، تو ابو زبید نے کہا: ش معبود (برحق) کی قسم! اگر تلوار کی دھار اور زبان کی گفتگو ہوتی تو نہ میرے صاف گھر کی تلاشی ہوتی اور نہ وہ وہاں آتے اور نہ تیرے درمیان شور و شغب حائل ہوتا”۔ سیدنا علی رضی اللہ عنہ کی شہادت پر مرثیہ کہا: ش ”معزز لوگ جن اخلاق و اوصاف کے مالک ہوتے ہیں وہ ایسے شخص کا خاندان ہے جو دین کا جامع اور پسندیدہ ہے مردوں کی قسموں میں کیا ہی خوب صاحب بصیرت انسان تھا رسول اللہ صلی اللہ علیہ وسلم کے پسندیدہ کے برابر اچھے لوگ نہیں ہو سکتے“۔ یہ اشعار ابوالفرج اصبہانی نے بحوالہ مبرد نقل کیے ہیں مرزبانی نے ان میں سے کچھ بھی نقل نہیں کیا۔ اصبہانی فرماتے ہیں۔ ابوزبید کا فقط تیرہ(۱۳) بالشت لمبا تھا اس کا بھائی اعور عجمی بادشاہوں کا خاص بندہ تھا جب اس کی وفات ہوئی تو ولید بن عقبہ کی قبر کے پاس دفن کیا گیا: جب اشجع سلمی کا وہاں سے گزر ہوا تو اس نے یہ اشعار کہے: ش ”میں ابوزبید کی ہڈیوں کے پاس سے گزرا، جو کھلے میدان میں سرد پڑی تھیں۔ ولید اس کا سچا دوست تھا، اب اس کی قبر ولید کی قبر کی ہم نشین ہے۔“ ابوزبید اپنے اشعار میں شیر کی تعریف کرنے میں بڑی دلچسپی لیتا تھا۔ جس کا سیدنا عثمان رضی اللہ عنہ کے ساتھ ایک واقعہ بھی ہے بقول بعض: اس کی قوم اسے کہنے لگی: ہمیں خدشہ ہے کہ تمہاری شیر کی تعریف کی وجہ سے عرب ہمیں گالیاں دیں گے۔ چنانچہ اس نے شیر کی تعریف میں اشعار کہنے چھوڑ دیے۔ مرزبانی لکھتے ہیں: ولید کی وفات اس سے پہلے ہو گئی تو یہ اس کی قبر پر سے گزرا تو کہا: ش ”اے قبر والے سلام ہو جس کی ملاقات کے درمیان قبر حائل ہو گئی ہے اے مجھے چھوڑنے والے! جب میں تیری ملاقات کے لئے آتا تھا تو تیری عادت بے رخی کی تو نہ تھی“۔"],[9925,"§۹۹۶۲ ۔ ابوزبیر (بیت المقدس کے مؤذن)\nدور نبوی صلی اللہ علیہ وسلم پایا ہے، دور فاروقی میں اذان دیتے تھے ابواحمد الحاکم نے الکنی میں روایت کی ہے کہ ابوزبیر کا قول ہے: ہمارے پاس عمر بن خطاب رضی اللہ عنہ آئے، مجھ سے فرمانے لگے: جب اذان دیا کرو تو تسلسل سے دیا کرو اور جب اقامت کہا کرو تو جلدی سے کہا کرو۔"],[9926,"§۹۹۶۳ ۔ ابوزہراء قشیری(1)\nابن عساکر نے الکنی میں ان کا ذکر کیا ہے کہ ان لوگوں میں سے ہیں جنہوں نے دور نبوی صلی اللہ علیہ وسلم پایا ہے اور فتح دمشق میں شریک ہوئے۔ اور اہل ثنیہ اور حوران کی صلح کے لئے سیدنا یزید بن ابی سفیان رضی اللہ عنہ کی جانب سے دور فاروقی میں مامور ہوئے پھر بطریق سیف بن عمر فتوح میں یہ روایت نقل کی ہے کہ یزید بن ابی سفیان رضی اللہ عنہ نے فتح دمشق کے بعد ایک لشکر میں دحیہ بن خلیفہ کلبی اور ابوزھراء کو ثنیہ اور حوران کی طرف دمشق کی صلح کے لئے تذمر بھیجا۔ اور اس مہم کی فتح کا بندوبست بھی انہی کے سپرد ہوا۔ ابوزھراء کے بھائی کا پاؤں فتح دمشق کے معرکہ میں کٹ چکا تھا۔ جب بنو قشیر نے بنی جعدہ کی ہجو کی تو اس پر فخر کیا۔ جس کا جواب انہیں نابغہ جعدی نے دیا پھر وہ اشعار نقل کیے۔ پھر سیف نے دمشق میں شراب پینے والوں کا واقعہ نقل کیا کہ سیدنا عمر نے انہیں حد لگائی۔ جس کے بارے میں ابوزھراء نے کہا: ش ”میں نے صبر سے کام لیا بے صبری نہیں کی اگرچہ میرے بھائی مر گئے حالانکہ میں تو ایک دن بھی شراب سے باز نہ رہ سکتا تھا امیر المومنین نے اسے موت کے گھاٹ اتار دیا، اب اس کے یار انگور کا رس نکالنے والوں کے پاس بیٹھ کے روتے ہیں۔“","",{"fn":"(1) تجرید (۱۶۸/۲)"}],[9927,"§۹۹۶۴ ۔ ابو زیاد(1)\nمولا آل دراج الجمحیین۔ دور نبوی پایا ہے مسدد نے اپنی مسند کبیر میں صحیح سند سے بواسطہ خالد بن معدان بحوالہ ابوزیاد مولا آل درّاج روایت کی ہے فرمایا: مجھے یہ بات نہیں بھولتی کہ صدیق اکبر جب نماز پڑھنے لگتے، تو اپنی داہنی ہتھیلی سے بائیں کلائی کو ہاتھ کے جوڑ (گٹے) کے ساتھ ملا کر پکڑتے۔ ابن عساکر نے یہ جواز پیش کیا ہے کہ یہ ربیعہ بن دراج کے مولا ہو سکتے ہیں۔ پھر اس ربیعہ کا نسب بیان نہیں کیا۔ میں کہتا ہوں: میں نے ربیعہ بن دراج کا تذکرہ اور ان کا نسب حرف راء کی قسم اول میں بیان کیا ہے۔","",{"fn":"(1) تجرید (۱۶۹/۲)"}],[9928,"§۹۹۶۵ ۔ ابوزید قیس بن عمرو ہمدانی\nناموں ذکر ہوا ہے۔"],[9929,"§۹۹۶۶ ۔ ابوزرعہ فزعی(1)\nابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے کہ ابن طرخان نے صحابہ میں ان کا ذکر کیا ہے اور ان کی یہ حدیث نقل کی ہے کہ نبی صلی اللہ علیہ وسلم نے انہیں جھنڈا باندھ کر دیا تھا۔(2) (حدیث) یہ غلطی لفظی تبدیلی سے پیدا ہوئی درست ابو زویبعہ ہے۔ حرف راء میں ان کا نسب بھی قلمبند ہوا ہے، ان کا نام عبداللہ بن عبدالرحمن ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۰۴) تجرید (۱۶۸/۲)\n(2) جامع المسانید (۷۰/۱۴) اسد الغابہ (۴۵۲/۴)"}],[9930,"§۹۹۶۷ ۔ ابوزرعہ(1)\nمولا مقداد بن اسود، بقول ابو عمر ان کا نام عبد الرحمن ہے، جو تابعی ہیں اور ان کی حدیث مرسل ہے۔ امام بخاری رحمہ اللہ(2) فرماتے ہیں: ان کی حدیث منقطع ہے۔ میں کہتا ہوں: ابو عمر سے پہلے مجھے کسی کا حوالہ نہیں ملا کہ اس نے ان کا صحابہ رضی اللہ عنہم میں ذکر کیا ہو۔ ان سے ابو ہلال راسبی نے روایت کی ہے جو قتادہ اور ان کے طبقہ سے روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۰۵) تجرید (۱۶۹/۲)\n(2) التاریخ الکبیر (۳۵۶/۵)"}],[9931,"§۹۹۶۸ ۔ ابوزید عامر (عمر) بن حدیدہ\nابو عمر نے انصار میں سے ابوزید کنیتوں والوں میں ان کا ذکر کیا ہے جبکہ یہ وہ ابوزید ہیں جن کا نام قطبہ بن عامر بن حدیدہ ہے۔"],[9932,"§۹۹۶۹ ۔ ابوزید انصاری\nبغوی نے ان میں اور ابوزید عمرو بن اخطب میں فرق کیا ہے جو عروہ (عزرہ) بن ثابت کے دادا ہیں، پھر ان کے حالات میں حدیث تمیم بن حویص روایت کی ہے کہ میں نے ابوزید کو فرماتے سنا: میں نے رسول اللہ صلی اللہ علیہ وسلم کی معیت میں تیرہ(۱۳) غزووں میں شرکت کی۔ اور عروہ (عزرہ) کے دادا کے حالات میں یہ حدیث نقل کی ہے: ”ہمیں نبی صلی اللہ علیہ وسلم نے نماز پڑھائی پھر منبر پر تشریف فرما ہوئے اور ظہر تک خطبہ دیا“۔ (حدیث) امام احمد رحمہ اللہ نے یہ دونوں حدیثیں مسند ابی زید عمرو بن خطب میں نقل کی ہیں۔"],[9933,"§۹۹۷۰ ۔ ابوزبید بن الصلت(1)\nابن مندہ نے ان کا ذکر کیا ہے اور مراد زبید کے والد کو لیا ہے، اس وقت عنوان صلت بن معدیکرب کندی کا ہوگا۔ مناسب تھا جب انہوں نے انہیں حرف کنیت سے تعبیر کیا ہے تو ابوزبید الصلت کہتے ہیں لیکن ابن مندہ کا یہ اکثر استعمال ہے جسے میں کئی بار بیان کر چکا ہوں۔","",{"fn":"(1) اسد الغابہ (۵۹۲۸) تجرید (۱۷۰/۲)"}],[9934,"§۹۹۷۱ ۔ ابوسالم حنفی ثمّ سُحَیمی\nابن السکن نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور پھر ام سالم سے بحوالہ ان کے خاوند ابو سالم سے روایت نقل کی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو تین بار فرماتے سنا: فلاں کی اولاد کے لیے ہلاکت ہے۔"],[9935,"§۹۹۷۲ ۔ ابوسائب\nعثمان بن مظعون جمحی، نام سے مشہور ہیں، سابقین اولین سے ہیں۔ ناموں میں تذکرہ ہو چکا ہے۔"],[9936,"§۹۹۷۳ ۔ ابوسائب(1)\nیزید عمر کے بھانجے، ناموں میں ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۲۹) تجرید (۱۷۰/۲)"}],[9937,"§۹۹۷۴ ۔ ابوسائب انصاری\nبقول بعض ثقفی گردم کے والد، ان کے بیٹے کے حالات میں ان کا ذکر ہوا ہے۔"],[9938,"§۹۹۷۵ ۔ ابوسائب ثقفی\nنام مالک ہے، بقول بعض: زید یا یزید ہے، میم میں ان کا ذکر ہوا ہے۔"],[9939,"§۹۹۷۶ ۔ ابوسائب(1)\nصحابہ رضی اللہ عنہم میں ان کا ذکر ملتا ہے، لیکن میں انہیں نہیں جانتا یہ ابوعمر کا قول ہے۔ مسند بقی بن مخلد میں ابو سائب بے نسبت کی دو حدیثیں ہیں، لگتا ہے انہی میں کے ایک ہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۳۲) استیعاب (۳۰۲۴)"}],[9940,"§۹۹۷۷ ۔ ابوسائب(1)\nمولا غیلان بن سلمہ ثقفی۔ ابو علی جیانی نے اپنے استدراک میں ان کا ذکر کیا ہے کہ عروہ بن سلمہ کا بیان ہے کہ ان کے والد ابو سائب مولا غیلان نے انہیں حدیث سنائی۔","",{"fn":"(1) اسد الغابہ (۵۹۳۰)"}],[9941,"§۹۹۷۸ ۔ ابوسائب(1)\nایک صحابی رسول صلی اللہ علیہ وسلم ہیں۔ ابن مندہ نے ان کا ذکر کیا ہے کہ اہل مدینہ میں شمار ہوتے ہیں، پھر بطریق عیاش سند بحوالہ ابو سائب ایک صحابی کی روایت نقل کی ہے، فرمایا: ایک شخص نے آ کر نماز پڑھی اور رسول اللہ صلی اللہ علیہ وسلم اسے دیکھ رہے تھے جب وہ نماز مکمل کر چکا آپ نے تین بار فرمایا: جاؤ نماز پڑھو۔ (حدیث)(2) ابونعیم ان کا تعاقب کرتے ہوئے لکھتے ہیں: محفوظ اسحاق بن عبد اللہ بن ابی طلحہ کی روایت ہے۔ داؤد بن قیس اور محمد بن غیلان سب علی بن یحییٰ سے وہ اپنے والد سے وہ اپنے چچا رفاعہ بن رافع کے حوالہ سے نقل کرتے ہیں۔ ممکن ہے اس حدیث میں علی بن یحییٰ کے دو شیخ (استاد) ہوں۔","",{"fn":"(1) اسد الغابہ (۵۹۳۱)\n(2) ابوداؤد کتاب الصلاۃ (۸۵۷، ۸۵۸) ترمذی کتاب الصلاۃ (۳۰۲) نسائی کتاب السہو (۱۳۱۲) ابن ماجہ کتاب الطہارۃ (۴۹۰) مسند احمد (۳۴۰/۴) جامع المسانید (۹۶/۱۴)"}],[9942,"§۹۹۷۹ ۔ ابوسبرہ الجعفی(1)\nوہی یزید بن مالک۔ محمد بن عبد اللہ بن نمیر نے ان کا نام نقل کیا ہے اور ان کی حدیث ان کے بیٹے عبدالرحمن بن سبرہ کے حالات میں بیان ہو چکی ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۳۳) تجرید (۱۷۰/۱)"}],[9943,"§۹۹۸۰ ۔ ابوسبرہ بن حارث(1)\nبقول بعض: ابو سبرہ سین کے بجائے ھاء۔ الف میں ان کا ذکر ہو چکا ہے اور بعض کا انہیں ابواسیرہ کا کہنا بھی بیان ہوا ہے۔","",{"fn":"(1) تجرید (۱۷۱/۱)"}],[9944,"§۹۹۸۱ ۔ ابوسبرہ بن ابی رہم(1)\nبن عبد العزی بن ابی قیس بن عبدود۔۔۔ قرشی عامری۔ اسلام کی طرف سبقت کرنے والوں میں سے ہیں۔ دوسری مرتبہ کی ہجرت میں حبشہ گئے ان کے ساتھ ام کلثوم بنت سہیل بن عمرو بھی تھیں۔ سب کا اتفاق ہے کہ بدر میں شریک ہوئے والدہ کا نام برد بنت عبدالمطلب ہے جو رسول اللہ صلی اللہ علیہ وسلم کی پھوپھی ہیں۔ اور ابو سلمہ بن عبد الاسد کے ماں شریک بھائی ہیں۔ زبیر بن بکار کا بیان ہے رسول اللہ صلی اللہ علیہ وسلم کی وفات کے بعد مکہ مقیم ہو گئے جہاں سیدنا عثمان رضی اللہ عنہ کی خلافت میں فوت ہوئے۔ زبیر لکھتے ہیں: ہمیں معلوم نہیں کہ ان کے علاوہ کوئی بدری صحابی مکہ آکر بس گیا ہو۔","",{"fn":"(1) اسد الغابہ (۵۹۳۵) استیعاب (۳۰۲۵)"}],[9945,"§۹۹۸۲ ۔ ابوسبرہ (بے نسب)(1)\nابن مندہ نے ان کا ذکر کیا ہے اور بطریق یوسف بن سفر روایت کی ہے کہ اوزاعی نے فرمایا مجھ سے قزعہ نے بیان کہ ہمارے پاس صحابی رسول صلی اللہ علیہ وسلم ابوسیرہ تشریف لائے۔ میں نے ان سے عرض کی: اللہ آپ پر رحم فرمائے مجھے نبی صلی اللہ علیہ وسلم سے سنی ہوئی کوئی حدیث سنائیے۔ انہوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: ”جس نے فجر کی نماز پڑھ لی وہ اللہ تعالیٰ کی ذمہ داری میں ہے سو اللہ تعالیٰ سے ڈرو وہ تم سے اپنی ذمہ داری کا مطالبہ کرے۔“(2)","",{"fn":"(1) اسد الغابہ (۵۹۳۷) تجرید (۱۷۱/۱)\n(2) جامع المسانید (۱۰۰/۱۴) اسد الغابہ (۴۶۲/۴)"}],[9946,"§۹۹۸۳ ۔ ابوسبرہ الجہنی\nمعبد بن عوسجہ، تذکرہ ہو چکا ہے۔"],[9947,"§۹۹۸۴ ۔ ابوسبرہ\nعیسیٰ بن سبرہ کے دادا۔ حبان میں ذکر ہوا ہے۔ بغوی فرماتے ہیں: میرے خیال میں مدینہ کے رہائشی ہیں، پھر ان کی حدیث بطریق ابن انیس، بواسطہ عیسیٰ بن سبرہ انہوں نے اپنے والد سے بحوالہ اپنے دادا نقل کی۔"],[9948,"§۹۹۸۵ ۔ ابوالسبع بن عبدقیس انصاری\nبدر میں شریک تھے، ان کا نام ذکوان ہے، پہلے بیان ہو چکا ہے۔"],[9949,"§۹۹۸۶ ۔ ابوسرَوعہ نوفلی(1)\nعقبہ ابن عامر ہیں، یہ اکثریت کا قول ہے ناموں میں ان کا ذکر ہوا ہے۔ بقول بعض ان کے بھائی ہیں، ان کا نام رث ہے یہ عدوی کا قول ہے ان کا بیان ہے: فتح مکہ میں مسلمان ہوئے، ایسا ہی زبیر وغیرہ کا کہنا ہے۔ سروعہ کے سین میں لاف ہے، اکثریت فتح (زبر) کی قائل ہے ایک قول زیر کا ہے را ساکن ہے ادھر حمیدی کا گمان ہے کہ انہوں نے الدارقطنی کے قلم عین پر پیش لکھا دیکھا ہے۔ شاید عدم نقطہ (نقطہ نہ ہونے) کی علامت تھی جسے وہ پیش سمجھ بیٹھے۔","",{"fn":"(1) اسد الغابہ (۵۹۳۹) استیعاب (۲۰۲۸) تجرید (۱۷۱/۲)"}],[9950,"§۹۹۸۷ ۔ ابوشریحہ(1)\nبروزن عظیمہ، حذیفہ بن اسید، پہلے ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۴۰) استیعاب (۳۰۲۹) تجرید (۱۷۱/۲)"}],[9951,"§۹۹۸۸ ۔ ابوسعاد جہنی(1)\nبقول بعض: ان کا نام جابر بن اسامہ ہے، ناموں میں ذکر ہو چکا ہے کہ ابن ماکولا(2) نے ان کا نام بتایا ہے۔ ایک قول کا یہ بعد والے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۴۲) استیعاب (۳۰۳۰) تجرید (۱۷۱/۲)\n(2) الاکمال (۳۰۶/۴)"}],[9952,"§۹۹۸۹ ۔ ابوسعاد الحمصّی(1)\nابوزرعہ نے کتاب الزھد میں روایت نقل کی ہے کہ ابن ابی عوف کا قول ہے: سیدنا ابودرداء ابوسعاد کے پاس سے گزرے، جو صحابی رسول صلی اللہ علیہ وسلم تھے۔ ابو سعاد فرمانے لگے: سبحان اللہ! نہ کچھ بیچتے ہیں اور نہ خریدتے ہیں۔ ابودرداء بولے: ”جس نے اپنی دنیا کی چیزیں جمع کیں اس نے اپنی آخرت کو نقصان پہنچایا“۔ ابو عمر نے ان میں اور جھنی میں فرق کیا ہے کہ یہ حمص فروکش ہوئے اور ان کی حدیث نقل کی۔","",{"fn":"(1) اسد الغابہ (۵۹۴۲) تجرید (۱۷۱)"}],[9953,"§۹۹۹۰ ۔ ابوسعاد(1)\nیہ جہینہ کے ہیں۔ روح بن قاسم بواسطہ اسمعیل بن امیہ اسی سند سے بحوالہ عقبہ بن عامر روایت کرتے ہیں۔ میں کہتا ہوں: عقبہ بن عامر مشہور صحابی ہیں جن کا تذکرہ ناموں میں ہوا۔ اس کی کنیت کے بارے میں اختلاف ہے، ابوحماد اکثریت کا قول ہے۔ ابو عمر/ابوعامر/ابوسعاد وغیرہ مختلف اقوال ہیں۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۵۹۴۱) تجرید (۱۷۱/۲)"}],[9954,"§۹۹۹۱ ۔ ابوسعدان (شامی، بے نام و نسب)(1)\nابو عمر نے ان کا ذکر کیا کہ محمول نے ان سے ہجرت کے بارے میں مرفوع حدیث روایت کی ہے۔(2) ذہبی رحمہ اللہ کا قول ہے: اس کی سند کمزور ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۴۹) استیعاب (۳۰۳۵) تجرید (۱۷۲/۱)\n(2) اسد الغابہ (۱۶۲)"}],[9955,"§۹۹۹۲ ۔ ابوسعد انصاری ثم حارثی\nمحیصہ بن مسعود۔"],[9956,"§۹۹۹۳ ۔ ابوسعد عیاض بن زہیر الفہری"],[9957,"§۹۹۹۴ ۔ ابوسعد سلمہ بن اسلم بن حریش\nسلمہ بن اسلم بن حریش، ان سب کا ذکر ناموں میں ہوا ہے۔"],[9958,"§۹۹۹۵ ۔ ابوسعد الخیر(1)\nبقول بعض: ابوسعید الخیر۔ ابن السکن: صحابی ہیں۔ بقول بعض: نام عمرو ہے۔ ابواحمد الحاکم: مجھے ان کا نام ونسب معلوم نہیں۔ پھر بیان کرتے ہیں: یہ ابوسعید الانماری ہیں، حالانکہ ایسا نہیں۔ کیونکہ ان کی دو حدیثیں اس حدیث کے علاوہ ہیں جس میں انماری کے حالات میں اختلاف ہے۔ بلکہ یہ ابوسعد یا ابوسعید ہیں چنانچہ ترمذی ”العلل المفردہ“ ابن ابی داؤد ”الصحابہ“ میں اور ابواحمد الحاکم ان سے ایک اور طریق سے پھر یہ سب بطریق ابو فروہ رہاوی، معقل کندی، عبادہ بن نسی بحوالہ ابوسعید روایت کرتے ہیں۔ فرمایا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ نے رات میں روزہ رکھنا فرض نہیں کیا ہے جس نے رکھا اس نے مشقت کی اس کا کوئی اجر نہیں ہے“۔(2) یہی روایت دولابی نے الکنی میں ایک اور سند سے بحوالہ ابوفروہ نقل کی ہے کہ ابوسعید الخیری سے مروی ہے، حاکم کی روایت میں ہے ابوسعد الخیری سے منقول ہے ابن مندہ نے یہ روایت نقل کر کے کہا: غریب ہے، ہمیں اسی سند سے معلوم ہے۔ ترمذی کا قول ہے: میں نے محمد یعنی امام بخاری رحمہ اللہ سے پوچھا تو انہوں نے فرمایا: میں اس عبادہ بن نسی سے ناواقف ہوں جس نے ابو سعد الخیر سے یہ حدیث سنی ہے اور دولابی الکنی میں بطریق ابو فراس شعبانی روایت کرتے ہیں کہ یہ لوگ امیر معاویہ کے دور میں غزوہ قسطنطنیہ میں تھے اور یزید بن شجرہ ہمارے امیر تھے۔ ہمارے پاس سے ابوسعد الخیر صحابی رسول صلی اللہ علیہ وسلم گزرے پھر ایک واقعہ نقل کیا۔ ابوسعد الخیر نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: ”جن چیزوں کو آگ پر پکایا گیا ہو ان کے کھانے سے وضو کر لیا کرو“۔۔۔۔ (حدیث)(3) اسے امام حاکم رحمہ اللہ نے اسی سند سے نقل کیا ہے، اس کے سیاق میں فرماتے ہیں: میں ابوسعد الخیر کے پاس تھا، اور پھر فرماتے ہیں: ابوسعید الخیر۔ اکثریت ابوسعد بلا شک کہتی ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۴۴) جمع الجوامع (۴۹۶۹) تجرید (۱۷۲/۲)\n(2) کنز العمال (۲۳۹۲۵) جمع الجوامع (۴۹۶۹)\n(3) المعجم الکبیر (۷۷۶/۲۲) مجمع الزوائد (۲۴۹/۱۰) الکنی للدولابی (۳۵/۱) جامع المسانید (۱۱۹/۱۴)"}],[9959,"§۹۹۹۶ ۔ ابوسعد انصاری زرقی(1)\nسعید بن عبدالعزیز اور حاکم کا قول ہے: صحابی ہیں، ابن ماجہ بطریق یونس بن میسرہ یہ روایت کرتے ہیں کہ ہم لوگ ابوسعد زرقی صحابی رسول کے ساتھ قربانی کے جانور خریدنے گئے۔ پھر وہ حدیث ذکر کی۔(2) ابن ابی حاتم بحوالہ اپنے والد ان کے صحابی ہونے میں متردد ہے۔ طبرانی کی روایت میں یونس کے مذکورہ طریق سے مروی ہے میں ابوسعد الخیر کے ساتھ نکلا، اگر یہ روایت محفوظ ہے تو یہ سابقہ شخصیت ہیں، ابوسعید اسامہ بنت یزید کے خاوند کے حالات میں ان کا ذکر ہوگا۔","",{"fn":"(1) اسد الغابہ (۵۹۴۳) تجرید (۱۷۲/۲)\n(2) اسد الغابہ (۴۶۵/۴)"}],[9960,"§۹۹۹۷ ۔ ابوسعد الانماری\nبقول بعض: ابوسعید، تذکرہ ہونا ہے۔"],[9961,"§۹۹۹۸ ۔ ابوسعد ساعدی(1)\nابن ابی داؤد نے اور ان کے اتباع میں ابن شاہین نے صحابہ میں ان کا ذکر کیا ہے، اور ان سے بطریق ابو عمرو اوزاعی، یحییٰ بن ابی کثیر، قتادہ، ابی قتادہ روایت کی ہے کہ سعد ساعدی نے ایک شخص کو عصر کے بعد نفل پڑھتے دیکھا تو فرمایا: اس وقت (نماز نفل) نہ پڑھو، کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”عصر کی نماز کے بعد (نفل) نماز نہ پڑھا کرو“۔(2) الدارقطنی نے العلل میں ان کا نام درست لکھا ہے ابواسید ساعدی، ابن ابی داؤد ان کے بارے وہم ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۴۶) تجرید (۱۷۲/۲)\n(2) جامع المسانید (۱۲۰/۱۴) اسد الغابہ (۴۶۵/۴)"}],[9962,"§۹۹۹۹ ۔ ابوسعد بن فضالہ انصاری(1)\nبقول بعض: ابن ابی فضال۔ ایک قول ہے: ابوسعید بن فضال بن ابی فضال۔ ابن سعد نے اہل خندق کے طبقہ میں ان کا ذکر کیا ہے۔ ابن السکن فرماتے ہیں: غیر معروف ہیں۔ ترمذی، ابن ماجہ، ابن خزیمہ، ابن حبان اور حاکم نے بطریق عبدالحمید بن جعفر، انہوں نے اپنے والد سے بواسطہ زیاد بن مینا بحوالہ ابوفضالہ جو صحابی ہیں روایت کی ہے علی بن مدینی کا قول ہے: اس کی سند بہتر ہے، اکثریت کے ہاں یہ نام عین کے سکون سے لکھا ہے، جس پر ابواحمد الحاکم کا بھروسہ ہے، فرماتے ہیں: یہ صحابی ہیں لیکن مجھے ان کا نام ونسب یاد نہیں۔ ابن ماجہ میں دونوں طرح ہے۔ ترمذی میں یاء کی زیادتی سے لکھا ہے تجرید میں ذہبی لکھتے ہیں: ابوسعد بن ابی فضالہ کی، ابواحمد کی کتاب الکنی میں ایک متصل حدیث ہے، پھر فرماتے ہیں: ابوسعید بن فضالہ۔ بقول بعض: ابوسعد، ترمذی نے ریاء میں ان کی اسی طرح ایک حدیث نقل کی ہے اور انہیں دو شخص قرار دیا ہے، باوجود یکہ جو حدیث حاکم نے روایت کی وہی ترمذی نے نقل کی ہے۔ اسی طرح حاکم کی کتاب الکنی میں عین کے سکون سے ہے، بغوی الکنی میں لکھتے ہیں: ابوسعد بن ابی فضالہ انصاری، مدینہ کے رہائشی تھے پھر ان کی حدیث بیان کی۔ فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”اللہ تعالیٰ جب اولین و آخرین کو قیامت کے روز جس میں کوئی شک نہیں جمع فرمائے گا تو ایک اعلان کرنے والا اعلان کرے گا جس نے کسی کو کسی عمل میں شریک کیا ہے وہ اس سے اس عمل کا ثواب مانگے اللہ تعالیٰ شریکوں کے شرک سے بے نیاز ہے۔“(2) ابن ابی خیثمہ نے ایسا ہی نقل کیا ہے، فوائد صولی میں لکھا ہے: یحیی بن معین اس سند سے بحوالہ ابوسعید بن فضالہ بن ابی فضالہ روایت کرتے ہیں۔ حافظ ابن عساکر کا قول ہے: یہ وہم ہے، درست پہلی سند ہے۔ ایسا ہی امام احمد نے محمد بن ابی بکر سے نقل کیا ہے۔ ان کی سہیل بن عمرو سے روایت ہے، اسے بھی ابن سعد نے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۴۷) تجرید (۱۷۳/۲)\n(2) ترمذی کتاب التفسیر باب من سورۃ الکہف (۳۱۵۴) ابن ماجہ کتاب الزھد باب الریاء والسمعۃ (۴۲۰۳) مسند احمد (۴۶۶/۳)"}],[9963,"§۱۰۰۰۰ ۔ ابوسعد بن وہب نضری(1)\nاز بنی نضیر، جو قریظہ کے بھائی ہیں۔ مغازی میں ابن اسحاق کا قول ہے: بنی نضیر میں سے سوائے دو آدمیوں کے کوئی مسلمان نہیں ہوا۔ یامین بن عمرو بن کعب اور ابوسعد بن وہب، ان دونوں نے اپنے مال محفوظ کر لیے۔ پھر ابن سعد نے بسند واقدی ان کی حدیث نقل کی ہے، فرمایا: میں اس وقت موجود تھا جب رسول اللہ صلی اللہ علیہ وسلم نے مہروز کے پانی کی تقسیم کی تھی کہ اوپر والا ٹخنوں تک پہنچنے پر پانی کو روکے، پھر چھوڑ دے۔(2) ابو عمر کے کلام میں ہے وہ معرکہ قریظہ کے روز رسول اللہ صلی اللہ علیہ وسلم کے پاس اتر آئے تھے۔ یہ غلط ہے جس کا تعاقب رشاطی نے کیا ہے کیونکہ بنی نضیر کا واقعہ بنی قریظہ کے واقعہ سے بہت مدت پہلے کا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۴۸) تجرید (۱۷۳/۲)\n(2) ابوداؤد کتاب الاقضیۃ باب ابواب من القضاء (۳۶۳۸) ابن ماجہ کتاب الرھون باب الشرب فی الادویۃ (۲۴۸۱) جامع المسانید (۱۱۶/۱۴) اسد الغابہ (۴۶۶/۴)"}],[9964,"§۱۰۰۰۱ ۔ ابوسعد انصاری(1)\nابن ابی فدیک نے ان کی حدیث بواسطہ یحیی بن ابی خالد بحوالہ ابوسعد نقل کی ہے۔ ایسا ہی ابوعمر کا مختصر قول ہے۔ ابن مندہ فرماتے ہیں: اسے محمد بن اسمعیل بن فدیک نے یحییٰ بن ابی خالد سے بواسطہ ابن ابی سعد انصاری بحوالہ اپنے والد نبی صلی اللہ علیہ وسلم سے نقل کیا ہے: ”ندامت و پشیمانی بھی توبہ ہے۔“(2) میں کہتا ہوں: یہ روایت حکیم ترمذی حنفی نے ”نوادر الاصول“ میں بطریق ابن ابی فدیک اسی سند سے ان الفاظ میں نقل کی ہے: ”گناہ سے توبہ کرنے والا ایسا ہے جیسا بے گناہ اور ندامت خود توبہ ہے“۔ ابو نعیم اعتماد سے لکھتے ہیں: ”یہ پہلے والے نفری ہی ہیں“۔ جو بہتر نہیں، اور ابوبکر نے یقین سے لکھا ہے کہ انہوں نے ہی یہ حدیث نقل کی ہے: ”قربانی کا بہترین جانور کالی ناک والا دنبہ ہے“۔ یہ بھی صحیح نہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۴۳) تجرید (۱۷۲/۲)\n(2) مجمع الزوائد (۱۹۹/۱۰) المعجم الکبیر (۱۷۷۵/۲۲) حلیۃ الاولیاء (۳۹۸/۱۰)"}],[9965,"§۱۰۰۰۲ ۔ ابوسعد بن اوس(1)\nبن معلی ابن لوذان بن حارثہ بن عدی انصاری اوسی۔ طبری نے ذیل میں ان کا ذکر کیا ہے کہ ۹۴ ھ میں فوت ہوئے، ان کا نام حارث ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۵۵) تجرید (۱۷۳/۲)"}],[9966,"§۱۰۰۰۳ ۔ ابوسعید خدری\nسعد بن مالک بن سنان۔"],[9967,"§۱۰۰۰۴ ۔ ابوسعید عبشمی\nعبدالرحمن بن سمرہ۔"],[9968,"§۱۰۰۰۵ ۔ ابوسعید سعیدی\nخالد بن احیہ سعد بن عاص۔"],[9969,"§۱۰۰۰۶ ۔ ابوسعید انصاری\nیزید بن ثابت بن ودیعہ۔"],[9970,"§۱۰۰۰۷ ۔ ابوسعید مخزومی\nالمسیب ابن حزن بن ابی وہب۔"],[9971,"§۱۰۰۰۸ ۔ ابوسعید مخزومی\nعمرو بن حریث۔"],[9972,"§۱۰۰۰۹ ۔ ابوسعید کاتب وحی\nزید بن ثابت انصاری خزرجی۔"],[9973,"§۱۰۰۱۰ ۔ ابوسعید رافع بن المعلی بدری\nان سب حضرات کا تذکرہ ناموں میں ہو چکا ہے۔ بقول بعض: ابوسعید بن معلی کا نام حارث بن اوس بن معلی ہے۔ ایک قول ہے: حارث بن نفیح، بقول بعض: یہ سابقہ شخصیت کا نام ہے۔"],[9974,"§۱۰۰۱۱ ۔ ابوسعید بن معلی انصاری\nدوسرے ہیں۔ امام بخاری رحمہ اللہ نے ان کی حدیث نقل کی ہے جو بروایت حفص بن عاصم ان سے مروی ہے، ان سے عبید بن حنین بھی روایت کرتے ہیں۔ بقول ابو عمر: جس نے انہیں رافع بن معلی کہا اسے وہم ہوا ہے کیونکہ وہ بدر میں شہید ہوئے تھے۔ یہ بات حارث بن نفیح بن معلی کے بارے میں سب سے صحیح ہے۔ مؤرخین نے ان کی تاریخ وفات ۷۴ ھ یا ۷۵ ھ لکھی ہے۔ ان کا کہنا ہے: وہ چونسٹھ(۶۴) سال زندہ رہے۔(1) میں کہتا ہوں: یہ غلط ہے، کیونکہ اس سے یہ لازم آتا ہے ان کا یہ واقعہ نبی صلی اللہ علیہ وسلم کے ساتھ بچپنے میں پیش آیا تھا جبکہ حدیث کا سیاق اس کے خلاف ہے۔ اس واسطے کہ صحیح میں ان کی حدیث میں ہے میں نماز پڑھ رہا تھا نبی صلی اللہ علیہ وسلم کا وہاں سے گزر ہوا، آپ صلی اللہ علیہ وسلم نے مجھے بلایا، میں آپ کے پاس اس وقت تو حاضر نہ ہو سکا نماز پڑھنے کے بعد آ گیا۔ (حدیث) ان کی ایک اور حدیث بھی ہے جس کا آغاز اس طرح ہے: ”ہم لوگ بازار جاتے“۔ ابوعمر کا قول ہے: ان کی والدہ کا نام امیمہ بنت قرط بن خنساء ہے۔ بنی سلمہ سے تعلق رکھتی ہیں۔","",{"fn":"(1) بخاری کتاب تفسیر القرآن باب ما جاء فی فاتحۃ الکتاب (۴۴۷۴) کتاب فضائل القرآن باب (۵۰۰۶) ابوداؤد کتاب الصلاۃ باب ما جاء فی فاتحۃ الکتاب (۱۴۵۸) نسائی کتاب الافتتاح (۹۱۲) ابن ماجہ کتاب الادب باب ثواب القرآن (۳۸۷۵) مسند احمد (۴۵۰/۳) (۲۱۱/۴)"}],[9975,"§۱۰۰۱۲ ۔ ابوسعید انصاری(1)\nاسماء بنت یزید بن السکن کے شوہر۔(2) ان کا نام سعید بن عمارہ/عمارہ بن سعید اور عامر بن مسعود بتایا جاتا ہے۔ حاکم نے آخری قول کو فضول لکھا ہے اور کہا ہے عامر بن مسعود دوسرے ہیں جو تابعی ہیں، ان کی کنیت ابوسعید ہے، ابن مندہ کی روایت ہے کہ ابوسعید انصاری مدینہ کے محاصرے کے دن مروان بن الحکم کے پاس سے گزرے تو وہ پچھڑے ہوئے تھے۔ آپ نے فرمایا: ابن الزرقاء اگر مجھے معلوم ہوتا کہ تم ہی وہ (فتنہ پرداز) ہو تو میں تمہارے خلاف چڑھ دوڑتا۔ تو عبد الملک بن مروان نے اس بات کی وجہ سے ان سے بغض رکھنا شروع کر دیا، جب وہ خلیفہ بنا تو انہیں بلا بھیجا، آپ نے فرمایا: ”مجھے اس بارے میں نبی صلی اللہ علیہ وسلم کی وصیت یاد ہے“۔ اس نے پوچھا: وہ کیا ہے؟ آپ نے فرمایا: ”ان کے محسنوں کی بات قبول کرو اور ان کے بروں سے درگزر کرو“۔(3) چنانچہ اس نے انہیں چھوڑ دیا۔ بقول بعض: یہ وہی ابوسعید زرقی ہیں جن کا تذکرہ ہوتا ہے۔ جس پر المزی کا اعتماد ہے، جبکہ ابن مندہ نے دونوں میں فرق کو یقینی کہا ہے، شاید یہی زیادہ درست ہے۔","",{"fn":"(1) نسائی کتاب المساجد (۳۹) باب صلاۃ الذی یمر علی المسجد (۷۲۸)\n(2) اسد الغابہ (۵۹۵۲) استیعاب (۳۰۴۰) تجرید (۱۷۲/۲)\n(3) المعجم الکبیر (۷۷۷/۲۲) مجمع الزوائد (۳۶/۱۰) جامع المسانید (۱۲۸/۱۴) اسد الغابہ (۴۶۷/۴)"}],[9976,"§۱۰۰۱۳ ۔ ابوسعید سعد بن عامر(1)\nبن مسعود زرقی۔ ابن السکن نے ان کا ذکر کیا ہے اور یہ روایت نقل کی ہے کہ عبدالملک بن مروان نے ابوسعید، سعد بن عامر زرقی کی طرف پیام بھیجا۔ بقول بعض ان کی نبی صلی اللہ علیہ وسلم سے ملاقات ہوئی اور آپ سے ہدی (قربانی حج) کے بارے میں پوچھا اور سیدہ عائشہ رضی اللہ عنہا سے روایت کی ہے۔ نسائی بطریق شعبہ بحوالہ ابوسعید زرقی عزل کی حدیث نقل کرتے ہیں۔ ان سے عبداللہ بن مرہ، یونس بن میسرہ اور مکحول شامی روایت کرتے ہیں۔ بقول سعید بن عبد العزیز، صحابی ہیں۔ ایک قول ہے: انہی کو سعید الخیر کہا جاتا ہے۔","",{"fn":"(1) ۹۹۹۱ میں ان کا تذکرہ ہو چکا ہے۔"}]])